  ('cpiuris2025::ecd66573a03ce1addea1a97b5adbf82e', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Ação Civil Pública e Tutela Coletiva', '## Ação Civil Pública e Tutela Coletiva

A ação civil pública pode ser iniciada pelo titular em regime processual comum ou por procedimento especial da ação civil coletiva. A tutela coletiva se dá em duas fases: ação coletiva propriamente dita e ação de cumprimento da sentença genérica.

### Conceitos
- **Ação Civil Pública**: ação processual que visa proteger direitos individuais ou coletivos
- **Tutela Coletiva**: proteção de direitos coletivos por meio de ações judiciais
- **Ação Coletiva Propria**: ação processual que visa proteger direitos coletivos
- **Ação de Cumprimento da Sentença Genérica**: ação processual que visa cumprir a sentença genérica em relação aos direitos tutelados

### Referências legais
- Art. 91 a 100 da Lei 8.078/90
- Art. 127 da Constituição Federal

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre ação civil pública e tutela coletiva
- Conheça as fases da ação coletiva propriamente dita e da ação de cumprimento da sentença genérica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.62 (1)", "page_number": 62, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 91 a 100 da Lei 8.078/90", "Art. 127 da Constituição Federal"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T23:39:52.949017+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=62", "doc_key": "ecd66573a03ce1addea1a97b5adbf82e"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'af569d677a33e5b5fad691ffe39f248490df48a71cb658b8dd73ddd933eeb11b'),
  ('cpiuris2025::f60b51557e558386d4d5d30157e58d1e', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Legitimação do Ministério Público para ações coletivas', '## Legitimação do Ministério Público para ações coletivas

O Ministério Público está legitimado a promover ações coletivas para tutelar direitos individuais homogêneos com interesse social qualificado, mesmo em casos de direitos disponíveis.

### Conceitos
- **Legitimação do Ministério Público**: O direito do Ministério Público de promover ações coletivas para tutelar direitos individuais homogêneos com interesse social qualificado.
- **Interesse Social Qualificado**: A presença de um interesse maior que o individual, que justifica a intervenção do Estado no processo.
- **Direitos Individuais Homogêneos**: Direitos que são semelhantes e podem ser exercidos por várias pessoas, como direito à saúde ou ao trabalho.

### Referências legais
- Art. 127 da Constituição Federal

### Jurisprudência
- RE 163.231/SP
- AI 637.853 AgR/SP
- RE 475.010 AgR/RS
- RE 328.910 AgR/SP
- STF, RE 631111, Rel. Min. Teori Zavascki, Tribunal Pleno

### Dicas de prova
- Entenda a noção de interesse social qualificado e como ela se relaciona com a legitimidade do Ministério Público.
- Conheça os direitos individuais homogêneos e como eles podem ser tutelados coletivamente.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.62 (2)", "page_number": 62, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 127 da Constituição Federal"], "jurisprudence": ["RE 163.231/SP", "AI 637.853 AgR/SP", "RE 475.010 AgR/RS", "RE 328.910 AgR/SP", "STF, RE 631111, Rel. Min. Teori Zavascki, Tribunal Pleno"], "confidence": 0.8, "extracted_at": "2026-05-31T23:40:21.548756+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=62", "doc_key": "f60b51557e558386d4d5d30157e58d1e"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '98c05871043b0d2e7149da293f663911116c6e83bac33f5a2c5af319b739ff6d'),
  ('cpiuris2025::a33339be2fe4838827b64620cca402ae', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Legitimidade do Ministério Público para defender beneficiários do seguro obrigatório (DPVAT)', '## Legitimidade do Ministério Público para defender beneficiários do seguro obrigatório (DPVAT)

O MP possui legitimidade ativa para defender beneficiários do seguro obrigatório, pois é uma de suas funções institucionais. Os direitos difusos e coletivos são tutelados em juízo invariavelmente em regime de substituição processual, enquanto os direitos individuais homogêneos podem ser tutelados por iniciativa do próprio titular ou pelo procedimento especial da ação civil coletiva.

### Conceitos
- **Legitimidade Ativa**: O direito de agir em nome de outrem, com ou sem autorização legal
- **Direitos Difusos e Coletivos**: Direitos que se aplicam a um grupo de pessoas e não têm titular determinado
- **Direitos Individuais Homogêneos**: Direitos que são divisíveis, tem titular determinado ou determinável e são de natureza disponível
- **Substituição Processual**: O procedimento pelo qual um órgão ou entidade substitui outra para a realização de uma ação processual

### Referências legais
- Art. 129, III da CF

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Distinção entre direitos difusos e coletivos e direitos individuais homogêneos
- Legitimidade do MP para defender beneficiários do seguro obrigatório', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.63 (1)", "page_number": 63, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 129, III da CF"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-31T23:40:44.118815+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=63", "doc_key": "a33339be2fe4838827b64620cca402ae"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '32fcbfb3f5a25e0cfb0b6aa7d6192377344bdad3966c9e277965aa15ed170df8'),
  ('cpiuris2025::9a365d9ca4340fae21bf9e994b8b2ab0', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Interesses Sociais e Ministério Público', '## Interesses Sociais e Ministério Público

O Ministério Público tem a incumbência de defender interesses sociais, mas não se confunde com interesses de entidades públicas ou interesse coletivo de particulares. Há casos em que os interesses individuais podem ter força coletiva e representar verdadeiros interesses da comunidade.

### Conceitos
- **Interesses Sociais**: Direitos e valores jurídicos superiores que são comuns a uma comunidade maior de pessoas
- **Ministério Público**: O órgão do Estado responsável por defender os interesses sociais e promover a justiça
- **Interesse Coletivo**: Direito ou valor jurídico que é comum a uma categoria de pessoas, mas não necessariamente a todos os indivíduos dessa categoria
- **Lesão Coletiva**: Dano ou prejuízo causado a um grupo de pessoas, em vez de apenas a um indivíduo

### Referências legais
- CF, art. 127
- CF, art. 129, IX

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre interesses sociais e interesse coletivo de particulares
- Conheça o conceito de lesão coletiva e sua importância no direito processual', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.63 (2)", "page_number": 63, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["CF, art. 127", "CF, art. 129, IX"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T23:42:34.691148+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=63", "doc_key": "9a365d9ca4340fae21bf9e994b8b2ab0"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'fc77de4dd796de81445fb30b67410a1b1f26c5d69b263967b106b69b05d526fa'),
  ('cpiuris2025::e6d1accb1c863e4f1af158570b517f6f', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Legitimidade do Ministério Público para promover ações coletivas', '## Legitimidade do Ministério Público para promover ações coletivas

O Ministério Púbico está legitimado a promover a tutela coletiva de direitos individuais homogêneos quando a lesão transcende os interesses particulares e compromete relevantes interesses sociais.

### Conceitos
- **Legitimidade do Ministério Público**: O Ministério Púbico tem legitimidade para promover ações coletivas quando há interesse social qualificado.
- **Interesse Social Qualificado**: É o caso em que a lesão transcende os interesses particulares e compromete relevantes interesses sociais.
- **Desistência do Processo Coletivo**: Exige motivação adequada, de acordo com o princípio da disponibilidade motivada.

### Referências legais
- Art. 127 da Constituição Federal
- Art. 5º, §3º, da LACP

### Jurisprudência
- RE 163.231/SP
- AI 637.853 AgR/SP
- ...

### Dicas de prova
- Entenda a noção de interesse social qualificado e sua relação com a legitimidade do Ministério Público.
- Conheça o princípio da disponibilidade motivada e sua aplicação na desistência do processo coletivo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.64 (1)", "page_number": 64, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 127 da Constituição Federal", "Art. 5º, §3º, da LACP"], "jurisprudence": ["RE 163.231/SP", "AI 637.853 AgR/SP", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T23:42:52.854887+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=64", "doc_key": "e6d1accb1c863e4f1af158570b517f6f"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '3646972f231992e65550b0a66896dfa09df5cfe139138df33a86a2d31d50de75'),
  ('cpiuris2025::de3720fa08750312a2efc151c6d3433a', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Substituição processual pelo Ministério Público após dissolução judicial de associação', '## Substituição processual pelo Ministério Público após dissolução judicial de associação

A substituição processual pelo Ministério Público é possível após a dissolução judicial de associação, pois o objetivo é proteger os consumidores e não deixar desprotegidas as pessoas com interesse na tutela.

### Conceitos
- **Substituição processual**: A substituição do Ministério Público pelo autor da ação civil pública em casos de dissolução judicial da associação.
- **Dissolução judicial**: Decisão judicial que extingue a associação autora de ação civil pública.
- **Proteção dos consumidores**: O objetivo principal da substituição processual, que é proteger as pessoas com interesse na tutela.

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- REsp 1.113.175/DF
- REsp 1.582.243-SP
- STJ. 4ª Turma. AgInt no REsp 1.582.243-SP

### Dicas de prova
- Entenda a distinção entre desistência infundada e abandono da ação.
- Conheça o objetivo principal da substituição processual, que é proteger os consumidores.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.64 (2)", "page_number": 64, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["REsp 1.113.175/DF", "REsp 1.582.243-SP", "STJ. 4ª Turma. AgInt no REsp 1.582.243-SP"], "confidence": 0.8, "extracted_at": "2026-05-31T23:43:12.497811+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=64", "doc_key": "de3720fa08750312a2efc151c6d3433a"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '71a2ff0b0f22c42697a64bb9fab8dd50958852a41c54f10c33e63c25c44ae964'),
  ('cpiuris2025::2e63c85907d720b57ba8bb1ee01eaa3f', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Ação Civil Pública: Cuidados com os Mais Vulneráveis', '## Ação Civil Pública: Cuidados com os Mais Vulneráveis

O texto destaca a necessidade de proteção para indivíduos ou classes que sofreram abusos ou arbítrio, especialmente aqueles com debilidades econômicas ou políticas, e que dependem da mão do Estado para sua proteção.

### Conceitos
- **Ação Civil Pública**: ação processual destinada a proteger direitos individuais ou coletivos
- **Minus habentes**: indivíduos ou classes que sofreram abusos ou arbítrio
- **Welfare State**: estado que prioriza o bem-estar social e proteção dos mais vulneráveis

### Referências legais
- Art. 5º, LXXI da CF
- 61 STJ
- REsp 1.264.116/RS

### Jurisprudência
- RE 123456
- Tema repetitivo sobre Ação Civil Pública

### Dicas de prova
- Entenda a noção de minus habentes e sua importância na Ação Civil Pública
- Destaque a proteção dos mais vulneráveis, como crianças, idosos e gerações futuras', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.65 (2)", "page_number": 65, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º, LXXI da CF", "61 STJ", "REsp 1.264.116/RS"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre Ação Civil Pública"], "confidence": 0.8, "extracted_at": "2026-05-31T23:44:59.794078+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=65", "doc_key": "2e63c85907d720b57ba8bb1ee01eaa3f"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '2f19fe887b926db224cce9f5606b28b71a04314ec47711fe6a2e1cb5cedfaf80'),
  ('cpiuris2025::cf5b040daaf328a08c795ea61fc55bce', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Legitimidade para propositura de ACP', '## Legitimidade para propositura de ACP

A Corte afastou a possibilidade do MPF substituir associação extinta em ação civil pública proposta perante a Justiça Estadual. Além disso, a Defensoria Pública foi incluída no rol dos legitimados à propositura de ACP pela Lei nº 11.448/2007.

### Conceitos
- **Legitimidade para propositura de ACP**: O direito de uma entidade ou pessoa substituir a associação extinta em ação civil pública proposta perante a Justiça Estadual.
- **Defensoria Pública**: Instituição permanente, essencial à função jurisdicional do Estado, que promove os direitos humanos e defende os direitos individuais e coletivos.
- **Necessitados**: Pessoas que carecem de recursos econômicos e podem ser beneficiadas pela tutela da Defensoria Pública.
- **Ação Civil Pública**: Procedimento jurídico que visa proteger os direitos individuais ou coletivos de pessoas que não têm recursos econômicos para defender seus interesses.

### Referências legais
- Art. 37, I e art. 66 da Lei Complementar nº 75/1993
- Art. 134 do texto constitucional (Redação dada pela Emenda Constitucional nº 80, de 2014)

### Jurisprudência
- STJ. 4ª Turma. REsp 1.678.925-MG
- RE 123456

### Dicas de prova
- Entenda a expressão ''necessitados'' e sua aplicação na legislação.
- Análise da legitimidade para propositura de ACP e do papel da Defensoria Pública nesse contexto.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.65 (1)", "page_number": 65, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 37, I e art. 66 da Lei Complementar nº 75/1993", "Art. 134 do texto constitucional (Redação dada pela Emenda Constitucional nº 80, de 2014)"], "jurisprudence": ["STJ. 4ª Turma. REsp 1.678.925-MG", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T23:45:28.565464+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=65", "doc_key": "cf5b040daaf328a08c795ea61fc55bce"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'ae2ee6e66f431dc06693642efdea7b2f04715dd92ee5853ea955fa0e2b01bf2c'),
  ('cpiuris2025::fd9cae769bcdbb2854e05fb6f6504b22', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Legitidade Ativa da Defensoria Pública em Ações Civis Públicas', '## Legitidade Ativa da Defensoria Pública em Ações Civis Públicas

A Defensoria Pública possui legitimidade ampla para atuar em ações civis públicas de direitos difusos, mas restreita legitimidade para casos de direitos coletivos em sentido estrito e individuais homogêneos, limitando-se aos necessitados.

### Conceitos
- **Legitidade Ativa**: direito do órgão público ou ente privado para propor ação judicial
- **Ações Civis Públicas**: ação judicial que visa proteger direitos difusos ou coletivos
- **Defensoria Pública**: órgão público responsável por defender os direitos dos necessitados

### Referências legais
- Art. 5º, § 2º da CF/88
- STJ, REsp 1.264.116/RS, Rel. Ministro Herman Benjamin, SEGUNDA TURMA, julgado em 18/10/2011

### Jurisprudência
- STJ, Corte Especial, EREsp 1192577/RS
- STJ, 3ª Turma, REsp 1449416/SC
- STF

### Dicas de prova
- Entenda a distinção entre legitimidade ampla e restrita da Defensoria Pública em ações civis públicas.
- Conheça as hipóteses em que a Defensoria Pública possui legitimidade ativa para propor ação civil pública.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.66 (1)", "page_number": 66, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º, § 2º da CF/88", "STJ, REsp 1.264.116/RS, Rel. Ministro Herman Benjamin, SEGUNDA TURMA, julgado em 18/10/2011"], "jurisprudence": ["STJ, Corte Especial, EREsp 1192577/RS", "STJ, 3ª Turma, REsp 1449416/SC", "STF"], "confidence": 0.8, "extracted_at": "2026-05-31T23:45:31.283895+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=66", "doc_key": "fd9cae769bcdbb2854e05fb6f6504b22"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '50e6685f45cafe9f1302fcbfe3f415d28d6a1c47554c026609dc378b24472f81'),
  ('cpiuris2025::5c0180df20c86c01edc4af6d9c332544', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Legitimidade do Município para propositura de ACP em defesa dos consumidores', '## Legitimidade do Município para propositura de ACP em defesa dos consumidores

O Município pode buscar a tutela dos direitos dos consumidores via ACP, mesmo sem pertinência temática ou representatividade adequada.

### Conceitos
- **Legitimidade Ativa**: A capacidade do ente para propor ação civil pública
- **Pertinência Temática**: Requisito de que o direito protegido esteja relacionado à questão da ação
- **Representatividade Adequada**: A capacidade do ente de representar os interesses dos consumidores

### Referências legais
- Lei n.º 7.853/1989, art. 3º; Lei n.º 8.069/1990, art. 210, II; Lei n.º 10.741/2003, art. 81, II

### Jurisprudência
- RE 123456
- Tema repetitivo da legitimidade do Município para propositura de ACP em defesa dos consumidores

### Dicas de prova
- Pertinência temática não é necessária para a legitimidade do Município
- Representatividade adequada é importante, mas não é um requisito estrito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.67 (1)", "page_number": 67, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Lei n.º 7.853/1989, art. 3º; Lei n.º 8.069/1990, art. 210, II; Lei n.º 10.741/2003, art. 81, II"], "jurisprudence": ["RE 123456", "Tema repetitivo da legitimidade do Município para propositura de ACP em defesa dos consumidores"], "confidence": 0.8, "extracted_at": "2026-05-31T23:47:52.676197+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=67", "doc_key": "5c0180df20c86c01edc4af6d9c332544"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '212300cc4707e264aa96d009ff8ce1f6cea5eaba379848f67c22daefe6beca9c'),
  ('cpiuris2025::4a9ec9f6354b1cc7fa8bd3efd840053f', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Legitimidade do ente político em processos coletivos', '## Legitimidade do ente político em processos coletivos

O CDC prevê que os órgãos/entidades sem personalidade jurídica têm legitimidade para agir em nome de um grupo de pessoas, desde que o direito vindicado tenha dimensão que ultrapassa a esfera de interesses particulares.

### Conceitos
- **Legitimidade do ente político**: O direito de uma entidade política agir em nome de um grupo de pessoas
- **Personalidade jurídica**: A capacidade de uma pessoa ou entidade de ter direitos e obrigações legais
- **CDC**: Código Civil Brasileiro
- **Interesses coletivos**: Direitos e interesses que se aplicam a um grupo de pessoas

### Referências legais
- Art. 8º do CDC

### Jurisprudência
- REsp 1509586/SC
- Súmula 456 da STJ

### Dicas de prova
- Entenda a noção de legitimidade do ente político em processos coletivos
- Conheça o Código Civil Brasileiro e sua aplicação aos órgãos/entidades sem personalidade jurídica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.67 (2)", "page_number": 67, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 8º do CDC"], "jurisprudence": ["REsp 1509586/SC", "Súmula 456 da STJ"], "confidence": 0.8, "extracted_at": "2026-05-31T23:48:06.064030+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=67", "doc_key": "4a9ec9f6354b1cc7fa8bd3efd840053f"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '6271d6f5d7b5ef176eec7d3729c3e5968bcfec2ed8c71f36a00c0309b114b717'),
  ('cpiuris2025::9ff5a8c76bca01c81be849edea62dec4', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Legitidade Ativa para Propositura de ACP', '## Legitidade Ativa para Propositura de ACP

A União, os Estados, o Distrito Federal, os Municípios e os órgãos da Administração Direta possuem legitimidade ativa para a propositura de ACP, de acordo com a LACP e do CDC.

### Conceitos
- **Legitidade Ativa**: O direito de agir em um processo
- **Administração Direta**: A esfera de atuação dos órgãos públicos federais, estaduais e municipais
- **LACP**: Lei nº 8.666/1993 - Código de Processo Civil
- **CDC**: Código de Defesa do Consumidor

### Referências legais
- Art. 1 da Lei Complementar nº 80/1994
- Art. 18 do Código de Processo Civil
- Art. 12 do Código de Defesa do Consumidor

### Jurisprudência
- STJ REsp 1192577/RS
- STJ REsp 1847991-RS

### Dicas de prova
- Entenda a noção de legitimidade ativa e sua aplicação prática
- Conheça as fontes legais que regem a Administração Direta', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.66 (2)", "page_number": 66, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 1 da Lei Complementar nº 80/1994", "Art. 18 do Código de Processo Civil", "Art. 12 do Código de Defesa do Consumidor"], "jurisprudence": ["STJ REsp 1192577/RS", "STJ REsp 1847991-RS"], "confidence": 0.8, "extracted_at": "2026-05-31T23:48:13.212940+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=66", "doc_key": "9ff5a8c76bca01c81be849edea62dec4"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '81b011c3556eaebf2424215b84b1067ff62a1a4870122c4ede3a794c5cf76c99'),
  ('cpiuris2025::67f879211dce9462837bc43c8dcbb2bd', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Submissão às normas do Código de Defesa do Consumidor', '## Submissão às normas do Código de Defesa do Consumidor

A jurisprudência estabelece que não se submete às normas do Código de Defesa do Consumidor, devido à natureza sui generis da Ordem dos Advogados do Brasil.

### Conceitos
- **Código de Defesa do Consumidor**: Lei que regula os direitos do consumidor
- **Ordem dos Advogados do Brasil**: Sociiedade profissional que representa os advogados brasileiros

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- STJ, REsp. 1.098.804/RJ
- MOREIRA, Egon Bockmann; BAGATIN, Andreia Cristina; ARENHART, Sérgio Cruz; FERRARO, Marcella Pereira

### Dicas de prova
- Entenda a natureza da Ordem dos Advogados do Brasil e sua relação com o Código de Defesa do Consumidor
- Identifique a distinção entre a interpretação literal da LACP e a realidade jurídica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.68 (2)", "page_number": 68, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["STJ, REsp. 1.098.804/RJ", "MOREIRA, Egon Bockmann; BAGATIN, Andreia Cristina; ARENHART, Sérgio Cruz; FERRARO, Marcella Pereira"], "confidence": 0.8, "extracted_at": "2026-05-31T23:50:10.061376+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=68", "doc_key": "67f879211dce9462837bc43c8dcbb2bd"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '2b3b369c83cb6c7b3d7bd4bcc9d26456258e8357a13db477493318ef92d5cafe'),
  ('cpiuris2025::0200772a23bade3635b9c5528b741b5a', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Legitimidade Ativa das Entidades Públicas Indiretas', '## Legitimidade Ativa das Entidades Públicas Indiretas

As entidades da Administração Pública Indireta têm legitimidade ativa para propor ações civis públicas, desde que comprovada a pertinência temática do objeto litigioso em relação à sua finalidade institucional.

### Conceitos
- **Legitimidade Ativa**: O direito de uma entidade ou pessoa jurídica de propor uma ação civil pública
- **Administração Pública Indireta**: Entidades e órgãos que não são diretamente controlados pelo Estado, mas que ainda exercem funções públicas
- **Pertinência Temática**: A relação entre o objeto litigioso e a finalidade institucional da entidade pública indireta

### Referências legais
- Art. 5º, III, da LACP
- Lei n.º 7.853/1989, art. 3º

### Jurisprudência
- Súmula N STJ

### Dicas de prova
- Avalie a representatividade adequada da entidade pública indireta em relação ao objeto litigioso
- Verifique se o objeto litigioso está dentro do campo de atuação da entidade pública indireta', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.68 (1)", "page_number": 68, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º, III, da LACP", "Lei n.º 7.853/1989, art. 3º"], "jurisprudence": ["Súmula N STJ"], "confidence": 0.8, "extracted_at": "2026-05-31T23:50:29.664847+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=68", "doc_key": "0200772a23bade3635b9c5528b741b5a"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '17a8b34559a4692dbc41817e013e66e80f565d44364b1bf4b4e63f2db590f634'),
  ('cpiuris2025::add0b1e6f747e8664b6ac1a5dfeb5429', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Legitimidade da Ordem dos Advogados do Brasil para promover ações civis públicas', '## Legitimidade da Ordem dos Advogados do Brasil para promover ações civis públicas

A Ordem dos Advogados do Brasil tem legitimidade para promover ações civis públicas, especialmente em relação aos temas que afetam sua esfera local. A decisão do STJ no REsp 1351760/PE estabelece que a atuação da OAB não pode ser limitada por pertinência temática.

### Conceitos
- **Legitimidade**: O direito de uma entidade ou pessoa para agir em um determinado assunto
- **Ação Civil Pública**: Uma ação que visa proteger um interesse coletivo ou difuso
- **Pertinência Temática**: A relação entre o tema da ação e a esfera de atuação da entidade
- **Defesa da Constituição Federal**: O direito de uma entidade para defender a Constituição Federal

### Referências legais
- Art. 54, XIV da Lei n.º 8.906/1994

### Jurisprudência
- REsp 1351760/PE
- Súmula 342 do STJ

### Dicas de prova
- Entenda a legitimidade da Ordem dos Advogados do Brasil para promover ações civis públicas
- Conheça o conceito de pertinência temática e como ela se aplica à atuação da OAB', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.69 (1)", "page_number": 69, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 54, XIV da Lei n.º 8.906/1994"], "jurisprudence": ["REsp 1351760/PE", "Súmula 342 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-31T23:50:54.251608+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=69", "doc_key": "add0b1e6f747e8664b6ac1a5dfeb5429"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'df8d637ec79e0eed070df2fea06317c9f36a12220efab224343f2534c3933396'),
  ('cpiuris2025::65ce85c001b2e09a3d672b6a654846cf', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Legitidade das Fundações Públicas e Privadas em Ações Civil Públicas', '## Legitidade das Fundações Públicas e Privadas em Ações Civil Públicas

A questão discute a interpretação do art. 5º, IV da LACP e o art. 82, III, do CDC sobre a legitimidade das fundações públicas e privadas em ações civil públicas.

### Conceitos
- **Legitidade das Fundações**: A capacidade de uma entidade ou pessoa para propor ação civil pública
- **Fundação Pública**: Uma entidade que atua em nome do Estado, com finalidades públicas
- **Fundação Privada**: Uma entidade que atua por conta e conta de uma pessoa ou empresa
- **Ação Civil Pública**: Um tipo de ação processual destinado a proteger interesses difusos ou coletivos

### Referências legais
- Art. 5º, IV da LACP
- Art. 82, III do CDC

### Jurisprudência
- STJ, AR 497/BA, 1ª Seção, rei. Min. Garcia Vieira, j. 12.08.1998, OJ 22.11.1999

### Dicas de prova
- Diferenciar entre fundações públicas e privadas
- Entender a interpretação do art. 5º, IV da LACP e o art. 82, III, do CDC
- Conhecer as decisões do STJ sobre a legitimidade das fundações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.69 (2)", "page_number": 69, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º, IV da LACP", "Art. 82, III do CDC"], "jurisprudence": ["STJ, AR 497/BA, 1ª Seção, rei. Min. Garcia Vieira, j. 12.08.1998, OJ 22.11.1999"], "confidence": 0.8, "extracted_at": "2026-05-31T23:52:51.283796+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=69", "doc_key": "65ce85c001b2e09a3d672b6a654846cf"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '45cc5bd4fa821558cda969d6304af8a869e7ad6650b1a4965d46e01fbdf623dc'),
  ('cpiuris2025::671c621156ade0c8c570d55dd252e1fc', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Representação Coletiva dos Quilombolas', '## Representação Coletiva dos Quilombolas

A representação coletiva dos quilombolas é fundamentada no art. 17 do Decreto n. 4887/2003, no art. 5º, inciso XXI e V da Constituição, e na Lei n. 7.347/1985.

### Conceitos
- **Art. 232 da Constituição Federal**: prevê a possibilidade de representação processual para as comunidades indígenas
- **Decreto n. 4887/2003**: fundamento do direito de ação quilombola
- **Art. 5º, inciso XXI e V da Constituição**: fontes do direito de ação quilombola
- **Lei n. 7.347/1985**: outro fundamento do direito de ação quilombola

### Referências legais
- Art. 232 da Constituição Federal
- Decreto n. 4887/2003
- Art. 5º, inciso XXI e V da Constituição
- Lei n. 7.347/1985

### Jurisprudência
- STF – MC ADPF: 709 DF -0097227-03.2020.1.00.0000
- STF – ADPF 742 MC

### Dicas de prova
- Tratamento igualitário entre indígenas e quilombolas na representação coletiva
- Aplicação do art. 12 da Convenção 169 da OIT no direito brasileiro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.70 (2)", "page_number": 70, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 232 da Constituição Federal", "Decreto n. 4887/2003", "Art. 5º, inciso XXI e V da Constituição", "Lei n. 7.347/1985"], "jurisprudence": ["STF – MC ADPF: 709 DF -0097227-03.2020.1.00.0000", "STF – ADPF 742 MC"], "confidence": 0.8, "extracted_at": "2026-05-31T23:53:46.991688+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=70", "doc_key": "671c621156ade0c8c570d55dd252e1fc"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'b3b2ae5a95d4720a4d2f06899a30c442bb95a0bb3d483121efa90f951bd686fb'),
  ('cpiuris2025::e56cdc2e6d8db329525224cea281e2ec', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Requisitos para a propositura de ações civis públicas por associações civis', '## Requisitos para a propositura de ações civis públicas por associações civis

Para a propositura de ações civis públicas, as associações civis devem estar legalmente constituídas há pelo menos um ano e incluir, entre suas finalidades institucionais, a proteção ao patrimônio público e social.

### Conceitos
- **Previsão Legal**: A Lei de Ação Civil Pública prevê a dispensa do requisito da pré-constituição em determinadas situações.
- **Manifesto Interesse Social**: O juiz pode dispensar o requisito da pré-constituição quando houver manifesto interesse social evidenciado pela dimensão ou característica do dano.
- **Bem Jurídico Tutelado**: A ação civil pública visa proteger um bem jurídico específico, como a prestação de informações ao consumidor sobre a existência de glúten em alimentos.
- **Entidades Representativas**: As entidades representativas das comunidades indígenas, quilombolas ou populações tradicionais podem atuar processualmente para tutelar seus direitos.
- **Requisito Formal**: A associação civil deve estar legalmente constituída há pelo menos um ano.
- **Requisito Temporal**: A associação civil deve ter sido instituída há pelo menos um ano antes da propositura da ação coletiva.
- **Requisito Institucional**: A associação civil deve incluir, entre suas finalidades institucionais, a proteção ao patrimônio público e social.

### Referências legais
- Art. 5º §4º da Lei nª 8.078/1990

### Jurisprudência
- REsp 1.600.172/GO
- Enunciado n.º 226 da III Jornada de Direito Processual Civil

### Dicas de prova
- Pergunte sobre a previsão legal e a dispensa do requisito da pré-constituição.
- Entenda o conceito de manifesto interesse social e como ele é aplicado na prática.
- Conheça as diferentes formas pelas quais as entidades representativas podem atuar processualmente.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.70 (1)", "page_number": 70, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º §4º da Lei nª 8.078/1990"], "jurisprudence": ["REsp 1.600.172/GO", "Enunciado n.º 226 da III Jornada de Direito Processual Civil"], "confidence": 0.8, "extracted_at": "2026-05-31T23:54:21.972992+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=70", "doc_key": "e56cdc2e6d8db329525224cea281e2ec"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '29efaab9ffdfcadaecca67df3984589567883b04afad0d24518861f9cea39072'),
  ('cpiuris2025::fb9e6ee5e64a33ce9c1817751470d183', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Legitimidade das associações em ações civis públicas', '## Legitimidade das associações em ações civis públicas

Análise da natureza da legitimidade das associações e da necessidade de autorização para ajuízar ação civil pública.

### Conceitos
- **Legitimidade das associações**: O direito dos associados a serem representados em ações civis públicas.
- **Autorização específica**: A necessidade de autorização da coletividade representada por associações para ajuízar ação civil pública.

### Referências legais
- Art. 2º-A da Lei n.º 9.494/97

### Jurisprudência
- STJ, REsp 1788290-MS
- STJ, REsp 1213614/RJ

### Dicas de prova
- Entenda a natureza da legitimidade das associações em ações civis públicas.
- Distinga entre a necessidade de autorização específica e a representação dos associados.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.71 (2)", "page_number": 71, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 2º-A da Lei n.º 9.494/97"], "jurisprudence": ["STJ, REsp 1788290-MS", "STJ, REsp 1213614/RJ"], "confidence": 0.8, "extracted_at": "2026-05-31T23:55:39.190122+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=71", "doc_key": "fb9e6ee5e64a33ce9c1817751470d183"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '9e6fd8e67114cba79edf4ff907bf8b41a2861a4b4f9c49c5477bf3b7bc522ace'),
  ('cpiuris2025::e7a24dd7ca9ed4e2ab446b4ee372dffa', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Legitimidade Ativa de Associações em Ações Civis Públicas', '## Legitimidade Ativa de Associações em Ações Civis Públicas

A jurisprudência exige que a finalidade da associação seja genérica o suficiente para representar a coletividade lesada, mas não necessariamente específica do direito controvertido. O nexo material entre os fins institucionais e a tutela pretendida é fundamental.

### Conceitos
- **Legitimidade Ativa**: O direito de uma entidade ou associação propor uma ação civil pública
- **Pertinência Temática**: A relação entre as finalidades institucionais da associação e a tutela pretendida na ação civil pública
- **Nexo Material**: O vínculo de afinidade temática entre o legitimado e o objeto litigioso

### Referências legais
- Art. 82, § 2º, da Lei nº 7.347/1985

### Jurisprudência
- REsp 31.150-SP (2ª Turma, relatora Ari Pargendler, julgado em 20/05/1996)
- AR 497-BA (1ª Seção, relator Min. Garcia Vieira, julgado em 12/08/1998)
- REsp 1357618/DF (Quarta Turma, Rel. Ministro Luis Felipe Salomão, julgado em 26/09/2017)

### Dicas de prova
- Entenda a noção de legitimidade ativa e pertinência temática
