  ('cpiuris2025::25f5ec022c63187286bc26949fba6bee', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Legitimidade das associações em ações cíveis fundadas em interesses coletivos ou difusos', '## Legitimidade das associações em ações cíveis fundadas em interesses coletivos ou difusos

A Lei n.º 8.069/90 e a Lei n.º 10.741/03 estabelecem que as associações legalmente constituídas há pelo menos um ano podem ser legitimadas concorrentemente em ações cíveis fundadas em interesses coletivos ou difusos, desde que tenham prévia autorização estatutária.

### Conceitos
- **Legitimidade das associações**: O direito de uma entidade associativa participar do processo como parte legítima
- **Representação coletiva**: A capacidade de uma entidade associativa representar os interesses de seus membros em um processo
- **Substituição processual**: O direito de uma entidade associativa substituir um membro individual no processo
- **Autorização estatutária**: A prévia autorização concedida pela assembleia da entidade associativa para propositurar ação coletiva

### Referências legais
- Art. 210 da Lei n.º 8.069/90
- Art. 81 da Lei n.º 10.741/03
- Medida provisória nº 2.180-35 de 2001

### Jurisprudência
- RE 612.043/PR (2017)

### Dicas de prova
- Entenda a distinção entre representação coletiva e substituição processual
- Conheça a importância da autorização estatutária para legitimidade das associações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.72 (1)", "page_number": 72, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 210 da Lei n.º 8.069/90", "Art. 81 da Lei n.º 10.741/03", "Medida provisória nº 2.180-35 de 2001"], "jurisprudence": ["RE 612.043/PR (2017)"], "confidence": 0.8, "extracted_at": "2026-05-31T23:57:23.308305+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=72", "doc_key": "25f5ec022c63187286bc26949fba6bee"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '78cd77c25ba5e4a6dddcbf5f03b7f9465837e0007ed29b3e1c1ceeb19285befb'),
  ('cpiuris2025::d154976778881f85d562aa9ce184b8df', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Eficácia subjetiva da coisa julgada na ação coletiva', '## Eficácia subjetiva da coisa julgada na ação coletiva

A eficácia da coisa julgada na ação coletiva somente alcança os associados residentes no âmbito do órgão julgador, que estavam filiados anteriormente ou até a data da propositura da demanda.

### Conceitos
- **Copo**: Ação coletiva
- **Eficácia subjetiva**: Alcança apenas os interessados na ação
- **Associados**: Membros da associação civil
- **Filiado**: Pertence à associação
- **Cidade de residência**: Local onde o associado reside

### Referências legais
- Art. 102 do Código Civil
- Súmula 394/STJ

### Jurisprudência
- RE 573.232
- RE 612.043/PR

### Dicas de prova
- Entenda a diferença entre ação coletiva e ação civil pública.
- Conheça o conceito de eficácia subjetiva da coisa julgada.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.72 (2)", "page_number": 72, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 102 do Código Civil", "Súmula 394/STJ"], "jurisprudence": ["RE 573.232", "RE 612.043/PR"], "confidence": 0.8, "extracted_at": "2026-05-31T23:57:51.071511+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=72", "doc_key": "d154976778881f85d562aa9ce184b8df"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '9d4c77da633b6bc397231c8d0e90be9af199b1faaef8e328b14e6810263145dd'),
  ('cpiuris2025::7b8e848d0c032165319cb6248d842e0d', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Autorização para ações coletivas em associações civis', '## Autorização para ações coletivas em associações civis

A jurisprudência do STJ permite que uma associação civil assuma ação coletiva iniciada por outra sem autorização expressa dos associados, com base no microssistema de defesa dos interesses coletivos.

### Conceitos
- **Autorização individual**: A autorização individual é necessária para que uma associação civil assuma ação coletiva iniciada por outra.
- **Defesa dos interesses coletivos**: O microssistema de defesa dos interesses coletivos privilegia o aproveitamento do processo coletivo.
- **Sucessão da parte autora**: A sucessão da parte autora é possível em demandas coletivas, especialmente quando os interesses envolvidos são importantes.

### Referências legais
- Art. 5º, parágrafo 3º, da Lei da Ação Civil Pública
- Art. 9º, da Lei da Ação Popular

### Jurisprudência
- RE 573.232/SC
- EDcl no REsp 1405697/MG
- AgInt no REsp 1833056-SP

### Dicas de prova
- Entenda o microssistema de defesa dos interesses coletivos e a importância do aproveitamento do processo coletivo.
- Conheça as regras sobre autorização individual e sucessão da parte autora em demandas coletivas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.73 (1)", "page_number": 73, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º, parágrafo 3º, da Lei da Ação Civil Pública", "Art. 9º, da Lei da Ação Popular"], "jurisprudence": ["RE 573.232/SC", "EDcl no REsp 1405697/MG", "AgInt no REsp 1833056-SP"], "confidence": 0.8, "extracted_at": "2026-05-31T23:58:41.750083+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=73", "doc_key": "7b8e848d0c032165319cb6248d842e0d"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'c040b588e6605d3031b51b338d0c21acb5ff54b9ca5fcaf2301e20a02a9a3046'),
  ('cpiuris2025::6b9d741c8d23d5d7337f81b6311fe61c', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Eficácia Subjetiva da Coisa Julgada em Ações Coletivas', '## Eficácia Subjetiva da Coisa Julgada em Ações Coletivas

A eficácia subjetiva da coisa julgada em ações coletivas somente alcança os associados residentes no âmbito da jurisdição do órgão julgador, que o fossem em momento anterior ou até a data da propositura da demanda.

### Conceitos
- **Coisa Julgada**: Conceito jurídico que se refere à decisão final de um processo
- **Ações Coletivas**: Processos em que vários indivíduos ou entidades são parte do litigio
- **Eficácia Subjetiva**: Obrigação de cumprir uma obrigação, seja ela civil, penal ou administrativa
- **Legitimidade**: Direito de participar no processo em nome de outrem

### Referências legais
- Art. 2º-A da Lei n. 9.494/97
- Súmula 499 do STF

### Jurisprudência
- RE 612043/PR
- AREsp 2.122.178-SP
- EREsp 1.367.220-PR

### Dicas de prova
- Entenda a diferença entre eficácia subjetiva e objetiva da coisa julgada em ações coletivas
- Conheça as limitações do entendimento firmado pelo STF no RE 612043/PR', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.74 (1)", "page_number": 74, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 2º-A da Lei n. 9.494/97", "Súmula 499 do STF"], "jurisprudence": ["RE 612043/PR", "AREsp 2.122.178-SP", "EREsp 1.367.220-PR"], "confidence": 0.8, "extracted_at": "2026-05-31T23:59:47.708573+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=74", "doc_key": "6b9d741c8d23d5d7337f81b6311fe61c"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'dbef333f2921be5e8b25f492fdfa41846ede0acde579c7b35db87f38fa9f959a'),
  ('cpiuris2025::6e6968e7b2a87a87baa4dadbefcae6d9', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Legitidade Ativa de Associação de Municípios e Prefeitos em Ações Coletivas', '## Legitidade Ativa de Associação de Municípios e Prefeitos em Ações Coletivas

É necessária a autorização expressa dos associados e a juntada da lista de representados à inicial para a proposta de ação coletiva. O STJ entende que associações de Municípios e Prefeitos não têm legitimidade ativa para tutelar direitos e interesses de pessoas jurídicas de direito público.

### Conceitos
- **Legitidade Ativa**: O direito de agir em nome de outrem, especialmente no contexto do direito processual
- **Representação Processual**: A capacidade de uma pessoa ou entidade exercer ações processuais em nome de outra
- **Art. 75, III, do CPC/2015**: Preve que a representação judicial dos Municípios deve ser exercida pelo seu Prefeito ou Procurador

### Referências legais
- Art. 75, III, do CPC/2015
- STJ. 1ª Turma. Resp 1977830-MT, Rel. Min. Sérgio Kukina, julgado em 22/03/2022 (Info 730)
- STJ. 1ª Seção. REsp 1.503.007-CE, Rel. Min. Herman Benjamin, julgado em 14/6/2017 (Info 610)

### Jurisprudência
- RE 573.232/SC
- RE 1977830-MT

### Dicas de prova
- Entenda a noção de legitimidade ativa e representação processual
- Conheça o artigo 75, III, do CPC/2015
- Análise cuidadosa das decisões do STJ em casos semelhantes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.73 (2)", "page_number": 73, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 75, III, do CPC/2015", "STJ. 1ª Turma. Resp 1977830-MT, Rel. Min. Sérgio Kukina, julgado em 22/03/2022 (Info 730)", "STJ. 1ª Seção. REsp 1.503.007-CE, Rel. Min. Herman Benjamin, julgado em 14/6/2017 (Info 610)"], "jurisprudence": ["RE 573.232/SC", "RE 1977830-MT"], "confidence": 0.8, "extracted_at": "2026-05-31T23:59:50.098402+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=73", "doc_key": "6e6968e7b2a87a87baa4dadbefcae6d9"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '2eca396fe5ad58c91439a29feb424462d82c450eb02bf20c3dc976f44b555a55'),
  ('cpiuris2025::4032e8b7482d4c9d271ffbb0761261c3', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Legitimidade dos Sindicatos em Juízo', '## Legitimidade dos Sindicatos em Juízo

Os sindicatos têm legitimidade para defender direitos difusos, coletivos e individuais homogêneos, sem necessidade de autorização dos substituídos.

### Conceitos
- **Legitimidade Extraordinária**: Direito do sindicato a atuar em juízo sem autorização dos substituídos
- **Direitos Difusos**: Direitos que afetam mais de uma pessoa, como o meio ambiente do trabalho
- **Coletivos**: Direitos que se aplicam a um grupo de pessoas, como os trabalhadores

### Referências legais
- Art. 831 da CLT

### Jurisprudência
- RE 123456
- Súmula 345 do STF

### Dicas de prova
- Entenda o conceito de legitimidade extraordinária dos sindicatos em juízo
- Diferencie entre direitos difusos, coletivos e individuais homogêneos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.74 (2)", "page_number": 74, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 831 da CLT"], "jurisprudence": ["RE 123456", "Súmula 345 do STF"], "confidence": 0.8, "extracted_at": "2026-06-01T00:01:48.059543+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=74", "doc_key": "4032e8b7482d4c9d271ffbb0761261c3"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '16dd1c4df9e92b311d2f1845015c2cd8431b69435d0e53d137b6798b5b2b9509'),
  ('cpiuris2025::e0037eff125b34f5dfeba0418ecb0946', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Obrigatoriedade do litisconsórcio necessário', '## Obrigatoriedade do litisconsórcio necessário

A obrigatoriedade do litisconsórcio necessário depende de disposição legal ou da natureza da relação jurídica controvertida, sendo necessário citar todos os sujeitos econômicos envolvidos.

### Conceitos
- **Litisconsórcio necessário**: Obrigatoriedade do litisconsórcio para todos os sujeitos econômicos envolvidos
- **Disposição de lei**: Obrigação legal de citar todos os sujeitos econômicos envolvidos
- **Natureza da relação jurídica**: A eficácia da sentença depende da citação de todos os sujeitos econômicos envolvidos

### Referências legais
- Art. 114 do CPC/2015

### Jurisprudência
- REsp 1453891-PE
- STJ. 1ª Turma.

### Dicas de prova
- Distinção entre litisconsórcio necessário e facultativo
- Importância da natureza da relação jurídica para determinar a obrigatoriedade do litisconsórcio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.75 (2)", "page_number": 75, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 114 do CPC/2015"], "jurisprudence": ["REsp 1453891-PE", "STJ. 1ª Turma."], "confidence": 0.8, "extracted_at": "2026-06-01T00:02:15.001464+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=75", "doc_key": "e0037eff125b34f5dfeba0418ecb0946"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'e11381afc5f57d92328b7661a62dc3ae5fc3131bcab97983c2a2f765dd22636b'),
  ('cpiuris2025::989f6b1ae2e4c7b1d041a0157dfd0f30', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Legitimidade passiva em ações civis públicas', '## Legitimidade passiva em ações civis públicas

A legislação não prevê rol de legitimados passivos para as ações civis públicas. Qualquer pessoa física ou jurídica responsável pelo dano pode compor o polo passivo da demanda, necessitando de litisconsórcio quando presentes os requisitos do art. 114 do CPC.

### Conceitos
- **Legitimidade passiva**: O direito de uma pessoa ou entidade se opor a uma ação judicial
- **Litisconsórcio**: A junção de pessoas ou entidades no mesmo processo
- **CPC**: Código de Processo Civil
- **Art. 114**: Requisito para o litisconsórcio em ações civis públicas

### Referências legais
- Art. 114 do CPC

### Jurisprudência
- RE 883.642/AL
- AREsp 2.399.352-MA
- AgInt no REsp 1.956.312-RS

### Dicas de prova
- Entenda a diferença entre legitimidade passiva e litisconsórcio
- Conheça o artigo 114 do CPC e seus requisitos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.75 (1)", "page_number": 75, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 114 do CPC"], "jurisprudence": ["RE 883.642/AL", "AREsp 2.399.352-MA", "AgInt no REsp 1.956.312-RS"], "confidence": 0.8, "extracted_at": "2026-06-01T00:02:15.693762+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=75", "doc_key": "989f6b1ae2e4c7b1d041a0157dfd0f30"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '08ff216a122800f38f448ca77e7836c2ebf73a978586babf94ec68e06d03484d'),
  ('cpiuris2025::24c83d7c668ac117680c1a1cc868466e', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Legitimidade das partes na ação civil pública ou coletiva', '## Legitimidade das partes na ação civil pública ou coletiva

As partes legítimas à ação civil pública ou coletiva podem substituir processualmente a coletividade lesada, excetuando-se algumas hipóteses.

### Conceitos
- **Legitimidade das partes**: O direito de uma parte participar do processo em nome da coletividade
- **Ação civil pública ou coletiva**: Procedimento destinado a proteger interesses difusos ou coletivos
- **Coletividade lesada**: Grupamento de pessoas que se encontra em situação prejudicada por ato ilegal

### Referências legais
- Art. 81 do Código de Processo Civil
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a noção de legitimidade das partes e suas limitações
- Conheça as hipóteses em que o Ministério Público ou outras entidades podem substituir processualmente a coletividade lesada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.76 (2)", "page_number": 76, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 81 do Código de Processo Civil", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-06-01T00:04:14.092389+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=76", "doc_key": "24c83d7c668ac117680c1a1cc868466e"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '65e8a58e060d4c7854fc2e57c6f57374719e8f3996251aa5c168a075febd3474'),
  ('cpiuris2025::db16269b3e26648eabd74c360d77ff26', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Litisconsórcio e Intervenção de terceiros', '## Litisconsórcio e Intervenção de terceiros

O litisconsórcio é facultativo e ulterior, permitindo que o Poder Público e outras associações possam se habilitar como litisconsortes. A LACP também permite a formação de litisconsórcio entre órgãos do Ministério Público.

### Conceitos
- **Litisconsórcio**: Facultativo e ulterior, permitindo que o Poder Público e outras associações possam se habilitar como litisconsortes
- **Intervenção de terceiros**: Permitida pela LACP, especialmente em casos de dissídios coletivos de trabalho e ações contra sindicatos
- **LACP**: Lei nº 8.078, de 11.9.1990

### Referências legais
- Art. 5º §2º da CF
- Art. 5º, §5º da Lei nª 8.078, de 11.9.1990

### Dicas de prova
- Entenda a diferença entre litisconsórcio ativo e passivo
- Conheça as exceções ao litisconsórcio facultativo, como o caso de dissídios coletivos de trabalho', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.77 (1)", "page_number": 77, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º §2º da CF", "Art. 5º, §5º da Lei nª 8.078, de 11.9.1990"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-06-01T00:04:47.544895+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=77", "doc_key": "db16269b3e26648eabd74c360d77ff26"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'b4feaee844488fb202c702720cec440bb81dd69f6037651f06b97219133d50de'),
  ('cpiuris2025::d60a8b413158d337545dfa29d0c91f23', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Legitimidade Extraordinária Passiva', '## Legitimidade Extraordinária Passiva

A legitimidade extraordinária passiva é um tema debatido no direito brasileiro, com duas correntes doutrinárias: uma que admite a legitimação passiva coletiva e outra que rechaça. A primeira corrente defende que o artigo 5º, §2º, da LACP permite a legitimidade passiva coletiva, enquanto a segunda corrente argumenta que a substituição processual é instituto excepcional.

### Conceitos
- **Legitimidade Extraordinária Passiva**: Direito de uma coletividade ou grupo ser considerado sujeito passivo de uma relação jurídica
- **Litisconsórcio**: Condição em que várias pessoas são consideradas como partes no mesmo processo
- **Substituição Processual**: Instituto que permite a substituição de uma parte pelo outro, em determinados casos

### Referências legais
- Art. 5º, §2º, da LACP

### Jurisprudência
- {''term'': ''REsp 1735702-PR'', ''definition'': ''Processo que julgou a questão da legitimidade extraordinária passiva no direito brasileiro''}
- {''term'': ''STJ. 2ª Turma'', ''definition'': ''Corte que julgou o processo REsp 1735702-PR''}

### Dicas de prova
- Entenda a diferença entre legitimidade passiva coletiva e substituição processual
- Conheça as hipóteses em que a legitimidade extraordinária passiva é permitida ou rechaçada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.76 (1)", "page_number": 76, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º, §2º, da LACP"], "jurisprudence": ["{''term'': ''REsp 1735702-PR'', ''definition'': ''Processo que julgou a questão da legitimidade extraordinária passiva no direito brasileiro''}", "{''term'': ''STJ. 2ª Turma'', ''definition'': ''Corte que julgou o processo REsp 1735702-PR''}"], "confidence": 0.8, "extracted_at": "2026-06-01T00:05:02.914552+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=76", "doc_key": "d60a8b413158d337545dfa29d0c91f23"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'a2b498ddd24b203574bf52d6338202473ca04946815d8fa2b9e672fbb289a45d'),
  ('cpiuris2025::943ff0527a69093ef0faf9e5af2b269b', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Competência da Justiça Federal em ajuizamento de ACP em litisconsórcio', '## Competência da Justiça Federal em ajuizamento de ACP em litisconsórcio

A competência da Justiça Federal é determinada pela presença dos ramos do Ministério Público da União no processo, e o litisconsórcio em ação civil pública requer demonstração de razões específicas para justificar a presença de ambos os órgãos do MP.

### Conceitos
- **Litisconsórcio**: Ação com mais de um autor ou réu
- **Competência da Justiça Federal**: Determinada pela presença dos ramos do Ministério Público da União no processo
- **Legitimidade em ação civil pública**: Requer demonstração de razões específicas para justificar a presença de ambos os órgãos do MP

### Referências legais
- Art. 109, § 4º da CC/2012

### Jurisprudência
- REsp 1.051.302/STJ
- REsp 771.619/STJ

### Dicas de prova
- Entenda a regra de competência da Justiça Federal em ajuizamento de ACP em litisconsórcio.
- Demonstre a legitimidade em ação civil pública e as razões específicas que justificam a presença de ambos os órgãos do MP.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.77 (2)", "page_number": 77, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 109, § 4º da CC/2012"], "jurisprudence": ["REsp 1.051.302/STJ", "REsp 771.619/STJ"], "confidence": 0.8, "extracted_at": "2026-06-01T00:06:51.182799+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=77", "doc_key": "943ff0527a69093ef0faf9e5af2b269b"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '15b72cd201c94246caf19522a4874ef3452926b038df256e72ea3cd38a5960b6'),
  ('cpiuris2025::8a44c6bc6df0ab56f584206d539be864', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Denunciação da Lide em Demandas Consumeristas', '## Denunciação da Lide em Demandas Consumeristas

Regra que proíbe a denunciação da lide em demandas consumeristas nas hipóteses do art. 13, parágrafo único do CDC.

### Conceitos
- **Denunciação da Lide**: Procedimento pelo qual um terceiro é adicionado à causa de alheio
- **Demandas Consumeristas**: Ações civis que visam proteger os direitos dos consumidores
- **Art. 13, parágrafo único do CDC**: Dispositivo legal que proíbe a denunciação da lide em demandas consumeristas

### Referências legais
- Art. 13, parágrafo único do Código de Defesa do Consumidor (CDC)

### Jurisprudência
- STJ, 1ª Turma, AgRg no REsp 1.125.981/RS

### Dicas de prova
- Entenda a importância da denunciação da lide em demandas consumeristas
- Conheça o artigo 13, parágrafo único do CDC e sua aplicação prática', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.78 (2)", "page_number": 78, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 13, parágrafo único do Código de Defesa do Consumidor (CDC)"], "jurisprudence": ["STJ, 1ª Turma, AgRg no REsp 1.125.981/RS"], "confidence": 0.8, "extracted_at": "2026-06-01T00:07:15.731445+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=78", "doc_key": "8a44c6bc6df0ab56f584206d539be864"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'a7d0ed90e68ef0d1171f5f9c4c52ad4e5d92a9c614513d05391487190223b8ff'),
  ('cpiuris2025::9bc2c2a923156dcb74af8d3ff5a3d0e7', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Litisconsórcio entre Ministério Público Estadual e Federal', '## Litisconsórcio entre Ministério Público Estadual e Federal

O litisconsórcio entre os dois órgãos ministeriais não é permitido, pois a defesa dos interesses dos consumidores é atribuição comum a ambos, tornando injustificável o litisconsórcio ante a unicidade do Ministério Público.

### Conceitos
- **Litisconsórcio**: Conjunto de pessoas que se encontram em uma relação jurídica comum
- **Unicidade do Ministério Público**: A defesa dos interesses dos consumidores é atribuição comum a ambos os órgãos ministeriais
- **Racionalização dos serviços prestados à comunidade**: Deve pautar-se pela racionalização dos serviços prestados à comunidade

### Referências legais
- Art. 5º, § 5º da Lei n. 7.347/1985

### Jurisprudência
- RE 1.254.428
- Enunciado n. 119 do Fórum Permanente de Processualistas Civis

### Dicas de prova
- Mencione a necessidade de racionalização dos serviços prestados à comunidade
- Destaque a unicidade do Ministério Público como razão para não permitir o litisconsórcio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.78 (1)", "page_number": 78, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º, § 5º da Lei n. 7.347/1985"], "jurisprudence": ["RE 1.254.428", "Enunciado n. 119 do Fórum Permanente de Processualistas Civis"], "confidence": 0.8, "extracted_at": "2026-06-01T00:07:23.542417+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=78", "doc_key": "9bc2c2a923156dcb74af8d3ff5a3d0e7"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '6faf7955d21deb2feaf86a3e3672ef72d3ffea236db76f20ed71de058cec1697'),
  ('cpiuris2025::6d988ef0ab42f9e25c753122ce4a51ac', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Relação entre demandas coletivas e individuais', '## Relação entre demandas coletivas e individuais

A relação entre demandas coletivas e individuais é definida pela teoria da tríplice identidade (partes, pedido e causa de pedir). No processo coletivo, a teoria da identidade da relação jurídica material explica a identidade entre ações coletivas.

### Conceitos
- **TEORIA DA TRÍPlice IDENTIDADE**: Define a relação entre demandas individuais
- **IDENTIDADE DA RELAÇÃO JURÍDICA MATERIAL**: Explica a identidade entre ações coletivas no processo coletivo

### Referências legais
- Art. 104 do CDC
- Súmula 137 STF

### Jurisprudência
- RE 456.789

### Dicas de prova
- Diferenciar entre litispendência e conexão/continuidade nas demandas coletivas e individuais
- Entender a teoria da tríplice identidade e a teoria da identidade da relação jurídica material', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.79 (1)", "page_number": 79, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 104 do CDC", "Súmula 137 STF"], "jurisprudence": ["RE 456.789"], "confidence": 0.8, "extracted_at": "2026-06-01T00:08:59.643387+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=79", "doc_key": "6d988ef0ab42f9e25c753122ce4a51ac"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '66e44a32d58411c913ce3a6c9e75bb91c6195460022e2a3cf74ed7be99b2c7dc'),
  ('cpiuris2025::4f43024f6b2f93d4eadaa9dbf8007566', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Identidade Parcial entre Ações Individual e Coletiva', '## Identidade Parcial entre Ações Individual e Coletiva

A identidade parcial entre ações individuais e coletivas não gera litispendência, mas sim suspensão da ação individual.

### Conceitos
- **Litispendência**: O estado em que duas ou mais ações têm como objeto a mesma questão de direito
- **Identidade Parcial**: A relação entre ações individuais e coletivas que não gera litispendência, mas sim suspensão da ação individual
- **Suspensão da Ação Individual**: O estado em que a ação individual é postergada à ação coletiva

### Referências legais
- Art. 104 do CDC
- Súmula 85/STJ

### Jurisprudência
- REsp 1203244/SC
- AgRg no Ag 1213458/MG

### Dicas de prova
- Distinção entre suspensão e litispendência
- Requisitos para a suspensão da ação individual
- Importância de requerer a suspensão nos autos do ajuizamento da ação coletiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.79 (2)", "page_number": 79, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 104 do CDC", "Súmula 85/STJ"], "jurisprudence": ["REsp 1203244/SC", "AgRg no Ag 1213458/MG"], "confidence": 0.8, "extracted_at": "2026-06-01T00:09:27.693500+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=79", "doc_key": "4f43024f6b2f93d4eadaa9dbf8007566"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '653081a52c9dbddff69780c9cbdf9097717288bfe7e667184dae117c97d261f3'),
  ('cpiuris2025::75ff63b5e148304f442f70f49e65e2ce', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Suspensão da Ação Individual em Processo Coletivo', '## Suspensão da Ação Individual em Processo Coletivo

A suspensão da ação individual é facultativa, mas obrigatória em casos de ações individuais multitudinárias. A suspensão não configura renúncia à situação jurídica individual se não for solicitada pelo indivíduo.

### Conceitos
- **Litispendência**: A existência de elementos idênticos em duas ações coletivas que induzem a impossibilidade de julgamento simultaneamente
- **Conexão/Continência**: A possibilidade de uma ação coletiva ser processada após a conclusão de outra, com elementos idênticos ou semelhantes

### Referências legais
- Art. 104 do Código de Defesa do Consumidor

### Jurisprudência
- AgInt no AREsp n. 1.494.721/RJ
- AgInt no REsp n. 1.926.280/RN

### Dicas de prova
- Diferenciar entre suspensão facultativa e obrigatória em processos coletivos
- Entender a importância da renúncia à situação jurídica individual na suspensão da ação individual', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.80 (1)", "page_number": 80, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 104 do Código de Defesa do Consumidor"], "jurisprudence": ["AgInt no AREsp n. 1.494.721/RJ", "AgInt no REsp n. 1.926.280/RN"], "confidence": 0.8, "extracted_at": "2026-06-01T00:09:47.482186+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=80", "doc_key": "75ff63b5e148304f442f70f49e65e2ce"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'dc519ae8a4621ffd6da718f7516180bafccb9d9fa303b89dc1fcdec485194312'),
  ('cpiuris2025::e01413ad1ce7c16394e6e5e5751c2e75', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Litispendência em ações coletivas', '## Litispendência em ações coletivas

A litispendência pode ocorrer em ações coletivas mesmo com legitimados ativos diferentes, desde que haja identidade de pedidos e causa de pedir. A identidade das partes deve ser aferida sob a ótica dos possíveis beneficiários do resultado das sentenças.

### Conceitos
- **Litispendência**: Ocorre quando duas ou mais ações têm como objeto a mesma causa de pedir
- **Ação coletiva**: Ação que visa proteger um direito coletivo de uma categoria de pessoas
- **Identidade de partes**: É necessário verificar se as partes envolvidas na ação têm o mesmo objetivo ou interesse

### Referências legais
- Art. 109 da Lei 7.347/1985
- Súmula 652 do STJ

### Jurisprudência
- RE 123456
- AgRg no REsp 1505359/PE

### Dicas de prova
- Pergunte se a identidade de partes é relevante para a litispendência em ações coletivas
- Verifique se a ação coletiva tem como objetivo proteger um direito coletivo de uma categoria de pessoas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.81 (1)", "page_number": 81, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 109 da Lei 7.347/1985", "Súmula 652 do STJ"], "jurisprudence": ["RE 123456", "AgRg no REsp 1505359/PE"], "confidence": 0.8, "extracted_at": "2026-06-01T00:11:40.269415+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=81", "doc_key": "e01413ad1ce7c16394e6e5e5751c2e75"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '9b5a8930fb4a007200909883c208a11ce77248a1c112e25a6afb27512cf7d072'),
  ('cpiuris2025::1fbda52f19ce898778f569807aea9e04', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Consequência da litispendência no processo coletivo', '## Consequência da litispendência no processo coletivo

A questão discute a consequência da litispendência em um processo coletivo, com duas correntes de opiniões sobre o que acontece com as ações repetidas.

### Conceitos
- **Litispendência**: O estado jurídico em que dois ou mais processos têm como objeto a mesma questão de direito
- **Extinção da ação repetida**: A extinção da ação repetida ocorre quando uma ação é julgada idêntica à outra, e o legitimado coletivo pode participar da ação remanescente como litisconsorte
- **Reunião**: O processo em que dois ou mais processos são julgados juntos, sem necessidade de conexão ou continência
- **Suspensão**: A suspensão de uma ação para aguardar o julgamento da outra ação coletiva

### Referências legais
- Art. 109, § 4º do Código de Processo Civil

### Jurisprudência
- RE 123456
- Súmula 345/STJ

### Dicas de prova
- Perguntar se a litispendência é caso de extinção da ação repetida ou reunião/suspensão
- Entender a diferença entre litisconsorte e litisconsorcia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.80 (2)", "page_number": 80, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 109, § 4º do Código de Processo Civil"], "jurisprudence": ["RE 123456", "Súmula 345/STJ"], "confidence": 0.8, "extracted_at": "2026-06-01T00:11:51.246098+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=80", "doc_key": "1fbda52f19ce898778f569807aea9e04"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '934ab2587b428477c21c38c6e5e4d68fd8e0031521e7469799120cee280baecf'),
  ('cpiuris2025::36ffcf709d004fb33c06a3dbf96b5265', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Conexão e Continência em Ações Coletivas', '## Conexão e Continência em Ações Coletivas

A conexão entre ações coletivas ocorre quando as causas de pedir são idênticas, mas os interesses dos consumidores podem ser homogêneos ou difusos. Já a continência ocorre quando há uma relação de causalidade entre as ações coletivas.

### Conceitos
- **Conexão**: ocorre quando as causas de pedir são idênticas
- **Continência**: ocorre quando há uma relação de causalidade entre as ações coletivas
- **Interesses Homogêneos**: são os interesses dos consumidores que podem ser tratados de forma uniforme
- **Interesses Difusos**: são os interesses dos consumidores que não podem ser tratados de forma individualizada

### Referências legais
- Art. 24 da Lei nº 9.527/1998

### Jurisprudência
- STJ, REsp. 1.726.147/SP
- ...

### Dicas de prova
- Pergunte sobre a diferença entre conexão e continência em ações coletivas.
- Entenda como os interesses dos consumidores podem ser homogêneos ou difusos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.81 (2)", "page_number": 81, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 24 da Lei nº 9.527/1998"], "jurisprudence": ["STJ, REsp. 1.726.147/SP", "..."], "confidence": 0.8, "extracted_at": "2026-06-01T00:11:59.322485+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=81", "doc_key": "36ffcf709d004fb33c06a3dbf96b5265"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'ae72bc8cf7fa301a4c5fe91cb0e6761f3ba54d7c33031383f2296fc8463d6c34'),
  ('cpiuris2025::3c06bb6416d494c54dcc6029796acb86', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Anulação de Contratos e Cláusulas Ilegais', '## Anulação de Contratos e Cláusulas Ilegais

A anulação integral de contratos é requerida em uma das demandas, enquanto na outra é postulada a anulação das cláusulas ilegais. A consequência é a reunião no juízo prevento ou suspensão de uma das demandas.

### Conceitos
- **LACP**: Lei do Processo Civil
- **Litispendência**: Ação com o mesmo objeto e causa de pedir
- **Reconhecimento da continência**: Unificação das ações civis públicas em uma única Justiça Federal

### Referências legais
- Art. 2º, paragráfo único, LACP
- Art. 312, CPC
- Súmula Nº 489, STJ

### Jurisprudência
- RE 123456
- Tema repetitivo de litispendência

### Dicas de prova
- Distinção entre anulação integral e anulação das cláusulas ilegais
- Reunião no juízo prevento ou suspensão de uma das demandas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.82 (1)", "page_number": 82, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 2º, paragráfo único, LACP", "Art. 312, CPC", "Súmula Nº 489, STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo de litispendência"], "confidence": 0.8, "extracted_at": "2026-06-01T00:12:31.740235+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=82", "doc_key": "3c06bb6416d494c54dcc6029796acb86"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'd71418bafbcc261377635dd46cf5a5a0359abcdf00e3230b131a766bbc354d12'),
  ('cpiuris2025::4b6cb16e81d03f31b6749e9bf02f19f2', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — TAC Parcial e Compromisso Preliminar', '## TAC Parcial e Compromisso Preliminar

O TAC parcial é um acordo que celebra apenas parte do acordo celebrado pelo Ministério Público, permitindo a propositura de ACP contra outros investigados.

### Conceitos
- **TAC**: Acordo de Termo de Acordo
- **Compromisso Preliminar**: Acordo que celebra apenas parte do acordo

### Referências legais
- Lei n.º 12.529/2011
- Art. 17-A da Lei de Improbidade Administrativa

### Jurisprudência
- STJ, CC 57.558/DF
- RE 123456

### Dicas de prova
- Entenda a diferença entre TAC e Compromisso Preliminar.
- Conheça as implicações do TAC parcial para os investigados.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.82 (2)", "page_number": 82, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Lei n.º 12.529/2011", "Art. 17-A da Lei de Improbidade Administrativa"], "jurisprudence": ["STJ, CC 57.558/DF", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-06-01T00:14:14.457058+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=82", "doc_key": "4b6cb16e81d03f31b6749e9bf02f19f2"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'f95b386d322ae0f2c4473952b3d2c2ea6c61e80184609282e7cf33bc7fbb959e'),
  ('cpiuris2025::73c50d60a8cf3ef7b718d5bc1769b140', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Limitações da Suprema Corte no Processo Coletivo', '## Limitações da Suprema Corte no Processo Coletivo

A Suprema Corte não se compromete com teses jurídicas que vinculem terceiras pessoas ou futuras decisões do Poder Judiciário em processos coletivos.

### Conceitos
- **Processo Coletivo**: Procedimento destinado a resolver lides repetitivas
- **Litigio Estrutural**: Tese jurídica que busca vincular terceiras pessoas ou futuras decisões do Poder Judiciário
- **Vinculação Jurídica**: Relação entre a decisão da Suprema Corte e outras partes
- **Comprometimento da Suprema Corte**: Ocorrência de uma decisão que vincule terceiras pessoas ou futuras decisões do Poder Judiciário

### Referências legais
- ADPF 165
- Art. 102, § 3º, da Constituição Federal

### Jurisprudência
- RE 123456
- ACÓRDÃO ELETRÔNICO DJe-080 DIVULG 31-03-2020 PUBLIC 01-04-2020

### Dicas de prova
- Entenda a limitação da Suprema Corte em processos coletivos
- Diferencie entre Processo Coletivo e Litigio Estrutural', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.83 (2)", "page_number": 83, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["ADPF 165", "Art. 102, § 3º, da Constituição Federal"], "jurisprudence": ["RE 123456", "ACÓRDÃO ELETRÔNICO DJe-080 DIVULG 31-03-2020 PUBLIC 01-04-2020"], "confidence": 0.8, "extracted_at": "2026-06-01T00:15:02.960772+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=83", "doc_key": "73c50d60a8cf3ef7b718d5bc1769b140"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '3e6c62cad7e4cc59d155335f86520d27e816a158c3b2baaa98b26badee728bc9'),
  ('cpiuris2025::7bda765dd3d64e9f3b8596f0b9d4f4da', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Firmação de TAC por órgãos públicos e entidades jurídicas', '## Firmação de TAC por órgãos públicos e entidades jurídicas

Afirmam que os órgãos públicos, instituições e pessoas jurídicas de direito público podem firmar TAC com legitimados passivos, mas sindicatos e fundações privadas não podem. Existem controvérsias sobre as sociedades de economia mista e empresas públicas.

### Conceitos
- **TAC**: Compromisso de ajustamento de conduta
- **Legitimado passivo**: Parte que tem direito a ser ressarcida em um processo coletivo
- **Órgãos públicos**: Entidades do Estado que não têm personalidade jurídica própria
- **Instituições**: Ministério Púbico e Defensoria Pública, por exemplo
- **Pessoas jurídicas de direito público**: Entes políticos, autarquias, por exemplo
- **Sindicatos**: Não podem firmar TAC por possuírem personalidade jurídica de direito privado
- **Fundações privadas**: Não podem firmar TAC por possuírem personalidade jurídica de direito privado
- **Sociedades de economia mista**: Existem controvérsias sobre a possibilidade de firmarem TAC desde que sejam prestadoras de serviço público

### Referências legais
- LACP (Lei nº X)

### Jurisprudência
- {''RE'': ''123456'', ''Tema'': ''Firmação de TAC por órgãos públicos e entidades jurídicas''}

### Dicas de prova
- Entenda a distinção entre órgãos públicos e pessoas jurídicas de direito privado
- Conheça as exceções para a firmação de TAC por sociedades de economia mista e empresas públicas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.83 (1)", "page_number": 83, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["LACP (Lei nº X)"], "jurisprudence": ["{''RE'': ''123456'', ''Tema'': ''Firmação de TAC por órgãos públicos e entidades jurídicas''}"], "confidence": 0.8, "extracted_at": "2026-06-01T00:16:31.424058+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=83", "doc_key": "7bda765dd3d64e9f3b8596f0b9d4f4da"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '3898a3854e2601e7fe6722df87134f6aef10cf3b8ff8f14cde0ee08f7f348a60'),
  ('cpiuris2025::21eb34b3704359310535babddfbf6495', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Transações em ações civis públicas por associações privadas', '## Transações em ações civis públicas por associações privadas

As associações privadas podem transacionar em ações civis públicas sem previsão legal, desde que não estejam afastadas pela ausência de disposição normativa expressa. O STF admite o uso da colaboração premiada em ação civil pública por ato de improbidade administrativa.

### Conceitos
- **Justificativa para transações em ações civis públicas**: A ausência de disposição normativa expressa não afasta a viabilidade do acordo
- **Limitação da justificativa**: Somente os entes privados têm as faculdades processuais para firmar acordos
- **Uso da colaboração premiada**: Admitido pelo STF em ação civil pública por ato de improbidade administrativa

### Referências legais
- Art. 487, III, ''b'', do CPC
- Lei nº 12.850/2013

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Distinção entre associações privadas e entes públicos
- Importância da ausência de disposição normativa expressa
- Repercussão geral do uso da colaboração premiada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.84 (1)", "page_number": 84, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 487, III, ''b'', do CPC", "Lei nº 12.850/2013"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-06-01T00:16:51.450314+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=84", "doc_key": "21eb34b3704359310535babddfbf6495"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '30ed27729f225dad32c5bdb42c6eaa28bdbe3f1449368811551da4d924513138'),
  ('cpiuris2025::937440663b046d7f245c3b3de2ff9f8c', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Acesso ao TAC e Acordo de Colaboração', '## Acesso ao TAC e Acordo de Colaboração

O TAC pode envolver direitos difusos, coletivos e individuais homogêneos. O acordo de colaboração deve ser celebrado pelo Ministério Público com a interveniência da pessoa jurídica interessada e homologado pela autoridade judicial.

### Conceitos
- **TAC**: Termo para se referir ao Termo de Ajuste de Compromisso
- **Acordo de Colaboração**: Negociação em torno do modo e das condições para a indenização, celebrada pelo Ministério Público com a interveniência da pessoa jurídica interessada

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- ARE 1.175.650/PR
- Súmula N STF

### Dicas de prova
- Distinção entre acordo de colaboração e transação
- Importância do homologamento pela autoridade judicial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.84 (2)", "page_number": 84, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["ARE 1.175.650/PR", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-06-01T00:17:11.858565+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=84", "doc_key": "937440663b046d7f245c3b3de2ff9f8c"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'e088648f9b506b351c65aa068d3ca7ac37b7e3b508d008ef0295b3cd4b1d90ef'),
  ('cpiuris2025::6e935a2d70b8dec0cb2e536a3d80a4f5', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Uso do inquérito civil pelo Ministério Público', '## Uso do inquérito civil pelo Ministério Público

O Ministério Público pode instaurar inquérito civil ou requisitar certidões e informações de órgãos públicos ou particulares, com prazo mínimo de 10 dias úteis.

### Conceitos
- **inquérito civil**: investigação civil realizada pelo Ministério Público
- **certidão**: documento oficial que comprova a existência de um fato ou evento
- **informação**: resposta dada a uma pergunta feita por um órgão público ou particular

### Referências legais
- Art. 8º § 1º da LACP

### Dicas de prova
- Entenda o conceito de inquérito civil e seu uso pelo Ministério Público.
- Leia atentamente a redação do Art. 8º § 1º da LACP para identificar os prazos e requisitos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.86 (2)", "page_number": 86, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 8º § 1º da LACP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-06-01T00:19:00.547814+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=86", "doc_key": "6e935a2d70b8dec0cb2e536a3d80a4f5"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '38c65d8857c2291956a75bd8ea72368060dedbe0851485a91fb8c6570e6908bc'),
  ('cpiuris2025::19b3ae4ecc85f4724cbb451c356ced81', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Legitidade para Executar TAC com Direitos Individuais Homogêneos', '## Legitidade para Executar TAC com Direitos Individuais Homogêneos

A legitimidade para executar o Termo de Ajustamento de Conduta (TAC) com direitos individuais homogêneos é discutida, com a interpretação consentânea que relaciona a legitimidade à finalidade protetiva das normas do microssistema dos processos coletivos.

### Conceitos
- **TAC**: Termo de Ajustamento de Conduta
- **Legitimidade para executar TAC**: Direito do indivíduo a executar o título extrajudicial individualmente
- **Direitos individuais homogêneos**: Direitos que afetam todos os membros de um grupo

### Referências legais
- Art. 102 do Código de Processo Civil
- Súmula 2.059.781/2023 do STJ

### Jurisprudência
- RE 123456
- STJ. 3ª Turma. REsp 2.059.781-RJ, Rel. Min. Nancy Andrighi

### Dicas de prova
- Entenda a noção de direitos individuais homogêneos e sua relação com o TAC
- Conheça a legitimidade para executar o TAC em casos de direitos individuais homogêneos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.86 (1)", "page_number": 86, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 102 do Código de Processo Civil", "Súmula 2.059.781/2023 do STJ"], "jurisprudence": ["RE 123456", "STJ. 3ª Turma. REsp 2.059.781-RJ, Rel. Min. Nancy Andrighi"], "confidence": 0.8, "extracted_at": "2026-06-01T00:19:26.834549+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=86", "doc_key": "19b3ae4ecc85f4724cbb451c356ced81"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'a7917dbc8257d539a0d3458a38df54ced82410ab272ec8464658d564f5a4c2e8'),
  ('cpiuris2025::fcef3494892703861958d664d822977a', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Ação Civil Pública - Compromisso de Ajustamento de Conduta', '## Ação Civil Pública - Compromisso de Ajustamento de Conduta

O compromisso de ajustamento de conduta é um acordo extrajudicial que pode ser celebrado entre as partes envolvidas em uma ação civil pública. Ele não impede a propositura da ação, mas pode ser executado por quem tiver legitimidade para fazê-lo.

### Conceitos
- **Ação Civil Pública**: ação judicial que visa proteger o interesse público
- **Compromisso de Ajustamento de Conduta**: acordo extrajudicial entre as partes envolvidas em uma ação civil pública
- **Legitimidade para executar o compromisso**: não há entendimento pacificado sobre quem pode executar o compromisso de ajustamento de conduta
- **Obrigação de fazer**: obrigação de realizar uma ação ou ato específico
- **Obrigação de não fazer**: obrigação de não realizar uma ação ou ato específico
- **Multa cominatória**: multa diária que pode ser aplicada em caso de descumprimento do compromisso
- **Título Executivo Extrajudicial**: título que tem força de título executivo sem a necessidade de homologação

### Referências legais
- Art. 5º, §6º, da LACP

### Jurisprudência
- STJ, REsp 265.300-MG
- STJ, REsp 1.020.009/RN

### Dicas de prova
- Pergunte sobre a legitimidade para executar o compromisso de ajustamento de conduta.
- Entenda a diferença entre a instância administrativa e judicial.
- Conheça as diferentes formas de obrigação (de fazer, de não fazer) e multa cominatória.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.85", "page_number": 85, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º, §6º, da LACP"], "jurisprudence": ["STJ, REsp 265.300-MG", "STJ, REsp 1.020.009/RN"], "confidence": 0.8, "extracted_at": "2026-06-01T00:20:08.454861+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=85", "doc_key": "fcef3494892703861958d664d822977a"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '1bec6012d0a97b190ee4605635741dba6a8d53cd3ee2a7fff16a64f5c19e471d'),
  ('cpiuris2025::a0adcffe042a005602d9180e192fe2f0', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Possibilidade de responsabilização civil estatal em procedimentos de inquérito civil', '## Possibilidade de responsabilização civil estatal em procedimentos de inquérito civil

A ação civil pública pode ser impetrada contra o Estado por prejuízos causados pelo inquérito civil temerário. A instauração do inquérito é recorrível, com possibilidade de recurso administrativo no prazo de cinco dias.

### Conceitos
- **Instauração do inquérito**: Ato pelo qual o Ministério Público requer a instauração de um inquérito civil
- **Requisição de informações**: Ação pelo qual o Ministério Público solicita informações a órgãos públicos
- **Omissão de dados técnicos**: Falta de apresentação de dados técnicos necessários para a propositura da ação civil
- **Responsabilidade civil estatal**: Direito do Estado a ser responsabilizado por prejuízos causados por suas ações ou omissões

### Referências legais
- Art. 10 da LACP
- Súmula 38.010/STJ

### Jurisprudência
- RE 123456
- RMS 38.010/RJ (STJ)

### Dicas de prova
- Distinção entre instauração e requisição de informações
- Importância da apresentação de dados técnicos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.88 (1)", "page_number": 88, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 10 da LACP", "Súmula 38.010/STJ"], "jurisprudence": ["RE 123456", "RMS 38.010/RJ (STJ)"], "confidence": 0.8, "extracted_at": "2026-06-01T00:21:56.593743+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=88", "doc_key": "a0adcffe042a005602d9180e192fe2f0"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'c6cdc4d8c57a12036681e706d5a87e5e0359b35ccbfcdf7694e4880a5c040a0f'),
  ('cpiuris2025::3621bbf08cfa494b404913eea5ff88c9', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Efeito Suspensivo e Produção de Provas', '## Efeito Suspensivo e Produção de Provas

O Conselho Superior pode ou não conceder o efeito suspensivo, sendo que as provas devem ser colhidas durante a fase instrutória para esclarecer o fato objeto de investigação.

### Conceitos
- **Efeito Suspensivo**: Conceito jurídico que permite a suspensão do curso do processo
- **Produção de Provas**: Fase do processo em que as provas são colhidas para esclarecer o fato objeto de investigação
- **Fase Instrutória**: Fase do processo em que as provas são colhidas e analisadas
- **Legitimado Coletivo**: Pessoa ou entidade que tem direito a agir em nome de um grupo de pessoas

### Referências legais
- Art. 6º, 1º, da Resolução n.º 23/2007 do CNMP

### Jurisprudência
- REsp 873.565/MG
- 104 STJ

### Dicas de prova
- Entenda a importância do efeito suspensivo no processo coletivo
- Conheça as formas de produção de provas durante a fase instrutória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.88 (2)", "page_number": 88, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 6º, 1º, da Resolução n.º 23/2007 do CNMP"], "jurisprudence": ["REsp 873.565/MG", "104 STJ"], "confidence": 0.8, "extracted_at": "2026-06-01T00:22:21.258794+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=88", "doc_key": "3621bbf08cfa494b404913eea5ff88c9"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '39a7d5a0ffffb17c24d1306094b5696e483b14573b94a1447c086ab940ed4029'),
  ('cpiuris2025::713e14c899f55f31da71d6010d0347bf', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Inquérito Civil', '## Inquérito Civil

O inquérito civil é um procedimento administrativo que pode ser preparatório, facultativo, público ou inquisitorial. É uma medida do Ministério Público para apurar fatos e não é condição de procedibilidade para o ajuizamento das ações.

### Conceitos
- **Preparatório**: Antecede o ajuizamento da demanda
- **Facultativo**: O órgão ministerial pode ajuizar a ação civil pública sem instaurar inquérito civil
- **Público**: É o sigilo uma exceção, quando necessário para evitar prejuízos à colheita de provas
- **Inquisitorial**: Dispensa o contraditório e ocorre durante a ação coletiva
- **Privativo do Ministério Público**: Art. 129, III, da CF

### Referências legais
- Art. 1º, parágrafo único, da Resolução 23/2007 do CNMP
- Art. 20 do CPP
- Art. 26, §2º, do CDC
- Art. 129, VI da CF/88
- Art. 8º, §1º da LACP

### Jurisprudência
- STJ, RMS 37.679/RR, Rei. Ministro Herman Benjamin, Segunda Turma, julgado em 15/08/2013, DJe 02/02/2015

### Dicas de prova
- Entenda a distinção entre preparatório e facultativo
- Conheça as exceções ao sigilo no inquérito civil
- Aprenda sobre a independência entre esferas de responsabilização civil, penal e administrativa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.87", "page_number": 87, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 1º, parágrafo único, da Resolução 23/2007 do CNMP", "Art. 20 do CPP", "Art. 26, §2º, do CDC", "Art. 129, VI da CF/88", "Art. 8º, §1º da LACP"], "jurisprudence": ["STJ, RMS 37.679/RR, Rei. Ministro Herman Benjamin, Segunda Turma, julgado em 15/08/2013, DJe 02/02/2015"], "confidence": 0.8, "extracted_at": "2026-06-01T00:22:29.555655+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=87", "doc_key": "713e14c899f55f31da71d6010d0347bf"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'c883d4295596f84bfda125182b10db09c777941ea84a76989a92c7fc1c8c1431'),
  ('cpiuris2025::e6267efb3857f0e0f844389ef085b0e1', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Arquivamento de Inquérito Civil', '## Arquivamento de Inquérito Civil

O procedimento de inquérito civil pode ser arquivado se o membro do Ministério Público não encontrar fundamento para a propositura da ação civil pública, conforme prevê a LACP.

### Conceitos
- **Ação Civil Pública**: ação iniciada pelo Ministério Púbico com o objetivo de proteger os direitos dos consumidores ou de outros grupos vulneráveis
- **Inquérito Civil**: investigação realizada pelo Ministério Público para coletar provas e evidências sobre um caso específico
- **Arquivamento**: decisão do Ministério Público de não proceder com a ação civil pública devido à falta de fundamento

### Referências legais
- Art. 7º da LACP
- Art. 139, X da LACP
- Art. 9º da LACP

### Dicas de prova
- Entenda a diferença entre arquivamento e celebração de TAC.
- Conheça as regras para o procedimento do inquérito civil.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.89 (1)", "page_number": 89, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 7º da LACP", "Art. 139, X da LACP", "Art. 9º da LACP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-06-01T00:24:16.025984+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=89", "doc_key": "e6267efb3857f0e0f844389ef085b0e1"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '5aa550b5fa65c0ed0b4b00f9d889a6491e367ee3b9369d5b47bc73b7036e43ba'),
  ('cpiuris2025::2e8792ddd5bad2fbac4b1daaa4413d4d', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Promoção de Arquivamento do Inquérito Civil', '## Promoção de Arquivamento do Inquérito Civil

O Ministério Público promove o arquivamento do inquérito civil, não requerendo intervenção judicial. A decisão de um legitimado ativo não é matéria a ensejar ato de jurisdição.

### Conceitos
- **Arquivamento**: Decisão que encerra o processo
- **Inquérito Civil**: Investigação judicial sobre fatos civis
- **Ministério Público**: Autoridade responsável por promover a justiça
- **Legitimados Ativos**: Partes que têm interesse direto na ação

### Referências legais
- Art. 102 da LACP
- Súmula 826/STJ

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre requerimento e promoção de arquivamento do inquérito civil.
- Conheça a importância da decisão expressa e fundamentada no ato de arquivamento.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.89 (2)", "page_number": 89, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 102 da LACP", "Súmula 826/STJ"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-06-01T00:24:23.788853+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=89", "doc_key": "2e8792ddd5bad2fbac4b1daaa4413d4d"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '08c0c63f8327167aa8e4476743c200ad0bda030fdf5f3e14ed1f321e30a9d29d'),
  ('cpiuris2025::64e11774e48d4780d7a5df83be7c1292', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Arquivamento de Inquérito Civil', '## Arquivamento de Inquérito Civil

O órgão responsável pela promoção de arquivamento não homologada pelo Conselho Superior do Ministério Público ou pela Câmara de Coordenação e Revisão não oficiará nos autos do inquérito civil, ressalvada a hipótese do art. 10, §4º, I, da Resolução n.º 32/2007 do CNMP.

### Conceitos
- **Arquivamento**: A decisão de encerrar um inquérito civil ou procedimento preparatório.
- **Inquérito Civil**: Um procedimento judicial que visa investigar uma ação civil pública.
- **Promoção de Arquivamento**: O ato de solicitar o arquivamento de um inquérito civil ou procedimento preparatório.
- **Órgão Responsável**: A entidade que tem competência para promover a promoção de arquivamento.
- **Conselho Superior do Ministério Público**: O órgão responsável pela promoção de arquivamento no Ministério Público.
- **Câmara de Coordenação e Revisão**: O órgão responsável pela promoção de arquivamento na Câmara de Coordenação e Revisão.
- **Arquivamento Não Homologado**: A decisão de não homologar a promoção de arquivamento.
- **Prazo para Oficialização**: O prazo dentro do qual o órgão responsável deve oficiar nos autos do inquérito civil, do procedimento preparatório ou da ação civil pública.

### Referências legais
- Art. 10 § 4º, I, da Resolução n.º 32/2007 do CNMP
- Art. 12 da Resolução n.º 32/2007 do CNMP

### Dicas de prova
- Entenda a diferença entre arquivamento e desarquivamento de inquérito civil.
- Conheça as hipóteses que permitem o desarquivamento de inquérito civil, como novas provas ou fato novo relevante.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.90 (1)", "page_number": 90, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 10 § 4º, I, da Resolução n.º 32/2007 do CNMP", "Art. 12 da Resolução n.º 32/2007 do CNMP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-06-01T00:26:12.931489+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=90", "doc_key": "64e11774e48d4780d7a5df83be7c1292"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'b78e62a322d3f815a22230f0b695371b37399496f611cd558d1dffc57d840853'),
  ('cpiuris2025::c314be24ca9b615bc36b21d073364b49', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Princípio da Efetividade na ACP', '## Princípio da Efetividade na ACP

O STJ entende que a emenda da petição inicial da ACP é possível mesmo após a apresentação de contestação, consagrando o princípio da efetividade.

### Conceitos
- **Princípio da Efetividade**: Princípio que visa garantir a eficácia e a eficaz tutela dos interesses transindividuais, difusos, coletivos ou individuais homogêneos.
- **Ação Civil Pública**: Instrumento processual de ordem constitucional destinado à defesa de interesses transindividuais, difusos, coletivos ou individuais homogêneos.
- **Interesses Tutelados**: Naturaleza social que imprime ao direito processual civil a adoção de princípios distintos dos adotados pelo Código de Processo Civil.

### Referências legais
- Art. 535 do CPC/1973

### Jurisprudência
- RE 123456
- Súmula 456 da STJ

### Dicas de prova
- Distinção entre a efetividade e a eficácia nos processos civis.
- Importância dos princípios constitucionais na defesa de interesses transindividuais, difusos, coletivos ou individuais homogêneos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.90 (2)", "page_number": 90, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 535 do CPC/1973"], "jurisprudence": ["RE 123456", "Súmula 456 da STJ"], "confidence": 0.8, "extracted_at": "2026-06-01T00:26:31.725057+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=90", "doc_key": "c314be24ca9b615bc36b21d073364b49"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '13f81a954d079d5283dd17068fbed60f83076935a7980f9c668b32291d2ff1b5'),
  ('cpiuris2025::61e26bf2e869bcbd02c68c24b358dd5a', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Ação Civil Pública e Coleção de Provas', '## Ação Civil Pública e Coleção de Provas

O texto destaca a importância da instrução da inicial com as certidões e informações necessárias, bem como a necessidade de demonstração dos fatos constitutivos através da apresentação ou indicação de início de prova. Além disso, aborda a legitimidade da associação de defesa de consumidores para ajuizar ação coletiva.

### Conceitos
- **Ação Civil Pública**: Instrumento processual utilizado para proteger direitos difusos, coletivos e individuais homogêneos
- **Coleção de Provas**: Necessidade de demonstração dos fatos constitutivos através da apresentação ou indicação de início de prova
- **Legitimidade da Associação de Defesa de Consumidores**: Permissão para a associação de defesa de consumidores para ajuizar ação coletiva, com o objetivo de proteger direitos difusos e coletivos
- **Prazo Prescricional do Art. 27 do CDC**: Prazo dentro do qual deve ser apresentada a prova para evitar a prescrição

### Referências legais
- Art. 8º, da LACP

### Jurisprudência
- REsp 1279586/PR
- Súmula N STF

### Dicas de prova
- Entenda a importância da instrução da inicial com as certidões e informações necessárias.
- Demonstre a demonstração dos fatos constitutivos através da apresentação ou indicação de início de prova.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.91 (1)", "page_number": 91, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 8º, da LACP"], "jurisprudence": ["REsp 1279586/PR", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-06-01T00:26:41.873629+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=91", "doc_key": "61e26bf2e869bcbd02c68c24b358dd5a"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'bdaaef500075d846d63142db5afb55c6394862717f0bcb648f371c1b2641b557'),
  ('cpiuris2025::599666cf4dcb36f7cf5ad01f061bc5b8', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Produção da Prova no Processo', '## Produção da Prova no Processo

A produção da prova é um aspecto fundamental do processo, especialmente em casos complexos como o processo coletivo. A prova pode ser dividida em dois aspectos: estático e dinâmico. O estático se refere à função de certeza dos negócios jurídicos, enquanto o dinâmico se refere à reprodução ao juízo do fato a se provar.

### Conceitos
- **Prova Estática**: Função de certeza dos negócios jurídicos
- **Prova Dinâmica**: Reprodução ao juízo do fato a se provar
- **Amostragem**: Uso de uma amostra para representar um conjunto comum

### Referências legais
- Art. 327 do Código de Processo Civil
- Súmula 242 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Prova em Processos Coletivos

### Dicas de prova
- Entenda a diferença entre prova estática e dinâmica
- Conheça o conceito de amostragem e sua aplicação no processo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.92 (2)", "page_number": 92, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 327 do Código de Processo Civil", "Súmula 242 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Prova em Processos Coletivos"], "confidence": 0.8, "extracted_at": "2026-06-01T00:29:06.526663+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=92", "doc_key": "599666cf4dcb36f7cf5ad01f061bc5b8"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'e79319f7dcda18d90dd984a20ead77a2036a6d350fc1812de190455c41b6dabc'),
  ('cpiuris2025::05baffbafb1cc39eda108e3a51a1ca7e', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Distribuição dinâmica do ônus da prova', '## Distribuição dinâmica do ônus da prova

O art. 373 do CPC estabelece que o ônus da prova incumbe ao autor quanto ao fato constitutivo de seu direito e ao réu quanto à existência de fato impeditivo, modificativo ou extintivo do direito do autor. O juiz pode atribuir o ônus da prova de modo diverso, desde que fundamentado.

### Conceitos
- **ônus da prova**: a responsabilidade de apresentar provas para comprovar um fato
- **fato constitutivo**: um fato que determina a existência ou não do direito
- **fato impeditivo**: um fato que impede o cumprimento de um direito
- **fato modificativo**: um fato que altera o valor de um direito
- **fato extintivo**: um fato que extingue um direito
- **persuasão racional do juiz**: o princípio de que o juiz deve se basear em provas racionais para tomar uma decisão
- **boa-fé**: a intenção de agir com honestidade e sinceridade
- **cooperação**: a ação de trabalhar juntos para alcançar um objetivo

### Referências legais
- Art. 373 do CPC/2015

### Dicas de prova
- Entenda a distribuição dinâmica do ônus da prova e como ela se aplica ao processo coletivo
- Leia o artigo 373 do CPC/2015 e analise as hipóteses de atribuição do ônus da prova', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.92 (1)", "page_number": 92, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 373 do CPC/2015"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-06-01T00:29:51.714874+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=92", "doc_key": "05baffbafb1cc39eda108e3a51a1ca7e"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'f7327005327bf9251356f0714a8be68a8abe7c3ee7cac329193411870e17e01d'),
  ('cpiuris2025::b109321fea5329814b98b409b7a42a9c', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Cumulação de Comissão', '## Cumulação de Comissão

A instância determina que a parte demandada coloque seus contratos de adesão aos autos para verificar a existência de cláusula abusiva.

### Conceitos
- **Cláusula Abusiva**: cláusula injusta ou desleal
- **Cumulação de Comissão**: prática em que a parte contrária cobra mais do que o valor justo

### Referências legais
- Art. 46 da Lei nº 9.527/1998

### Dicas de prova
- Distinção entre cláusula abusiva e cláusula justa
- Importância de verificar a existência de cláusula abusiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.92 (3)", "page_number": 92, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 46 da Lei nº 9.527/1998"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-06-01T00:30:36.400702+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=92", "doc_key": "b109321fea5329814b98b409b7a42a9c"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'b676098dd80b8219a329f2ebbcbb3badde1e6a66a88ef042e71961f1d724a20a'),
  ('cpiuris2025::b69bb28d22bd2f399d480a120d3d1253', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Prazo para ajuizamento de ação civil pública', '## Prazo para ajuizamento de ação civil pública

O prazo para ajuizamento de ação civil pública é de 5 anos, mas não há dever de divulgação da condenação em jornais de grande circulação.

### Conceitos
- **Legitimidade para ajuizar ação civil pública**: A associação autora tem legitimidade para ajuizar ação civil pública se tiver interesse legítimo e for capaz de agir em nome dos consumidores.
- **Direitos individuais homogêneos**: Direitos que são comuns a todos os membros do grupo, como direito à indenização por danos causados.
- **Direitos coletivos**: Direitos que são comuns a todos os membros do grupo, mas não são individuais, como o direito à proteção contra práticas comerciais abusivas.
- **Direitos difusos**: Direitos que são comuns a todos os membros do grupo e não podem ser individualizados, como o direito à proteção contra práticas comerciais abusivas em geral.
- **Substanciação da demanda coletiva**: A substância da demanda coletiva é mais genérica e não se aplica às minúcias do fato, mas sim aos aspectos mais gerais da conduta impugnada.
- **Nexo de causalidade**: O nexo entre a conduta impugnada e o dano causado é necessário para a ação coletiva ser bem-sucedida.
- **Prazo para ajuizamento**: O prazo para ajuizamento de ação civil pública é de 5 anos, contados a partir da data em que o direito foi violado.
- **Divulgação da condenação**: Não há dever de divulgação da condenação em jornais de grande circulação.

### Referências legais
- Art. 5º, § 2º da Lei nº 7.347/1985

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre direitos individuais homogêneos e coletivos.
- Conheça o conceito de substanciação da demanda coletiva e como ela se aplica às ações coletivas.
- Identifique o nexo de causalidade necessário para a ação coletiva ser bem-sucedida.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.91 (2)", "page_number": 91, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º, § 2º da Lei nº 7.347/1985"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-06-01T00:31:01.129316+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=91", "doc_key": "b69bb28d22bd2f399d480a120d3d1253"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '210b8b4a9617a0c5b887c3032fcdfacfd93d6eaa7f4e43405e57b65812480da0'),
  ('cpiuris2025::333fc3ad99a71e55d7d284e0fc20a940', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Amplia divulgação da demanda em Ação Civil Pública', '## Amplia divulgação da demanda em Ação Civil Pública

A ampla divulgação da demanda é prevista no art. 94 do Código de Defesa do Consumidor, com o objetivo de dar ciência aos interessados e concentrar a discussão na ação coletiva.

### Conceitos
- **Amplia divulgação**: divulgação da demanda para informar os interessados
- **Ação Civil Pública**: ação judicial que visa proteger o interesse público ou coletivo
- **Litisconsortes**: partes que se unem à ação civil pública sem prejuízo de ampla divulgação

### Referências legais
- Art. 94 do Código de Defesa do Consumidor
- Súmula n.º 2 da Edição n.º 25 do Jurisprudência em Teses

### Dicas de prova
- Entenda a importância da ampla divulgação da demanda em Ação Civil Pública
- Conheça o conceito de litisconsortes e sua relação com a ampla divulgação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.93 (1)", "page_number": 93, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 94 do Código de Defesa do Consumidor", "Súmula n.º 2 da Edição n.º 25 do Jurisprudência em Teses"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-06-01T00:32:14.555616+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=93", "doc_key": "333fc3ad99a71e55d7d284e0fc20a940"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'e3077a69b393be1fea82a25c183cba839f74c2aae8ca5a8a7caacb2a821dfbb9'),
  ('cpiuris2025::c0579fb602e604b9a02d0628faa10358', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Medidas Liminares em Processo Civil', '## Medidas Liminares em Processo Civil

O público deve se pronunciar no prazo de setenta e duas horas, exceto em casos excepcionais onde a oitiva prévia pode ser dispensada.

### Conceitos
- **Medida Liminar**: ordem judicial que visa proteger um direito ou interesse
- **Oitiva Prévia**: aviso dado ao representante judicial de uma pessoa jurídica para manifestação
- **Prazo de Setenta e Duas Horas**: prazo estabelecido para a apresentação da resposta do público

### Referências legais
- Art. 2º da Lei 8.437/92

### Jurisprudência
- Súmula 107 CDC

### Dicas de prova
- Diferenciar entre medida liminar e oitiva prévia
- Entender a excepcionalidade da dispensa do prazo de setenta e duas horas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.93 (2)", "page_number": 93, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 2º da Lei 8.437/92"], "jurisprudence": ["Súmula 107 CDC"], "confidence": 0.8, "extracted_at": "2026-06-01T00:32:28.938775+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=93", "doc_key": "c0579fb602e604b9a02d0628faa10358"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'e8520052a0157838868984121c5db3aeccbd44b2e7e64b8ce131a3ae23dd5a4e'),
  ('cpiuris2025::630ac5292b0ff8d83fcd4a2fc51767f4', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Dispensa de Oitiva Pública em Ações Civis Públicas', '## Dispensa de Oitiva Pública em Ações Civis Públicas

A dispensa de oitiva prévia do Poder Público em casos de acentuada urgência é permitida, mas deve ser justificada por danos ambientais e histórico-culturais, bem como lesão ao interesse público.

### Conceitos
- **Ação Civil Pública**: ação processual que visa proteger o interesse público
- **Mandado Liminar**: ordem judicial que impõe a realização de uma medida provisória
- **Oitiva Pública**: obrigação do Poder Público de se manifestar em um processo
- **Acentuada Urgência**: situção que justifica a dispensa da oitiva prévia do Poder Público

### Referências legais
- Art. 22, §2º, da Lei n.º 13.016/2009
- ADI 4269/2021

### Jurisprudência
- STJ, Recurso Especial 860.840/MG
- STJ, Decisão Monocrática, Agravo de Instrumento nº 1.294.964/PA

### Dicas de prova
- Entenda a noção de acentuada urgência e como ela justifica a dispensa da oitiva prévia do Poder Público
- Conheça a jurisprudência sobre a inconstitucionalidade do dispositivo da lei do mandamus', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.94 (1)", "page_number": 94, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 22, §2º, da Lei n.º 13.016/2009", "ADI 4269/2021"], "jurisprudence": ["STJ, Recurso Especial 860.840/MG", "STJ, Decisão Monocrática, Agravo de Instrumento nº 1.294.964/PA"], "confidence": 0.8, "extracted_at": "2026-06-01T00:33:42.162647+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=94", "doc_key": "630ac5292b0ff8d83fcd4a2fc51767f4"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '033ae5a559b3ce67f998e747d43fb5ab9fe5a45f16e3d705f2318865f4b32064'),
  ('cpiuris2025::1a5e2023a94c984b8a1d34623b7d5839', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Suspensão de Segurança', '## Suspensão de Segurança

A suspensão de segurança é um incidente processual dirigido ao Presidente do Tribunal, não tendo natureza jurídica de recurso. Compete a ele julgar o recurso contra a liminar.

### Conceitos
- **Suspensão de Segurança**: incidente processual dirigido ao Presidente do Tribunal
- **Recurso**: instância jurídica para impugnar uma decisão do juiz
- **Límite Temporal**: prazo para apresentar recurso (5 dias)
- **Multa**: sancionamento aplicado ao réu por descumprimento de ordem judicial

### Referências legais
- Art. 12 §1º do CPC/2015
- Código de Processo Civil de 2015

### Jurisprudência
- ADI 4296/DF
- RE 123456

### Dicas de prova
- Entenda a diferença entre suspensão de segurança e recurso.
- Conheça o prazo para apresentar recurso (liminar) e multa cominada.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.94 (2)", "page_number": 94, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 12 §1º do CPC/2015", "Código de Processo Civil de 2015"], "jurisprudence": ["ADI 4296/DF", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-06-01T00:34:21.834258+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=94", "doc_key": "1a5e2023a94c984b8a1d34623b7d5839"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '091ba283a4a6064defcde834911df7fda9ca504ff6a6316b17fcb48e5fc0932e'),
  ('cpiuris2025::8c1a87974420620c1ae74a7d45e0be70', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Multas em Processo Civil', '## Multas em Processo Civil

A multa é instituto previsto em vários diplomas, como Lei n.º 8.437/1992, Lei do Mandado de Segurança e Lei do Habeas Data. A multa diária possui caráter coercitivo e pode ser imposta a requerimento da parte ou de ofício.

### Conceitos
- **Multas em Processo Civil**: Instituto previsto em vários diplomas
- **Multa Diária**: Possui caráter coercitivo e pode ser imposta a requerimento da parte ou de ofício
- **Cumprimento Provisório**: Decisão que fixa a multa é passível de cumprimento provisório, devendo ser depositada em juízo
- **Reversão de Multas**: Em regra, as multas pagas são revertidas aos fundos federal ou estaduais de reparação dos interesses difusos lesados
- **Estatutos da Pessoa Idosa e Criança e Adolescente**: Prevêem destinação das multas a fundos específicos

### Referências legais
- Art. 4º, §1º, Lei n.º 8.437/1992
- Art. 15, Lei do Mandado de Segurança
- Art. 16, Lei do Habeas Data
- Art. 537 §3º, CPC
- Art. 11, LACP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pegar a diferença entre multa e astreinte
- Entender o conceito de cumprimento provisório
- Conhecer as exceções para a reversão das multas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.95 (1)", "page_number": 95, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 4º, §1º, Lei n.º 8.437/1992", "Art. 15, Lei do Mandado de Segurança", "Art. 16, Lei do Habeas Data", "Art. 537 §3º, CPC", "Art. 11, LACP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-06-01T00:35:32.664427+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=95", "doc_key": "8c1a87974420620c1ae74a7d45e0be70"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '88a53e1979864cd2c10d4ed881d27eb79f187e973d9ced453a5db54a4e66d760'),
  ('cpiuris2025::6e89d3aba5967cee392cc36c1927759c', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Astreintes em Processos Civis Coletivos', '## Astreintes em Processos Civis Coletivos

A cominação de astreintes prevista no art. 11 da Lei nº 7.347/85 pode ser direcionada a entes estatais e autoridades, além de agentes responsáveis pelo cumprimento das determinações judiciais.

### Conceitos
- **Astreinte**: sancionamento aplicado em processos civis coletivos
- **Lei nº 7.347/85**: Lei que estabelece as regras para a reparação de danos em processos civis coletivos
- **Ente Estatal**: organização pública responsável por realizar atividades de interesse público
- **Autoridade**: pessoa responsável por tomar decisões ou implementar ações em um determinado campo

### Referências legais
- Art. 11 da Lei nº 7.347/85

### Jurisprudência
- STJ, REsp 1111562/RN
- Resolução Conjunta n.º 10 do CNJ e do CNMP

### Dicas de prova
- Entenda a noção de astreinte em processos civis coletivos
- Conheça a Lei nº 7.347/85 e seu aplicação às astreintes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.95 (2)", "page_number": 95, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 11 da Lei nº 7.347/85"], "jurisprudence": ["STJ, REsp 1111562/RN", "Resolução Conjunta n.º 10 do CNJ e do CNMP"], "confidence": 0.8, "extracted_at": "2026-06-01T00:36:04.711213+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=95", "doc_key": "6e89d3aba5967cee392cc36c1927759c"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'c583e835441d462c651389ebcc6202ffc660bee9a7e8ec59da70e21360685634'),
  ('cpiuris2025::0f19b3de6a9834913937f84976c78b7c', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Sentença e Meios de impugnação', '## Sentença e Meios de impugnação

A sentença em ações civis públicas pode condenar provimentos condenatórios, constitutivos ou meramente declaratórios. A Lei de Ação Popular prevê exceção ao princípio da congruência e à vedação à sentença extra petita.

### Conceitos
- **Ação Civil Pública**: ação em que o Estado é parte autora
- **Sentença condenatória**: sentença que condena o responsável por uma obrigação
- **Sentença constitutiva**: sentença que cria uma obrigação
- **Sentença declaratória**: sentença que declara a existência ou não de um fato
- **Lei de Ação Popular**: leis que permitem ações civis públicas contra atos ilegais
- **Princípio da congruência**: princípio que exige que as partes tenham os mesmos interesses
- **Vedação à sentença extra petita**: regra que proíbe a sentença de julgar questões não propostas

### Referências legais
- Art. 11 da Lei n.º 4.717/1965

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre condenação em dinheiro e indenização
- Importância do princípio da congruência na ação popular', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.96 (1)", "page_number": 96, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 11 da Lei n.º 4.717/1965"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-06-01T00:37:05.213894+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=96", "doc_key": "0f19b3de6a9834913937f84976c78b7c"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '59c6085034cb462e7471f88570c84ac5c0d06fdf4cd1ec501621da1c3b918bb4'),
  ('cpiuris2025::dde264fb050e7e14487c1f6fe76379d4', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Medidas de garantia em Processo Coletivo', '## Medidas de garantia em Processo Coletivo

A resolução n.º 10/2024-CNJ-CNMP estabelece que medidas de garantia são preferenciais às indenizatórias, sendo aplicáveis tanto nas decisões judiciais quanto nos instrumentos negociais de autocomposição coletiva.

### Conceitos
- **Medidas de garantia**: são medidas tomadas para proteger o bem jurídico violado ou ameaçado
- **Reversão de valores**: a reversão dos valores decorrentes de condenação em indenização pecuniária genérica para um fundo específico

### Referências legais
- Art. 3º da Resolução n.º 10/2024-CNJ-CNMP
- Art. 13 da Lei nº 7.347/1985

### Dicas de prova
- Entenda a diferença entre medidas de garantia e indenizatórias
- Conheça o conceito de reversão de valores', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.96 (2)", "page_number": 96, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 3º da Resolução n.º 10/2024-CNJ-CNMP", "Art. 13 da Lei nº 7.347/1985"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-06-01T00:37:31.037620+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=96", "doc_key": "dde264fb050e7e14487c1f6fe76379d4"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '5678a3ead14b442b0c9a7aae833458b5fda1afd2ef30e7f28799732725b1c7e4'),
  ('cpiuris2025::dfe294db2e7003c0e237d8abde1a82e2', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Revisão da Resolução sobre Fundos de Reparação', '## Revisão da Resolução sobre Fundos de Reparação

A resolução estabelece regras para a instituição e manutenção de cadastro de pessoas jurídicas sem fins lucrativos que promovem direitos transindividuais. Além disso, permite o repasse de recursos decorrentes de condenações judiciais em ações coletivas para a Defesa Civil em casos de calamidade pública.

### Conceitos
- **Fundos de Reparação**: Fundos criados para compensar vítimas de danos morais coletivos
- **Defesa Civil**: Instituição responsável pela promoção e proteção dos direitos humanos
- **Ações Coletivas**: Processos em que várias pessoas se unem para buscar uma mesma solução
- **Calamidade Pública**: Situação de emergência que afeta a população

### Referências legais
- Art. 11 da Resolução
- Art. 15 da Resolução

### Jurisprudência
- ADPF 944111
- Súmula n.º 232 do STF

### Dicas de prova
- Entenda a importância dos Fundos de Reparação e a Defesa Civil
- Conheça as regras para o repasse de recursos em casos de calamidade pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.97 (1)", "page_number": 97, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 11 da Resolução", "Art. 15 da Resolução"], "jurisprudence": ["ADPF 944111", "Súmula n.º 232 do STF"], "confidence": 0.8, "extracted_at": "2026-06-01T00:38:36.416165+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=97", "doc_key": "dfe294db2e7003c0e237d8abde1a82e2"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'b65ac0d0e2b7c4eba9097692a00bb6721efbb6fb1ca2a605030d6080ffcf6f06'),
  ('cpiuris2025::fc69df6f2c9566bb60af2d5650a124d5', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Destinação dos Fundos Federais de Defesa de Direitos Difusos', '## Destinação dos Fundos Federais de Defesa de Direitos Difusos

A questão aborda a necessidade de recomendações sobre a destinação dos valores destinados aos Fundos Federais de Defesa de Direitos Difusos, para uma melhor gestão sem prejuízo das alterações regulamentares.

### Conceitos
- **coletividade**: relação com a demanda e direitos violados
- **transparência**: destinação dos recursos de forma clara e transparente
- **desvio de finalidade**: aplicação das verbas em fins diferentes daqueles previstos
- **tutela e reparação**: efetiva proteção dos direitos transindividuais

### Referências legais
- Art. 100 do CDC

### Jurisprudência
- ADPF944MC/DF
- Sessão Virtual de 6.9.2024 a 13.9.2024

### Dicas de prova
- Entenda o conceito de coletividade e sua relação com a demanda e direitos violados.
- Aprenda a distinguir entre transparência e desvio de finalidade em relação à gestão dos Fundos Federais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.97 (2)", "page_number": 97, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 100 do CDC"], "jurisprudence": ["ADPF944MC/DF", "Sessão Virtual de 6.9.2024 a 13.9.2024"], "confidence": 0.8, "extracted_at": "2026-06-01T00:39:22.534290+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=97", "doc_key": "fc69df6f2c9566bb60af2d5650a124d5"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'e08a661e3a27fcc1601f43a95b08f8a1d2f926b75417c48438c7efac7ad2dbed'),
  ('cpiuris2025::2edaa43898792d31a4fb57d733d1162b', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Recurso em ACP e sentença', '## Recurso em ACP e sentença

O sistema recursal do processo coletivo é regido, subsidiariamente, pelas normas do CPC. Há distinção entre a apelação e as ações civis públicas, com regra de recebimento apenas no efeito devolutivo nas ações civis públicas.

### Conceitos
- **Recurso em ACP**: Recurso que pode ser recebido no efeito suspensivo ou devolutivo
- **Sentença**: Decisão final do juiz em uma ação
- **Remessa necessária**: Obrigação de remeter o processo para outro órgão jurisdicional
- **Reexame necessário**: Ação que visa reavaliar uma sentença anterior

### Referências legais
- Art. 14 da LACP
- Art. 1.012, caput do CPC
- Art. 19 da LAP

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Distinção entre a apelação e as ações civis públicas
- Regra de recebimento apenas no efeito devolutivo nas ações civis públicas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.98 (1)", "page_number": 98, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 14 da LACP", "Art. 1.012, caput do CPC", "Art. 19 da LAP"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-06-01T00:39:36.550618+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=98", "doc_key": "2edaa43898792d31a4fb57d733d1162b"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '5f69bd73a0d0a5266d3e5c269caab24923536666062dbe4f36f3b5afbcefcd3c'),
  ('cpiuris2025::31e6de897137c61c44061fed7b2ebd12', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Recurso do ECA', '## Recurso do ECA

O recurso do ECA possui peculiaridades recursais que se diferenciam das regras aplicáveis às demais ações civis públicas, especialmente em relação ao preparo.

### Conceitos
- **Preparo**: Sob a responsabilidade do autor ou réu
- **Adiantamento de preparo**: Prazo para o pagamento do preparo

### Referências legais
- Art. 496 do CPC
- Art. 198, I

### Jurisprudência
- REsp 802.060/RS
- REsp 1.374.232-ES

### Dicas de prova
- Diferenças entre recursos de ECA e outras ações civis públicas
- Importância do preparo e adiantamento de preparo no processo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.98 (2)", "page_number": 98, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 496 do CPC", "Art. 198, I"], "jurisprudence": ["REsp 802.060/RS", "REsp 1.374.232-ES"], "confidence": 0.8, "extracted_at": "2026-06-01T00:39:43.421295+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=98", "doc_key": "31e6de897137c61c44061fed7b2ebd12"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '775a56c51009c295667151d41f5910217f252ef16362ea30462b98e2c4e7a347'),
  ('cpiuris2025::65f23d51a7d0e64cd4de33cdabd07199', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Direitos Individuais em Processo Coletivo', '## Direitos Individuais em Processo Coletivo

Os direitos individuais não são prejudicados pela coisa julgada, mas apenas em caso de procedência do pedido. Em caso de improcedência, os interessados que não participaram como litisconsortes podem propor ação de indenização individual.

### Conceitos
- **Coisa Julgada**: princípio jurídico que protege os direitos adquiridos
- **Efeitos da Coisa Julgada**: aplicação dos princípios jurídicos ao processo
- **Direito Individual**: direito específico de cada pessoa
- **Litisconsorte**: parte que intervém no processo junto com o autor
- **Ação de Indenização**: ação processual para obter indenização por dano

### Referências legais
- Art. 103, §3º do Código de Processo Civil

### Dicas de prova
- Entenda a diferença entre direitos individuais e coletivos
- Conheça o conceito de coisa julgada e seus efeitos
- Identifique as partes que podem propor ação de indenização individual', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.99 (2)", "page_number": 99, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 103, §3º do Código de Processo Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-06-01T00:42:05.363960+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=99", "doc_key": "65f23d51a7d0e64cd4de33cdabd07199"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '8137801590daa8b106136849598d4cc32bd8d922b3a7384bf3b5c551f998b4aa'),
  ('cpiuris2025::06b199fe0348acf4ca6ba502bd1a6db2', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Coisa Julgada no Processo Coletivo', '## Coisa Julgada no Processo Coletivo

A coisa julgada no processo coletivo tem limites subjetivos (erga omnes ou ultra parts) e é formada de modo diverso, atingindo terceiros. O regramento geral está previsto no CDC.

### Conceitos
- **Coisa Julgada**: Conceito jurídico que se refere à decisão final do juiz em um processo
- **Erga Omnes**: Limites subjetivos da coisa julgada que atingem terceiros
- **Ultra Parts**: Limites subjetivos da coisa julgada que limitam o grupo, categoria ou classe
- **Coisa Julgada Secundum Eventum Probationis**: Conceito jurídico que se refere à possibilidade de qualquer legitimado intentar outra ação com idêntico fundamento valendo-se de nova prova

### Referências legais
- Art. 103 do CDC
- Art. 104 do CDC
- Art. 106 do CDC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre coisa julgada erga omnes e ultra parts.
- Conheça o conceito de coisa julgada secundum eventum probationis.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.99 (1)", "page_number": 99, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 103 do CDC", "Art. 104 do CDC", "Art. 106 do CDC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-06-01T00:42:24.865154+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=99", "doc_key": "06b199fe0348acf4ca6ba502bd1a6db2"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '7ebdb571e6ef01cf3d92e878af6d01a5118c1e8b8a7a9ebb773d210b1be65d09'),
  ('cpiuris2025::6bc7bea01d5b2b39711122e9280f3909', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Eficácia Erga Omnes em Ações Coletivas', '## Eficácia Erga Omnes em Ações Coletivas

A eficácia erga omnes em ações coletivas depende do regime jurídico da coisa julgada, que varia de acordo com o direito envolvido. Sentenças procedentes têm eficácia erga omnes, enquanto sentenças improcedentes não a têm, salvo no caso de falta de provas.

### Conceitos
- **Eficácia Erga Omnes**: eficácia da decisão em toda a sociedade
- **Cosa Julgada**: princípio que determina a eficácia das decisões judiciais
- **Ações Coletivas**: procedimentos jurídicos que envolvem mais de uma parte
- **Direitos Difusos**: direitos que se aplicam a todos os membros da sociedade

### Referências legais
- Art. 104 do Código de Defesa do Consumidor (Lei 8.078/90)

### Jurisprudência
- REsp 1593142/DF
- Súmula N da STJ

### Dicas de prova
- Entenda a diferença entre eficácia erga omnes e coisa julgada em ações coletivas.
- Conheça o regime jurídico da coisa julgada no plano coletivo e como ele depende do direito envolvido.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.100 (1)", "page_number": 100, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 104 do Código de Defesa do Consumidor (Lei 8.078/90)"], "jurisprudence": ["REsp 1593142/DF", "Súmula N da STJ"], "confidence": 0.8, "extracted_at": "2026-06-01T00:42:44.524321+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=100", "doc_key": "6bc7bea01d5b2b39711122e9280f3909"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'f7304af7e72a54e7f48c144468eced9c71f8589a5d687fce1f7072ce5590469e'),
  ('cpiuris2025::35b558caa3112b535ec0de6e3e9e6a75', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Eficácia ultra partes e erga omnes', '## Eficácia ultra partes e erga omnes

Resumo objetivo: A sentença procedente tem eficácia ultra partes, abrangendo toda a classe, enquanto a sentença improcedente tem eficácia erga omnes, abrangendo toda a sociedade. No caso de falta de provas, é possível propor nova ação coletiva.

### Conceitos
- **Eficácia ultra partes**: Abrange toda a classe
- **Eficácia erga omnes**: Abrange toda a sociedade

### Referências legais
- Art. 1022 do Código de Processo Civil
- ...

### Jurisprudência
- STJ, REsp 1302596/SP
- ...

### Dicas de prova
- Distinguir entre eficácia ultra partes e erga omnes
- Conhecer a exceção de falta de provas para nova ação coletiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.100 (2)", "page_number": 100, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 1022 do Código de Processo Civil", "..."], "jurisprudence": ["STJ, REsp 1302596/SP", "..."], "confidence": 0.8, "extracted_at": "2026-06-01T00:43:51.249020+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=100", "doc_key": "35b558caa3112b535ec0de6e3e9e6a75"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '4dcafa6eeaf5341562df8a337ebd4c7fa3973762e50f83fbb89315ef4d5b19c5'),
  ('cpiuris2025::c9c68aa27acfe6457e7447d7dccbf04b', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Competência territorial do órgão prolator', '## Competência territorial do órgão prolator

A competência territorial é determinada pelo órgão prolator, de acordo com a Medida Provisória nº 2.180-35/2001.

### Conceitos
- **Competência territorial**: Determinação do órgão prolator
- **Órgão prolator**: Entidade responsável por prolatar a competência

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Perguntas sobre competência territorial podem ser complexas, mas é importante entender que ela está determinada pelo órgão prolator.
- A Medida Provisória nº 2.180-35/2001 é um importante referencial para a competência territorial.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.101 (2)", "page_number": 101, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-06-01T00:44:14.886955+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=101", "doc_key": "c9c68aa27acfe6457e7447d7dccbf04b"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '52ccee43d17fc1828c17c246e9c1cc7e1ae09a37f0d1a9d46d70117ed25bcdf3'),
  ('cpiuris2025::af09e80055c32340f064c322f535d897', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Transporte utilibus da coisa julgada', '## Transporte utilibus da coisa julgada

A coisa julgada não prejudica os indivíduos, mas pode ser transportada para ação individual apenas para beneficiá-los. Existe exceção com o art. 94 do CDC e a possibilidade de interessados se tornarem litisconsortes.

### Conceitos
- **C coisa julgada**: Julgamento que beneficia os indivíduos, mas não prejudica
- **Transporte utilibus**: Máxima eficácia da tutela coletiva
- **Litisconsortes**: Interessados que intervêm no processo como parte do mesmo
- **Art. 94 CDC**: Possibilidade de interessados se tornarem litisconsortes

### Referências legais
- Art. 16 da LACP
- Art. 2º-A da Lei nº 9.494/97

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o transporte utilibus e a exceção do art. 94 CDC
- Conheça as limitações territoriais da coisa julgada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.101 (1)", "page_number": 101, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 16 da LACP", "Art. 2º-A da Lei nº 9.494/97"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-06-01T00:44:40.634979+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=101", "doc_key": "af09e80055c32340f064c322f535d897"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'fc4a53e0144abdd22886eda389bc2d06537aeaee3b32f7f37f50242e10945fff'),
  ('cpiuris2025::d0f25b50109465297bf07f46f37f005d', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Institucional de proteção aos direitos metaindividuais', '## Institucional de proteção aos direitos metaindividuais

A proteção aos direitos metaindividuais é afetada pela tutela coletiva e pelo acesso à Justiça, com a aplicação mútua das normas do CDC e da LACP.

### Conceitos
- **Tutela Coletiva**: Proteção aos direitos de uma categoria de pessoas
- **Acesso à Justiça**: Direito ao acesso a um processo judicial justo e eficiente
- **Leis do Consumidor**: Leis que protegem os consumidores e estabelecem regras para o consumo de bens e serviços
- **Competência Judicial**: Determinação do juízo competente para processar uma ação
- **Inconstitucionalidade**: Declaração da inconstitucionalidade de uma lei ou norma por violar o texto constitucional

### Referências legais
- Art. 90 (2) do CDC - Lei 8.078/1990
- Art. 21 da LACP - Lei 7.347/1985

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a aplicação mútua das normas do CDC e da LACP
- Conheça as regras de competência judicial para processar ações civis públicas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.102 (2)", "page_number": 102, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 90 (2) do CDC - Lei 8.078/1990", "Art. 21 da LACP - Lei 7.347/1985"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-06-01T00:46:40.817671+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=102", "doc_key": "d0f25b50109465297bf07f46f37f005d"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'f31cb16fea11563532a2fa508d9bfccd0a186b64e58befd534a4712449d0be3e'),
  ('cpiuris2025::b8c3633d251ebc738847ad55ef36b8d7', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Competência em ações civis públicas com abrangência nacional ou regional', '## Competência em ações civis públicas com abrangência nacional ou regional

A competência para processar e julgar ações civis públicas com abrangência nacional ou regional deve ser determinada de acordo com o art. 2º da LACP e do art. 93 do CDC, considerando a região atingida e a existência de demandas conexas.

### Conceitos
- **Competência**: A competência é a capacidade do juiz de julgar uma causa
- **LACP**: Lei nº 7.347/1985, que estabelece as normas gerais para o processo civil
- **CDC**: Código de Defesa do Consumidor
- **Conexão**: A conexão ocorre quando múltiplas demandas têm objeto comum

### Referências legais
- Art. 2º da LACP
- Art. 93 do CDC

### Jurisprudência
- RE 1101937/SP
- Tema 1075 da Repercussão Geral

### Dicas de prova
- Entenda a competência em ações civis públicas com abrangência nacional ou regional
- Conheça o regime da coisa julgada e sua aplicação às demandas conexas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.103 (1)", "page_number": 103, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 2º da LACP", "Art. 93 do CDC"], "jurisprudence": ["RE 1101937/SP", "Tema 1075 da Repercussão Geral"], "confidence": 0.8, "extracted_at": "2026-06-01T00:46:56.826285+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=103", "doc_key": "b8c3633d251ebc738847ad55ef36b8d7"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '5408fe0bb571a9a8cccb86868764dccbb283df31f5cf1a74bcddce7d7d7acad8'),
  ('cpiuris2025::1c0f1a28e0af3cb8d1553e7276977fe1', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Limitação dos Efeitos da Sentença em Ações Civis Públicas Coletivas', '## Limitação dos Efeitos da Sentença em Ações Civis Públicas Coletivas

A doutrina crítica os dispositivos que limitam a eficácia subjetiva da decisão coletiva, considerando inconstitucionais e ineficazes. A jurisprudência pacificou o tema, definindo que a eficácia das decisões não deve ficar limitada ao território da competência do órgão jurisdicional.

### Conceitos
- **Coisa julgada**: Conceito jurídico que se refere à imutabilidade e irreversibilidade de uma decisão judicial
- **Competência territorial**: Limitação do exercício da jurisdição a um determinado território
- **Eficácia da sentença**: Impacto ou efetividade da decisão proferida em uma ação

### Referências legais
- Art. 16 da Lei 7.347/1985
- Lei 9.494/1997
- MP 1.570/1997

### Jurisprudência
- {''title'': ''Súmula do STJ'', ''text'': ''A eficácia das decisões proferidas em ações civis públicas coletivas não deve ficar limitada ao território da competência do órgão jurisdicional que prolatou a decisão.''}
- {''title'': ''Julgamento do Resp 1.243.887/PR'', ''text'': ''O Ministro Luis Felipe Salomão entendeu que a eficácia da sentença não está limitada territorialmente, mas sim ao exercício da jurisdição.''}

### Dicas de prova
- Entenda a distinção entre competência territorial e eficácia da sentença.
- Conheça a evolução da jurisprudência sobre o tema.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.102 (1)", "page_number": 102, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 16 da Lei 7.347/1985", "Lei 9.494/1997", "MP 1.570/1997"], "jurisprudence": ["{''title'': ''Súmula do STJ'', ''text'': ''A eficácia das decisões proferidas em ações civis públicas coletivas não deve ficar limitada ao território da competência do órgão jurisdicional que prolatou a decisão.''}", "{''title'': ''Julgamento do Resp 1.243.887/PR'', ''text'': ''O Ministro Luis Felipe Salomão entendeu que a eficácia da sentença não está limitada territorialmente, mas sim ao exercício da jurisdição.''}"], "confidence": 0.8, "extracted_at": "2026-06-01T00:47:13.722956+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=102", "doc_key": "1c0f1a28e0af3cb8d1553e7276977fe1"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'c0a56b9a178b80a0380da744a859de57e8eb53210fde9ab44fbac5e8bda20921'),
  ('cpiuris2025::c11ee779ea62e57bfc52fb2b0caa964f', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Decisões Judiciais Incompatíveis em Processos Populares e Civil Pública', '## Decisões Judiciais Incompatíveis em Processos Populares e Civil Pública

A controvérsia gira em torno da configuração de coisa julgada, aplicação da teoria do fato consumado e existência de ilegalidade e lesividade no âmbito da ação popular.

### Conceitos
- **coisa julgada**: Conceito jurídico que se refere à decisão final de um processo, que não pode ser alterada ou modificada por outras decisões judiciais.
- **teoria do fato consumado**: Teoria jurídica que afirma que uma questão jurídica está resolvida quando se produz um fato que a torna necessariamente verdadeira, mesmo que não seja provada diretamente.
- **ilegalidade e lesividade**: Conceito jurídico que se refere à existência de uma ação ou decisão ilegal que pode gerar danos ao patrimônio público ou privado.

### Referências legais
- Art. 5º, § 2º da CF
- Súmula 646/STJ

### Jurisprudência
- RE 123456
