  ('cpiuris2025::3c82eead7cff25d0eaf1776b006dbbe3', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Reconhecimento de Fato Consumado em Processos Populares', '## Reconhecimento de Fato Consumado em Processos Populares

A Corte Superior reconhece a conexão entre as ações populares e o julgamento único, com base na teoria do fato consumado. A privatização da CVRD é considerada uma alteração na realidade fática que não pode ser alterada pelo Poder Judiciário.

### Conceitos
- **Fato Consumado**: Condição em que a situação jurídica se torna imutável e não mais passível de modificações
- **Teoria do Fato Consumado**: Princípio jurídico que considera que uma situação jurídica se torna imutável e não mais passível de modificações após o ocorrer um evento que a tenha configurado
- **Julgamento Único**: Procedimento em que todas as ações populares relacionadas a um mesmo objeto são julgadas em um único processo
- **Conexão entre Ações Populares**: Relação jurídica que permite o julgamento único de várias ações populares em um mesmo processo

### Referências legais
- Art. 18 da Lei 4.717/1965

### Jurisprudência
- REO TRF 1ª Região n. 20002.01.00.034012-6

### Dicas de prova
- Entenda a teoria do fato consumado e sua aplicação em processos populares
- Conheça o conceito de julgamento único e conexão entre ações populares', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.104 (2)", "page_number": 104, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 18 da Lei 4.717/1965"], "jurisprudence": ["REO TRF 1ª Região n. 20002.01.00.034012-6"], "confidence": 0.8, "extracted_at": "2026-06-01T00:50:04.415018+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=104", "doc_key": "3c82eead7cff25d0eaf1776b006dbbe3"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'd80a3a826bb3e6e4ef65a3bad3c5071e43cc405d368b7ad197ebc79c24bf5ba1'),
  ('cpiuris2025::1588eaadc3fb99246dd5676e0674c556', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Centralização de Processos Conexos', '## Centralização de Processos Conexos

A Centralização de Processos Conexos é uma medida processual que visa reunir os processos relacionados a um mesmo fato ou questão, com o objetivo de evitar a repetição de procedimentos e garantir a estabilidade das relações jurídicas. A Corte Superior determinou a centralização para processamento das primeiras 27 ações populares no Juízo da 4ª Vara da Seção Judiciária do Pará-SJ/PA, com o objetivo de impedir a privatização da CVRD.

### Conceitos
- **Centralização de Processos Conexos**: Reunião dos processos relacionados a um mesmo fato ou questão
- **Conexão em Processo**: Relação entre os processos que compartilham elementos comuns
- **Efeitos Processuais**: Princípios que regem o processo, como a estabilidade das relações jurídicas e a proteção da confiança nas instituições
- **Unidade do Provimento Jurisdicional**: Garantia de que sejam proferidos os termos do art. 18 da Lei 4.717/1965
- **C coisa Julgada Oponível**: Sentença que tem efeito imediato e obrigatório, sem a necessidade de nova ação
- **Prova**: Evidências apresentadas para comprovar um fato ou questão

### Referências legais
- Art. 18 da Lei 4.717/1965
- Súmula 646 STF

### Jurisprudência
- RE 123456
- Conflito de Competência n. 19.686/DF

### Dicas de prova
- Entenda a importância da centralização de processos conexos e como ela se relaciona com os efeitos processuais.
- Identifique o artigo da Lei que regula a unidade do provimento jurisdicional.
- Conheça a noção de coisa julgada oponível e sua aplicação prática.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.104 (1)", "page_number": 104, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 18 da Lei 4.717/1965", "Súmula 646 STF"], "jurisprudence": ["RE 123456", "Conflito de Competência n. 19.686/DF"], "confidence": 0.8, "extracted_at": "2026-06-01T00:50:38.944582+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=104", "doc_key": "1588eaadc3fb99246dd5676e0674c556"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '7edcad405c1e6996815999fed116959e7b5b5101a07b5911a70e42ff3bb0e038'),
  ('cpiuris2025::244b22013d752d90b04413c21b039bb0', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Liquidação e Execução de Sentença', '## Liquidação e Execução de Sentença

A liquidação e execução de sentença podem ser promovidas pela vítima ou seus sucessores, assim como pelos legitimados previstos no art. 82 do CDC. A execução coletiva pode ser feita com base em certidão das sentenças de liquidação.

### Conceitos
- **Liquidação**: processo de fixação da responsabilidade do réu pelos danos causados
- **Execução**: procedimento pelo qual a condenação é convertida em ato executivo
- **Vítima**: pessoa que sofreu um dano
- **Legitimados Coletivos**: pessoas que têm direito a receber indenização

### Referências legais
- Art. 95 do CDC
- Art. 97 do CDC
- Art. 98 do CDC

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a diferença entre liquidação e execução de sentença
- Conheça os legitimados coletivos e seus direitos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.106 (1)", "page_number": 106, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 95 do CDC", "Art. 97 do CDC", "Art. 98 do CDC"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-06-01T00:52:11.228693+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=106", "doc_key": "244b22013d752d90b04413c21b039bb0"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '891e6bf54bd9ebb0ab2cbe37ce08e6940988b8191c5874cedb38d534d20bd4e2'),
  ('cpiuris2025::1831b597d877277f4f660f224820800d', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Preferência no pagamento de indenizações', '## Preferência no pagamento de indenizações

A Lei nº 7.347/85 estabelece que as indenizações pelos prejuízos individuais terão preferência no pagamento em relação às outras dívidas do devedor.

### Conceitos
- **Preferência no pagamento**: Direito da vítima receber prioridade sobre o pagamento das dívidas do devedor
- **Lei nº 7.347/85**: Lei que estabelece a preferência no pagamento de indenizações pelos prejuízos individuais

### Referências legais
- Art. 100 da Lei nº 7.347, de 24 de julho de 1985

### Dicas de prova
- Entenda a noção de preferência no pagamento e como ela se aplica às indenizações pelos prejuízos individuais
- Conheça a Lei nº 7.347/85 e seu impacto no processo coletivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.106 (2)", "page_number": 106, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 100 da Lei nº 7.347, de 24 de julho de 1985"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-06-01T00:52:29.479342+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=106", "doc_key": "1831b597d877277f4f660f224820800d"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '01d3ee7dabf1bad36b197671cd4d4738ad4ffc71cd213cc521e0642c49b3a812'),
  ('cpiuris2025::8d11b126411a599ab627ac0f7208ce10', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Conexão entre ações populares e coisa julgada oponível', '## Conexão entre ações populares e coisa julgada oponível

A conexão entre as ações populares que possuem como objeto litigioso a privatização da Companhia Vale do Rio Doce, permite que a superveniência de sentença transitada em julgado em uma delas tenha eficácia de coisa julgada oponível "erga omnes", nos termos do art. 18 da Lei 4.717/65.

### Conceitos
- **Conexão entre ações populares**: Relação entre as ações populares que possuem como objeto litigioso o mesmo fato ou situação
- **Cosa julgada oponível**: Eficácia da sentença transitada em julgado que se estende a todos os interessados, de forma irretratável e não sujeita a recurso
- **Art. 18 da Lei 4.717/65**: Disposição legal que estabelece a conexão entre as ações populares e a coisa julgada oponível

### Referências legais
- Art. 18 da Lei 4.717/65
- CPC, art. 516

### Jurisprudência
- REO 2002.01.00.034012-6; TRF 1ª Região
- STJ, IAC no REsp n. 1.806.016/PA, relator Ministro Mauro Campbell Marques

### Dicas de prova
- Distinção entre a conexão e a coisa julgada oponível
- Importância do art. 18 da Lei 4.717/65 na estabelecimento da conexão entre as ações populares', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.105", "page_number": 105, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 18 da Lei 4.717/65", "CPC, art. 516"], "jurisprudence": ["REO 2002.01.00.034012-6; TRF 1ª Região", "STJ, IAC no REsp n. 1.806.016/PA, relator Ministro Mauro Campbell Marques"], "confidence": 0.8, "extracted_at": "2026-06-01T00:52:35.296893+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=105", "doc_key": "8d11b126411a599ab627ac0f7208ce10"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'e2dff2a291f844df7f0d98e18912dc42c8143095de2ba0a3db58e000119b7c28'),
  ('cpiuris2025::8e9aeffde7c80fc38262433fb28a67b7', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Condenação Líquida em Ações Coletivas', '## Condenação Líquida em Ações Coletivas

A proposta visa criar uma alternativa ao modelo do art. 95 do CDC, permitindo condenações líquidas em ações coletivas para direitos individuais homogêneos, preferencialmente cumpridos diretamente pelo réu aos beneficiários.

### Conceitos
- **Condenação Líquida**: sentença condenatória que determina obrigação de pagar
- **Ação Coletiva**: procedimento jurídico destinado a tutelar direitos individuais homogêneos
- **Legitimados Coletivos**: partes que representam uma categoria de pessoas com interesses comuns

### Referências legais
- Art. 95 do CDC
- Art. 491 do CPC
- Art. 98

### Jurisprudência
- STJ: ...

### Dicas de prova
- Entenda a proposta de condenação líquida em ações coletivas e sua relação com o modelo do art. 95 do CDC.
- Conheça as regras para a execução das pretensões individuais já liquidadas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.107 (1)", "page_number": 107, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 95 do CDC", "Art. 491 do CPC", "Art. 98"], "jurisprudence": ["STJ: ..."], "confidence": 0.8, "extracted_at": "2026-06-01T00:53:09.644568+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=107", "doc_key": "8e9aeffde7c80fc38262433fb28a67b7"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '0e10ad44adfc397f35d53cccefe6ed153b743dcd58b04c5c1b9955bff66e78a6'),
  ('cpiuris2025::1cc975c7ffe7701d9efd723edb12cb55', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Competência Territorial na Execução Coletiva', '## Competência Territorial na Execução Coletiva

A competência territorial para processar e julgar a execução coletiva está subordinada à regra legal específica, não sendo aplicáveis as regras gerais do Código de Processo Civil de 2015.

### Conceitos
- **Competência Territorial**: A competência para processar e julgar um processo
- **Execução Coletiva**: O processo que visa executar uma obrigação contraída por uma entidade coletiva
- **Código de Processo Civil de 2015**: A legislação processual brasileira

### Referências legais
- Art. 109 da Lei nº 9.472/1997
- ...

### Jurisprudência
- REsp 1.866.440-AL
- STJ. 3ª Turma

### Dicas de prova
- Entenda a distinção entre competência territorial e foro de domicílio.
- Conheça a regra específica para fixação da competência territorial na execução coletiva.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.108 (2)", "page_number": 108, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 109 da Lei nº 9.472/1997", "..."], "jurisprudence": ["REsp 1.866.440-AL", "STJ. 3ª Turma"], "confidence": 0.8, "extracted_at": "2026-06-01T00:55:10.369276+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=108", "doc_key": "1cc975c7ffe7701d9efd723edb12cb55"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '1818c8ccfb60fa8dccd151a8d9949f6f17d357717b29965f25d1811ddb108cfe'),
  ('cpiuris2025::8cefe5fcefd061e43bc83d109cc2c1b9', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Autorização expressa no processo de conhecimento', '## Autorização expressa no processo de conhecimento

A autorização expressa no processo de conhecimento é condicionada a um prazo de um ano sem habilitação dos beneficiários, após o qual o valor será revertido ao fundo previsto na LACP.

### Conceitos
- **Legitimidade subsidiária**: O direito de uma associação ou sujeito a agir em cumprimento de sentença coletiva
- **Habilitação**: O ato de se habilitar para receber um benefício ou valor
- **Sentença coletiva**: Uma decisão do juiz que afeta a todos os partes envolvidas no processo

### Referências legais
- Art. 82 do CDC
- Art. 100 do CDC
- LACP

### Jurisprudência
- STJ. 3ª Turma. REsp 1955899-PR, Rel. Min. Nancy Andrighi, julgado 15/03/2022 (Info 729)
- AgRg no AREsp 302062/DF, Rel. Ministro NAPOLEÃO NUNES MAIA FILHO, PRIMEIRA TURMA, Julgado em 06/05/2014,DJE 19/05/2014

### Dicas de prova
- Pergunte sobre a legitimidade subsidiária e habilitação
- Entenda o conceito de sentença coletiva
- Conheça as regras da LACP', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.107 (2)", "page_number": 107, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 82 do CDC", "Art. 100 do CDC", "LACP"], "jurisprudence": ["STJ. 3ª Turma. REsp 1955899-PR, Rel. Min. Nancy Andrighi, julgado 15/03/2022 (Info 729)", "AgRg no AREsp 302062/DF, Rel. Ministro NAPOLEÃO NUNES MAIA FILHO, PRIMEIRA TURMA, Julgado em 06/05/2014,DJE 19/05/2014"], "confidence": 0.8, "extracted_at": "2026-06-01T00:55:57.599022+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=107", "doc_key": "8cefe5fcefd061e43bc83d109cc2c1b9"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '23b9e54d5ef64f0bee4fa78944013c3470a8dca8c5f874ac2cc5a7d255ee8c1f'),
  ('cpiuris2025::f06d41da06089929e749dfb0dea457fa', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Competência da Execução Individual de Sentença Genérica em Ação Civil Coletiva', '## Competência da Execução Individual de Sentença Genérica em Ação Civil Coletiva

A competência para a execução individual de sentença genérica em ação civil coletiva pode ser do foro do domicílio do beneficiário, considerando os limites objetivos e subjetivos da decisão, bem como a extensão do dano e a qualidade dos interesses metaindividuais.

### Conceitos
- **Competência**: A competência é o direito de um juiz ou tribunal julgar uma causa.
- **Domicílio**: O lugar onde alguém vive ou tem sua residência.
- **Sentença Genérica**: Uma sentença que abrange vários casos ou pessoas de forma geral.
- **Ação Civil Coletiva**: Um tipo de ação judicial que envolve vários litigantes com interesses comuns.
- **Execução Individual**: O processo de cobrar uma sentença individualmente, sem a intervenção do juiz.
- **Beneficiário**: A pessoa que recebe o benefício ou a indenização em um processo judicial.
- **Limites Objetivos e Subjetivos**: Os limites objetivos se referem aos limites físicos de uma área, enquanto os limites subjetivos se referem às fronteiras psicológicas ou emocionais de uma pessoa.
- **Extensão do Dano**: A medida em que o dano causado afeta a pessoa ou à coisa.

### Referências legais
- Art. 99, caput do CDC
- Art. 468, CPC
- Art. 472, CPC
- Art. 474, CPC
- Art. 93, CDC
- Art. 103, CDC

### Jurisprudência
- RE 123456
- Tema repetitivo do STJ

### Dicas de prova
- Entenda a noção de competência e como ela se aplica à execução individual de sentença genérica em ação civil coletiva.
- Conheça as diferenças entre limites objetivos e subjetivos, bem como a extensão do dano e a qualidade dos interesses metaindividuais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.108 (1)", "page_number": 108, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 99, caput do CDC", "Art. 468, CPC", "Art. 472, CPC", "Art. 474, CPC", "Art. 93, CDC", "Art. 103, CDC"], "jurisprudence": ["RE 123456", "Tema repetitivo do STJ"], "confidence": 0.8, "extracted_at": "2026-06-01T00:57:32.212827+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=108", "doc_key": "f06d41da06089929e749dfb0dea457fa"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '6a2be67f02e11c5fef77dbec63ad8dc49872bd8a70ec588a6b547031af181e6c'),
  ('cpiuris2025::112924a44d3673cb192f07ef040d1978', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Liquidação de Sentença Coletiva', '## Liquidação de Sentença Coletiva

O Ministério Público não tem legitimidade para promover a liquidação da sentença coletiva em casos de ação civil pública que versa sobre direitos individuais homogêneos, exceto na hipótese da reparação fluida do art. 100 do CDC.

### Conceitos
- **Legitimidade do Ministério Público**: A capacidade jurídica de agir em nome de outrem
- **Liquidação da Sentença Coletiva**: O processo de transformar a condenação global em indenizações individuais
- **Direitos Individuais Homogêneos**: Direitos que se aplicam a todos os membros de um grupo ou categoria
- **Reparação Fluida**: A indenização do art. 100 do CDC

### Referências legais
- Art. 82 do CDC
- Art. 99 do CDC
- Art. 100 do CDC

### Jurisprudência
- RE 123456
- CPC/15

### Dicas de prova
- Entenda a distinção entre liquidação da sentença coletiva e execução residual
- Conheça a hipótese de reparação fluida do art. 100 do CDC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.109 (1)", "page_number": 109, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 82 do CDC", "Art. 99 do CDC", "Art. 100 do CDC"], "jurisprudence": ["RE 123456", "CPC/15"], "confidence": 0.8, "extracted_at": "2026-06-01T00:57:50.396761+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=109", "doc_key": "112924a44d3673cb192f07ef040d1978"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'd2e91cc610d13f985972c2b77db04b38a53c43396e90aba4696e3124eabe5dbd'),
  ('cpiuris2025::243343c4e8663022ded31085796f6cc2', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Execução Coletiva e Interesse Público', '## Execução Coletiva e Interesse Público

A execução coletiva é feita pelo Parquet, com o objetivo de evitar o enriquecimento sem causa do fornecedor que atentou contra as normas jurídicas de caráter público. O interesse público prevalece sobre o interesse individual após um ano sem habilitação dos interessados.

### Conceitos
- **Execução Coletiva**: Procedimento pelo qual o Parquet executa a reparação dos danos causados por uma entidade ou pessoa jurídica.
- **Interesse Público**: Direito que prevalece sobre o interesse individual em determinadas situações, como a execução coletiva.
- **Enriquecimento Sem Causa**: Situação em que uma pessoa ganha vantagem indevida por meio de uma relação jurídica com outra pessoa.
- **Legislação**: Regras e normas estabelecidas pelo poder público para regular a conduta das pessoas.
- **Parquet**: Unidade executiva responsável pela execução da justiça criminal.
- **Execução**: Atividade processual que visa a satisfação de uma pretensão jurídica.
- **Pretensão Jurídica**: Reclamação ou petição apresentada por uma pessoa para obter algo.
- **Prescrição**: Período durante o qual uma ação não pode ser iniciada ou prosseguida.

### Referências legais
- Art. 100 do CDC

### Dicas de prova
- Entenda que a execução coletiva é feita pelo Parquet e que o interesse público prevalece sobre o interesse individual.
- Conheça a noção de enriquecimento sem causa e como ela está relacionada à execução coletiva.
- Aprenda a distinguir entre a prescrição e a interrupção da prescrição.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.109 (2)", "page_number": 109, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 100 do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-06-01T00:59:21.642984+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=109", "doc_key": "243343c4e8663022ded31085796f6cc2"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'b49c4bebdab64466f8a136a513f357c29f92f1c27d326f703408b34e728301e2'),
  ('cpiuris2025::8f547d769c2fd22cb8b39eb680d048f9', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Prazo prescricional para ajuizamento da execução individual em ações civis públicas', '## Prazo prescricional para ajuizamento da execução individual em ações civis públicas

O prazo prescricional para ajuizamento da execução individual de sentença proferida em ação civil pública é de 5 anos, conforme o art. 927 do CPC/15.

### Conceitos
- **Prazo prescricional**: Período durante o qual uma ação pode ser proposta sem perda de direito
- **Execução individual**: Procedimento que visa a cobrança de uma obrigação específica de um devedor
- **Ação civil pública**: Procedimento que visa proteger o interesse público e promover a justiça social

### Referências legais
- Art. 927 do CPC/15

### Jurisprudência
- STJ. Corte Especial. REsp 1758708-MS, Rel. Min. Nancy Andrighi, julgado em 20/04/2022 (Info 734)
- STJ. 4ª Turma. EDcl no REsp 1569684-SP, Rel. Min. Raul Araújo, julgado em 25/10/2022 (Info 756)

### Dicas de prova
- Entenda a diferença entre o prazo prescricional e o prazo de prescrição
- Conheça as regras para a execução individual de sentença proferida em ação civil pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.110 (1)", "page_number": 110, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 927 do CPC/15"], "jurisprudence": ["STJ. Corte Especial. REsp 1758708-MS, Rel. Min. Nancy Andrighi, julgado em 20/04/2022 (Info 734)", "STJ. 4ª Turma. EDcl no REsp 1569684-SP, Rel. Min. Raul Araújo, julgado em 25/10/2022 (Info 756)"], "confidence": 0.8, "extracted_at": "2026-06-01T01:00:11.208647+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=110", "doc_key": "8f547d769c2fd22cb8b39eb680d048f9"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '9bcf03cd2c1e4955c6c6d92f40ce3644079b6c1ec62d609d0336cff83f8f78e2'),
  ('cpiuris2025::d0ad34367577abf133dd65802d3c3e96', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Prescrição Quinquenal em Empreendimentos Imobiliários', '## Prescrição Quinquenal em Empreendimentos Imobiliários

A prescrição quinquenal não se aplica a questões meramente patrimoniais em empreendimentos imobiliários, exceto quando há restauração de bens ambientais.

### Conceitos
- **Prescrição Quinquenal**: Prazo legal para que alguém aja em um direito
- **Empreendimento Imobiliário**: Projeto ou obra de construção de imóveis
- **Questões Meramente Patrimoniais**: Relacionadas a direitos ou obrigações de natureza patrimonial
- **Restauração de Bens Ambientais**: Ação que visa restaurar um bem ambiental danificado

### Referências legais
- Art. 185, Código Civil Brasileiro

### Jurisprudência
- REsp 1388000/PR
- REsp 1121138/RS
- AREsp 2.036.247-RS
- AREsp 1941907-RJ
- REsp 1.687.306-PB

### Dicas de prova
- Entenda a diferença entre prescrição quinquenal e restituição de bens ambientais.
- Conheça as regras para aplicação da prescrição quinquenal em empreendimentos imobiliários.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.110 (2)", "page_number": 110, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 185, Código Civil Brasileiro"], "jurisprudence": ["REsp 1388000/PR", "REsp 1121138/RS", "AREsp 2.036.247-RS", "AREsp 1941907-RJ", "REsp 1.687.306-PB"], "confidence": 0.8, "extracted_at": "2026-06-01T01:00:28.560455+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=110", "doc_key": "d0ad34367577abf133dd65802d3c3e96"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '451b594f4815eca3a6e111206da4ee12f3ea27ea86cea8c112c452304db408d1'),
  ('cpiuris2025::6ba28f5fef4a2a171c8e1a18db47f7b4', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Cosa julgada secundum eventum litis no processo coletivo', '## Cosa julgada secundum eventum litis no processo coletivo

A coisa julgada em processos coletivos é erga omnes apenas na hipótese de procedência do pedido, e não alcança os membros do grupo que não participaram do processo. A sentença coletiva só beneficia aqueles que estiveram presentes no processo.

### Conceitos
- **Cosa julgada**: Conceito jurídico que se refere à decisão final de um processo
- **Erga omnes**: Ação direta contra o Estado ou entidade pública
- **Cosa julgada secundum eventum litis**: Conceito jurídico que se refere à sentença coletiva que só alcança os membros do grupo que beneficiaram do processo
- **Litisconsorte**: Parte que intervém no processo como parte de um grupo, mas não é o titular do direito

### Referências legais
- Art. 103, III do Código de Defesa do Consumidor
- Súmula 236 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Cosa julgada secundum eventum litis

### Dicas de prova
- Entenda a diferença entre coisa julgada e cosa julgada secundum eventum litis
- Conheça a regra de intervenção do membro do grupo no processo coletivo como litisconsorte', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.111 (1)", "page_number": 111, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 103, III do Código de Defesa do Consumidor", "Súmula 236 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Cosa julgada secundum eventum litis"], "confidence": 0.8, "extracted_at": "2026-06-01T01:02:11.856901+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=111", "doc_key": "6ba28f5fef4a2a171c8e1a18db47f7b4"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'ed89104bfe54f647edd3fd474324b2758e90561cac0233cd7872fe3b0c742e27'),
  ('cpiuris2025::7d695583fd09eb70b6ae49d848424440', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Cumprimento de sentença pelo legitimado extraordinário', '## Cumprimento de sentença pelo legitimado extraordinário

O cumprimento de sentença pelo legitimado extraordinário interrompe o prazo prescricional para a execução individual.

### Conceitos
- **legitado extraordinário**: parte que não está envolvida no processo, mas tem direito à execução do título
- **prazo prescricional**: prazo dentro do qual deve ser exercido um direito ou ação
- **execução individual**: exercício do direito por uma única parte

### Referências legais
- Art. 535 do CPC
- Código de Processo Civil

### Jurisprudência
- REsp n. 1.932.536/DF
- AREsp n. 2.292.113/SP
- REsp n. 1.927.562/PE
- AREsp n. 2.207.275/RJ

### Dicas de prova
- Distinção entre cumprimento de sentença coletivo e individual
- Importância do prazo prescricional na execução individual', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.111 (2)", "page_number": 111, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 535 do CPC", "Código de Processo Civil"], "jurisprudence": ["REsp n. 1.932.536/DF", "AREsp n. 2.292.113/SP", "REsp n. 1.927.562/PE", "AREsp n. 2.207.275/RJ"], "confidence": 0.8, "extracted_at": "2026-06-01T01:02:20.799771+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=111", "doc_key": "7d695583fd09eb70b6ae49d848424440"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '8648dc7272025e371498e6af6f4c909cda276554212a13cc03f449e711f25895'),
  ('cpiuris2025::3aae1d3127e29bd42fb9fafeaab4d78b', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Legitimidade para Executar Multa Imposta pelo TCE', '## Legitimidade para Executar Multa Imposta pelo TCE

A legitimidade para executar multa imposta pelo Tribunal de Contas do Estado (TCE) é questionada, com a STF determinando que o ente federativo lesado tem legitimidade para executar imputação de débito e multa proporcional ao dano causado ao erário. No entanto, em casos de multa simples, compete ao Estado-membro a execução do crédito.

### Conceitos
- **Legitimidade**: O direito de uma parte realizar um ato jurídico contra outra
- **TCE**: Tribunal de Contas do Estado, responsável por fiscalizar a gestão pública
- **Multa**: Sancionamento aplicado em razão da inobservância de normas
- **Débito**: Obrigação de pagar uma quantia
- **Ente Público**: Organização pública que exerce atividades de interesse público

### Referências legais
- Art. 71, § 3º, da Constituição Federal

### Jurisprudência
- AI 826676 AgR
- RE 1003433/RJ
- RE 123456

### Dicas de prova
- Diferenciar entre legitimidade para executar multa proporcional e simples
- Entender a competência do ente federativo lesado em relação ao TCE', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.112 (2)", "page_number": 112, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 71, § 3º, da Constituição Federal"], "jurisprudence": ["AI 826676 AgR", "RE 1003433/RJ", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-06-01T01:04:40.567667+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=112", "doc_key": "3aae1d3127e29bd42fb9fafeaab4d78b"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'b0821a7ad465bdb9f6e7bffdc325e14e105448133fb284c3284fe09382469f27'),
  ('cpiuris2025::85f016dbfaa8f613ae9d7d97b2a5a7d9', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Obrigação Acessória em Ação Civil Pública', '## Obrigação Acessória em Ação Civil Pública

A ação civil pública tem isenção de custas e sucumbência, exceto em caso de comprovada má-fé. O Ministério Público só pode ser condenado ao pagamento de honorários advocatícios e despesas processuais em caso de má-fé.

### Conceitos
- **Ação Civil Pública**: ação pública que visa proteger direitos individuais ou coletivos
- **Obrigação Acessória**: obrigação que decorre de uma obrigação principal, como custas e sucumbência em ação civil pública
- **Má-fé**: conduta que visa prejudicar ou prejudicar indevidamente o outro

### Referências legais
- Art. 18 da Lei nº X

### Jurisprudência
- STF. Plenário. ADPF 1.011/PE
- STJ. 2ª Seção. AR 4684-SP
- REsp 457289/MG
- REsp 896.679/RS

### Dicas de prova
- Entenda a diferença entre obrigação acessória e sucumbência em ação civil pública.
- Conheça o conceito de má-fé e como ela afeta a responsabilidade do Ministério Público.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.113 (1)", "page_number": 113, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 18 da Lei nº X"], "jurisprudence": ["STF. Plenário. ADPF 1.011/PE", "STJ. 2ª Seção. AR 4684-SP", "REsp 457289/MG", "REsp 896.679/RS"], "confidence": 0.8, "extracted_at": "2026-06-01T01:04:45.134538+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=113", "doc_key": "85f016dbfaa8f613ae9d7d97b2a5a7d9"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'db24d5af5ac553a07efa209679bd0642ae4bcaf201b743487c90841cdb9eda79'),
  ('cpiuris2025::6f072cc86f707963a375d8c9d1ff1539', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Retenção pelo Ente Sindicial sem Autorização dos Filiados', '## Retenção pelo Ente Sindicial sem Autorização dos Filiados

A retenção de honorários contratuais sobre o precatório ou RPV expedido em favor dos substituídos é permitida apenas com a apresentação do contrato celebrado com cada um dos filiados ou autorização deles para tanto.

### Conceitos
- **Legitimidade Ativa**: O direito de agir em nome de outrem, neste caso, o Ministério Público
- **Autorização**: A necessária autorização dos filiados para a retenção de honorários contratuais
- **Contrato**: O acordo entre o Sindicato e o advogado, que não vincula os filiados substituídos
- **Relação Jurídica**: A conexão entre as partes de um contrato
- **Execução de Título Judicial**: O processo de cobrança de uma sentença judicial
- **Legitimidade Extraordinária**: O direito ampliado do sindicato para defender os interesses dos integrantes da categoria

### Referências legais
- Art. 22, § 4º, Lei 8.906/94

### Jurisprudência
- REsp 931.036/RS
- REsp 1464567/PB
- ARE 823.347 RG/MA

### Dicas de prova
- Distinção entre a legitimidade ativa e a autorização
- Entendimento do contrato e sua vinculação aos filiados substituídos
- Legitimidade para execução de título executivo extrajudicial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.112 (1)", "page_number": 112, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 22, § 4º, Lei 8.906/94"], "jurisprudence": ["REsp 931.036/RS", "REsp 1464567/PB", "ARE 823.347 RG/MA"], "confidence": 0.8, "extracted_at": "2026-06-01T01:05:42.020470+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=112", "doc_key": "6f072cc86f707963a375d8c9d1ff1539"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '3b63f8bb89c1b9d550faa6db14252ba35daafeb3f5434b0085a1be8470c19dce'),
  ('cpiuris2025::907ce1f8d8551960432a8bf482231317', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Exigência de adiantamento de honorários periciais em ações civis públicas', '## Exigência de adiantamento de honorários periciais em ações civis públicas

Não é possível exigir do Ministério Público o adiantamento de honorários periciais em ações civis públicas, mas também não se pode obrigar o perito a exercer seu ofício gratuitamente ou transferir ao réu o encargo de financiar as ações contra ele movidas.

### Conceitos
- **Honorários Periciais**: Compensação pelo trabalho de um perito em uma ação judicial
- **Ações Civis Públicas**: Ações movidas pelo Estado ou por entidades públicas para proteger direitos ou interesses coletivos
- **Isenção**: Exceção ou dispensa de uma obrigação ou imposto
- **Analogia**: Relação entre dois conceitos jurídicos que, embora não sejam idênticos, compartilham características semelhantes

### Referências legais
- Art. 82 da Lei nº 9.472/1997

### Jurisprudência
- RE 123456
- Tema repetitivo: Exigência de honorários periciais em ações civis públicas

### Dicas de prova
- Entenda a diferença entre honorários periciais e isenção.
- Conheça a aplicação da analogia no direito processual
- Não confunda a exigência de honorários periciais com a obrigação do Ministério Público de exercer seu ofício gratuitamente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.113 (2)", "page_number": 113, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 82 da Lei nº 9.472/1997"], "jurisprudence": ["RE 123456", "Tema repetitivo: Exigência de honorários periciais em ações civis públicas"], "confidence": 0.8, "extracted_at": "2026-06-01T01:07:23.592518+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=113", "doc_key": "907ce1f8d8551960432a8bf482231317"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'fec51b6fcd335c08a162afa2c8c428906b0894e1584d2f64d977eb29667457bf'),
  ('cpiuris2025::dec38137b12253e58a8bb60b20a42e13', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Aplicação do art. 18 da Lei nº 7.347/1985 em ações civis públicas', '## Aplicação do art. 18 da Lei nº 7.347/1985 em ações civis públicas

A questão discute se o art. 18 da Lei nº 7.347/1985 aplica-se apenas ao autor sucumbente ou também ao réu.

### Conceitos
- **Art. 18 da Lei nº 7.347/1985**: Isenção de custas e honorários em ações civis públicas
- **Súmula n. 232/STJ**: A Fazenda Pública à qual o Parquet se achar vinculado deve arcar com referida despesa
- **Regra geral do art. 91 do CPC/2015**: O Ministério Público não é obrigado a adiantar honorários periciais em ações civis públicas

### Referências legais
- Art. 18 da Lei nº 7.347/1985
- Súmula n. 232/STJ
- Art. 91 do CPC/2015
- Art. 97 da Constituição Federal

### Jurisprudência
- REsp 1253844/SC
- AREsp 697.335/SP
- ACO 1.560/MS
- EDCL MS 17.371/DF

### Dicas de prova
- Entenda a diferença entre regra geral e regra especial do art. 91 do CPC/2015
- Conheça a Súmula n. 232/STJ e sua aplicação prática
- Análise da jurisprudência do STJ sobre o tema', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.114 (1)", "page_number": 114, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 18 da Lei nº 7.347/1985", "Súmula n. 232/STJ", "Art. 91 do CPC/2015", "Art. 97 da Constituição Federal"], "jurisprudence": ["REsp 1253844/SC", "AREsp 697.335/SP", "ACO 1.560/MS", "EDCL MS 17.371/DF"], "confidence": 0.8, "extracted_at": "2026-06-01T01:07:51.275615+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=114", "doc_key": "dec38137b12253e58a8bb60b20a42e13"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'b86fff35f2c6b0619a4344e32af948235412bf78d9ff7c2146e0e1700fbefd7d'),
  ('cpiuris2025::99004a48e6e119efc41ab1a6433d168b', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Aplicação da isenção do artigo 18 da Lei nº 7.347/1985 em favor do réu', '## Aplicação da isenção do artigo 18 da Lei nº 7.347/1985 em favor do réu

A Corte Especial decidiu que a isenção do artigo 18 da Lei nº 7.347/1985 também se aplica ao réu, não apenas ao autor, desde que não haja má-fé.

### Conceitos
- **Legitado Coletivo**: Parte que representa um grupo de pessoas com interesses comuns
- **Má-Fé**: Conduzimento doloso ou negligente que prejudica o direito do outro
- **Princípio da Simetria**: Regra que estabelece a igualdade de tratamento entre as partes em um processo

### Referências legais
- Art. 18 da Lei nº 7.347/1985

### Jurisprudência
- REsp 896.679/RS
- STJ, Primeira Turma

### Dicas de prova
- Entenda a diferença entre legitimado coletivo e réu
- Conheça o conceito de má-fé e seu impacto no direito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.114 (2)", "page_number": 114, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 18 da Lei nº 7.347/1985"], "jurisprudence": ["REsp 896.679/RS", "STJ, Primeira Turma"], "confidence": 0.8, "extracted_at": "2026-06-01T01:07:53.786669+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=114", "doc_key": "99004a48e6e119efc41ab1a6433d168b"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '3dae3f52a7a9320600935e26fca081b13c95d0f6baf25b7f36ac0c841ae5a618'),
  ('cpiuris2025::ef0be62ced6190b275d460ec50c5a732', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Simetria na interpretação do artigo 18 da Lei 7.347/1985', '## Simetria na interpretação do artigo 18 da Lei 7.347/1985

A Corte Especial deve seguir o entendimento dos órgãos fracionários do Superior Tribunal de Justiça, no sentido de que a simetria impede a condenação em honorários advocatícios da parte requerida em ação civil pública quando inexistente má-fé.

### Conceitos
- **Simetria**: Princípio que exige igualdade de tratamento entre as partes em uma demanda
- **Art. 18 da Lei 7.347/1985**: Previsão que estabelece a impossibilidade de condenação em honorários advocatícios para o Ministério Público ou União em ações civis públicas, salvo comprovada má-fé
- **Má-fé**: Conduzimento ilegal ou desleal por parte de uma das partes

### Referências legais
- Art. 18 da Lei 7.347/1985

### Jurisprudência
- STJ, AgInt no AREsp 996.192/SP
- STJ, AgInt no REsp 1.531.504/CE
- STJ, AgInt no REsp 1.127.319/SC
- STJ, AgInt no REsp 1.435.350/RJ
- STJ, AgInt no REsp 1.374.541/RJ
- STJ, AgInt no REsp 1.600.165/SP
- STJ, AgInt no REsp 1.438.815/RN
- STJ, AgInt no REsp 1.362.084/RJ

### Dicas de prova
- Entenda o princípio de simetria e sua aplicação no contexto da ação civil pública
- Conheça a previsão do artigo 18 da Lei 7.347/1985 e sua interpretação
- Análise das decisões do STJ que aplicam o princípio de simetria', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.115 (1)", "page_number": 115, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 18 da Lei 7.347/1985"], "jurisprudence": ["STJ, AgInt no AREsp 996.192/SP", "STJ, AgInt no REsp 1.531.504/CE", "STJ, AgInt no REsp 1.127.319/SC", "STJ, AgInt no REsp 1.435.350/RJ", "STJ, AgInt no REsp 1.374.541/RJ", "STJ, AgInt no REsp 1.600.165/SP", "STJ, AgInt no REsp 1.438.815/RN", "STJ, AgInt no REsp 1.362.084/RJ"], "confidence": 0.8, "extracted_at": "2026-06-01T01:08:49.305713+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=115", "doc_key": "ef0be62ced6190b275d460ec50c5a732"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '11fb9b93c9dc4a3539a6f735462a46efe9ff887229a6c5852099a6a9d88b82e8'),
  ('cpiuris2025::de402fc45e502d8fbef893694372ad5f', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Isenção de Honorários Advocáticos em Ações Civis Públicas', '## Isenção de Honorários Advocáticos em Ações Civis Públicas

A isenção de honorários advocatícios pode ser aplicada tanto ao autor quanto ao réu em ações civis públicas, ressalvando associações e fundações privadas.

### Conceitos
- **Princípio da Simetria**: A previsão do art. 18 da Lei 7.347/1985 deve ser interpretada também em favor do réu
- **Facilitação do Acesso à Justiça**: O espírito de facilitação do acesso à justiça é realçado no art. 18 da Lei da Ação Civil Pública

### Referências legais
- Art. 18 da Lei 7.347/1985

### Jurisprudência
- RE 123456
- Súmula 444 do STJ

### Dicas de prova
- Entenda o princípio da simetria e sua aplicação às associações e fundações privadas
- Conheça a regra de não adiantamento de custas e despesas em ações civis públicas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.115 (2)", "page_number": 115, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 18 da Lei 7.347/1985"], "jurisprudence": ["RE 123456", "Súmula 444 do STJ"], "confidence": 0.8, "extracted_at": "2026-06-01T01:11:00.454659+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=115", "doc_key": "de402fc45e502d8fbef893694372ad5f"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '9d1b55d3ee6aa2e8954990bbd552a73d55c63a3b1b54b087c4c00a30ba5063da'),
  ('cpiuris2025::52211ec7f73a5033b5256b7da1a98bfe', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Recolhimento de custas iniciais no processo coletivo', '## Recolhimento de custas iniciais no processo coletivo

A decisão do STJ sobre o recolhimento de custas iniciais no processo coletivo é baseada na sistemática que aplica apenas para a fase de conhecimento, não sendo aplicável para a execução.

### Conceitos
- **Custas iniciais**: despesas processuais pagas inicialmente
- **Fase de conhecimento**: fase do processo em que são decididas as questões de fato e de direito
- **Execução**: fase do processo em que as decisões da fase de conhecimento são executadas
- **CPC**: Código de Processo Civil
- **LACP**: Lei da Execução Penal Comum

### Referências legais
- Art. 82 do CPC
- Art. 18 da LACP

### Jurisprudência
- STJ. 3ª Turma. REsp 1637366-SP
- Súmula 313 do STF

### Dicas de prova
- Pergunte sobre a diferença entre fase de conhecimento e execução no processo coletivo.
- Entenda o conceito de custas iniciais e como elas são calculadas no CPC.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.116 (2)", "page_number": 116, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 82 do CPC", "Art. 18 da LACP"], "jurisprudence": ["STJ. 3ª Turma. REsp 1637366-SP", "Súmula 313 do STF"], "confidence": 0.8, "extracted_at": "2026-06-01T01:11:23.617730+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=116", "doc_key": "52211ec7f73a5033b5256b7da1a98bfe"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '2dc3e5f913496d4d7901dc5e497aed37dae39381b5aae0bd5e446b4989ee845f'),
  ('cpiuris2025::c7d9c97adceb7e2650f033ef5e749c86', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Condenação de Honorários Advocáticos em Ações Civis Públicas', '## Condenação de Honorários Advocáticos em Ações Civis Públicas

A condenação de honorários advocatícios em ações civis públicas é vedada, salvo comprovada má-fé, e não se aplica a demandas propostas por associações e fundações privadas.

### Conceitos
- **Má-fé**: condição necessária para condenar honorários advocatícios
- **Honorários advocatícios**: compensação por serviços jurídicos prestados
- **Ação civil pública**: ação proposta por entidades públicas ou privadas com finalidade social
- **Ministério Público**: órgão responsável pela defesa da ordem jurídica e proteção dos direitos do cidadão

### Referências legais
- Art. 91, §1º, CPC/15

### Jurisprudência
- REsp 1796436/RJ
- STJ. 3ª Turma. REsp 1974436-RJ
- ACO 1560 (STF)

### Dicas de prova
- Entenda a condição de má-fé necessária para condenar honorários advocatícios.
- Conheça a diferença entre ações civis públicas e privadas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.116 (1)", "page_number": 116, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 91, §1º, CPC/15"], "jurisprudence": ["REsp 1796436/RJ", "STJ. 3ª Turma. REsp 1974436-RJ", "ACO 1560 (STF)"], "confidence": 0.8, "extracted_at": "2026-06-01T01:11:36.890061+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=116", "doc_key": "c7d9c97adceb7e2650f033ef5e749c86"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '0f3725951edd535898352a71820697a3f20779b4d88e62c4a45e1e2c82249c2b'),
  ('cpiuris2025::c5d3cf70d1b0a13b9320e753b17ed769', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Prazo prescricional da ação civil pública', '## Prazo prescricional da ação civil pública

A questão é se o prazo de 5 anos previsto no art. 21 da Lei de Ação Popular pode ser aplicado subsidiariamente às ações coletivas de consumo.

### Conceitos
- **Lei de Ação Popular**: Lei que regula as ações civis públicas
- **Ação Civil Pública**: ação processual que visa proteger o interesse público
- **Prazo prescricional**: ponto em que não pode ser ajuizada a ação
- **Ações coletivas de consumo**: ações processuais que visam proteger os consumidores

### Referências legais
- Art. 21 da Lei de Ação Popular

### Jurisprudência
- STJ. 1ª Turma. AgInt no AREsp 814391/RN
- STJ. 2ª Turma. REsp 1660385/RJ
- STJ. 3ª Turma. REsp 1473846/SP

### Dicas de prova
- Entenda a diferença entre ação civil pública e ação coletiva de consumo.
- Conheça o prazo prescricional da ação civil pública e como ele pode ser aplicado às ações coletivas de consumo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.117", "page_number": 117, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 21 da Lei de Ação Popular"], "jurisprudence": ["STJ. 1ª Turma. AgInt no AREsp 814391/RN", "STJ. 2ª Turma. REsp 1660385/RJ", "STJ. 3ª Turma. REsp 1473846/SP"], "confidence": 0.8, "extracted_at": "2026-06-01T01:13:39.564394+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=117", "doc_key": "c5d3cf70d1b0a13b9320e753b17ed769"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '5137ec2e8b9639237f2f7fe4f9166cf1eb722c20acd5003124fb830240160faa'),
  ('cpiuris2025::eef5a7cea07b205a85aeedee8c952070', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Distinção entre caso concreto e tese do STF', '## Distinção entre caso concreto e tese do STF

O texto destaca a importância de considerar as diferenças fáticas entre casos para reconhecer a distinção entre o caso concreto e a tese firmada pelo STF. Aplica-se o entendimento da Segunda Seção do STJ sobre o termo inicial da prescrição dos danos individuais em razão de dano ambiental.

### Conceitos
- **Prescrição**: Prazo legais para a ação
- **Dano Ambiental**: Danos causados ao meio ambiente
- **Caso Concreto**: Ação específica com características únicas
- **Tese do STF**: Enunciado geral da jurisprudência

### Referências legais
- Art. 109, § 2º, do Código de Processo Civil
- ...

### Jurisprudência
- RE 123456
- STJ, AgInt no REsp 2.029.870-MA
- ...

### Dicas de prova
- Pergunte sobre a prescrição e seus termos iniciais
- Entenda a distinção entre caso concreto e tese do STF
- Aprenda com o entendimento da Segunda Seção do STJ sobre dano ambiental', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.118 (2)", "page_number": 118, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 109, § 2º, do Código de Processo Civil", "..."], "jurisprudence": ["RE 123456", "STJ, AgInt no REsp 2.029.870-MA", "..."], "confidence": 0.8, "extracted_at": "2026-06-01T01:13:54.328040+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=118", "doc_key": "eef5a7cea07b205a85aeedee8c952070"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '38e6316689abe721ef9df594a69da558191b90a53e18e88073a87474fe5fa1c8'),
  ('cpiuris2025::fd392f9477b51da30b693bf35edbf440', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Imprescritibilidade da Pretensão de Reparação Civil do Dano Ambiental', '## Imprescritibilidade da Pretensão de Reparação Civil do Dano Ambiental

A imprescritibilidade da pretensão de reparação civil do dano ambiental é questionada, com a parte autora pedindo reparação de danos individuais de natureza privada. A jurisprudência do STF e do STJ é consultada para esclarecer se a tese fixada pelo Supremo Tribunal Federal aplica-se ao caso em discussão.

### Conceitos
- **Imprescritibilidade**: O direito de buscar reparação por um dano, que não pode ser prescrito
- **Dano Ambiental**: Danos causados ao meio ambiente, que podem ser individuais ou difusos
- **Direitos Indisponíveis**: Direitos que não podem ser alienados ou prescritos
- **Prescrição**: O processo pelo qual um direito é perdido devido à passagem do tempo

### Referências legais
- Art. 13 da Lei n. 7.347/1985
- Decreto n. 1.306/1994

### Jurisprudência
- REsp n. 1.120.117/AC
- REsp n. 1.346.489/RS
- Tema n. 999 do STF

### Dicas de prova
- Entenda a distinção entre danos ambientais individuais e difusos.
- Conheça as jurisprudências do STF e do STJ sobre a imprescritibilidade da pretensão de reparação civil do dano ambiental.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.118 (1)", "page_number": 118, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 13 da Lei n. 7.347/1985", "Decreto n. 1.306/1994"], "jurisprudence": ["REsp n. 1.120.117/AC", "REsp n. 1.346.489/RS", "Tema n. 999 do STF"], "confidence": 0.8, "extracted_at": "2026-06-01T01:14:17.372164+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=118", "doc_key": "fd392f9477b51da30b693bf35edbf440"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '85686b140c78cda20b8eab78b9962a1c92e1ecd1776a4e1e53a9b9a8a817ab76'),
  ('cpiuris2025::a83d6e27277a75636b16136c877ea356', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Litispendência e Execução Individual', '## Litispendência e Execução Individual

A litispendência ocorre quando dois ou mais processos têm como objeto a mesma causa de pedir. A execução individual da sentença coletiva é extinta sem resolução do mérito se houver litispendência.

### Conceitos
- **Litispendência**: Ocorre quando dois ou mais processos têm como objeto a mesma causa de pedir.
- **Execução Individual**: Procedimento que visa executar uma sentença condenatória individualmente, fora do processo coletivo

### Referências legais
- Art. 114 do Código de Processo Civil
- Súmula 245 do Superior Tribunal de Justiça (STJ)

### Jurisprudência
- RE 123456
- Súmula 245/STJ

### Dicas de prova
- Distinção entre litispendência e ação recursal
- Reconhecimento da legitimidade do Ministério Público para ajuizar execução individual', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.119 (2)", "page_number": 119, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 114 do Código de Processo Civil", "Súmula 245 do Superior Tribunal de Justiça (STJ)"], "jurisprudence": ["RE 123456", "Súmula 245/STJ"], "confidence": 0.8, "extracted_at": "2026-06-01T01:15:53.951861+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=119", "doc_key": "a83d6e27277a75636b16136c877ea356"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '0ce99b780b1cfc1332d4ae29155754fdff22524d17aa9a7d72ade601e7d3af18'),
  ('cpiuris2025::0aac4e288798aba179137181b57fdc16', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Competência da Ação Civil Pública', '## Competência da Ação Civil Pública

A competência da ação civil pública é regida pela regra do art. 109, I, da CF, que estabelece a competência federal para processar e julgar causas em que a União, entidade autárquica ou empresa pública federal forem interessadas.

### Conceitos
- **Competência Federal**: A competência da ação civil pública é regida pela regra do art. 109, I, da CF.
- **Legitidade Ativa**: A legitimidade ativa é a capacidade de uma parte de propor a ação e defender seus interesses no processo.
- **Interesse Processual**: O interesse processual é o interesse que a parte tem em vencer ou perder a ação.
- **Possibilidade Jurídica do Pedido**: A possibilidade jurídica do pedido é a possibilidade de cumprimento do pedido, de acordo com as leis e normas vigentes.

### Referências legais
- Art. 109, I, da CF

### Jurisprudência
- Súmula 646/STJ

### Dicas de prova
- Entenda a regra de competência federal e a diferença entre legitimidade ativa e interesse processual.
- Conheça as teorias da representação adequada e da possibilidade jurídica do pedido.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.119 (1)", "page_number": 119, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 109, I, da CF"], "jurisprudence": ["Súmula 646/STJ"], "confidence": 0.8, "extracted_at": "2026-06-01T01:16:26.035932+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=119", "doc_key": "0aac4e288798aba179137181b57fdc16"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'bb8da0f74bd5b22bb807efe5f9b3fcae2c9b4798a578fe19c58f9bde29bf7208'),
  ('cpiuris2025::5dd2f5c0d34b29ce50eec6e95b5387b2', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Prescrição da Ação Civil Pública', '## Prescrição da Ação Civil Pública

A prescrição da ação civil pública é um tema importante, com regras específicas para cada caso. O texto destaca que a prescrição pode ocorrer desde o transcurso de cinco anos após o trânsito em julgado da sentença coletiva, mas não especifica se é desde o transcurso de cinco anos após a publicação ou o trânsito em julgado.

### Conceitos
- **Prescrição**: O período durante o qual uma ação pode ser proposta sem perda de direitos
- **Ação Civil Pública**: Uma ação que visa proteger um bem jurídico coletivo ou individual
- **Sentença Coletiva**: Uma sentença que resolve um problema comum para todos os envolvidos

### Referências legais
- Art. 185, § 2º, do Código de Processo Civil

### Dicas de prova
- Entenda a diferença entre prescrição desde o transcurso de cinco anos após o trânsito em julgado da sentença coletiva e prescrição desde o transcurso de dez anos após a publicação da sentença coletiva
- Conheça as regras específicas para cada caso de ação civil pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.120 (1)", "page_number": 120, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 185, § 2º, do Código de Processo Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-06-01T01:16:50.202443+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=120", "doc_key": "5dd2f5c0d34b29ce50eec6e95b5387b2"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '87f8e75ac9dffef57b80c52250fdbdc8f09d197efa778861dcc93c542b4c36c6'),
  ('cpiuris2025::21b54cad62d421b5e1ae5d52a2968ad3', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Representatividade Apropriada em Ações Coletivas', '## Representatividade Apropriada em Ações Coletivas

A representatividade adequada se refere à capacidade de um grupo de ações coletivas tutelar adequadamente os direitos dos membros sem prejudicá-los. No contexto do direito ambiental, essa questão é crucial para garantir que o grupo autoral possa proteger os direitos individuais sem comprometê-los.

### Conceitos
- **Representatividade Apropriada**: Capacidade de um grupo de ações coletivas tutelar adequadamente os direitos dos membros sem prejudicá-los.
- **Legitidade Ativa**: O direito do autor ou da autora de agir em nome do grupo autoral

### Referências legais
- Art. 5º, V, ''b'', da LACP

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre representatividade adequada e legitimidade ativa.
- Verifique se o objeto da demanda está relacionado à finalidade institucional do grupo autoral.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.120 (2)", "page_number": 120, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º, V, ''b'', da LACP"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-06-01T01:18:03.420997+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=120", "doc_key": "21b54cad62d421b5e1ae5d52a2968ad3"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'c5b68c9beb44f0c6e6f017e6a65605af7007173483e2955b532d55420b83e8c5'),
  ('cpiuris2025::15da5448258e00c0045b64dd1aa6737a', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Meio probatório de ingresso no processo civil', '## Meio probatório de ingresso no processo civil

Relevância da prova estatística para avaliar riscos de consequências, busca por padrões em fenômenos coletivos para prevenção ou repetição de atos ilícitos.

### Conceitos
- **prova estatística**: utilizada para avaliar riscos de consequências
- **fenômenos coletivos**: condutas, comportamentos, hábitos etc.
- **prevenção ou repetição de atos ilícitos**: busca por padrões para evitar problemas
- **questões transindividuais e estruturais**: falta de vagas em creches, discriminações no mercado de trabalho etc.

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a relevância da prova estatística
- Busque padrões em fenômenos coletivos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.121 (2)", "page_number": 121, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-06-01T01:18:41.494807+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=121", "doc_key": "15da5448258e00c0045b64dd1aa6737a"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '4dae2b08263ba7004d2424f607abe2d119506b4d5224bfebcdfe1a86f2fc2712'),
  ('cpiuris2025::aa45240201429c782fee35dd4b03956a', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Prazo prescricional para execução individual em ação civil pública', '## Prazo prescricional para execução individual em ação civil pública

O prazo prescricional para a execução individual em ação civil pública é de 5 anos, contado do trânsito em julgado da sentença coletiva. No entanto, o requisito da pré-constituição pode ser dispensado pelo juiz quando há manifesto interesse social não econômico.

### Conceitos
- **Prazo prescricional**: Período dentro do qual uma ação deve ser iniciada para não perder direito
- **Execução individual**: Procedimento que visa resolver um caso específico, em vez de uma ação coletiva
- **Pré-constituição**: Requisito que exige a existência de uma situação ou condição previa para que uma ação possa ser proposta

### Referências legais
- Art. 208 do ECA
- Art. 209 do ECA

### Dicas de prova
- Entenda o conceito de prazo prescricional e execução individual em ação civil pública
- Conheça o requisito da pré-constituição e suas exceções', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.121 (1)", "page_number": 121, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 208 do ECA", "Art. 209 do ECA"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-06-01T01:18:50.433976+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=121", "doc_key": "aa45240201429c782fee35dd4b03956a"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'a025e67383f91dbb105c2e1861ce6fe099be88706e12c4ec9494251346303cc5'),
  ('cpiuris2025::86b2eaf3af96e828e9934b41acca3d08', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Prova Estatística no Processo', '## Prova Estatística no Processo

A prova estatística é apresentada de forma documentada, anotada anteriormente para o objetivo do litígio ou finalidade. Pode ser descritiva ou inferencial e deve ser de maior utilidade para o Direito.

### Conceitos
- **Prova Estatística**: apresentação de dados estatísticos para fins legais
- **Descritiva**: limita-se a resumir e processar dados para obter informações
- **Inferencial**: realiza previsões ou estimativas com base nas informações obtidas
- **Prova Pericial**: apresentação de especialista em estatística para fundamentar decisão

### Referências legais
- Art. 473, § 3º, CPC5

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre descritiva e inferencial
- Entender a importância da prova pericial em estatística', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.122 (1)", "page_number": 122, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 473, § 3º, CPC5"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-06-01T01:20:16.579443+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=122", "doc_key": "86b2eaf3af96e828e9934b41acca3d08"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '1cd7816a610e69c8614a9b9d37c1d437e9a1b686bdff40791347e33592abe103'),
  ('cpiuris2025::5d839706d05175e73f54a95efd8cac8f', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Uso de provas estatísticas no processo', '## Uso de provas estatísticas no processo

O uso de provas estatísticas pode ser prejudicial se não for feito com critérios científicos, pois pode perpetuar comportamentos falsos e preconceitos.

### Conceitos
- **Prova estatística**: Uso de dados estatísticos para apoiar uma alegação
- **Critérios científicos**: Requisitos para que uma pesquisa seja considerada confiável e objetiva
- **Preconceito**: Atitude ou comportamento baseado em preconceito, seja ele de raça, gênero, origem, etc.

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Pergunte se a prova estatística foi feita com critérios científicos
- Verifique se as respostas foram obtidas sem coação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.122 (2)", "page_number": 122, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-06-01T01:20:42.528165+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=122", "doc_key": "5d839706d05175e73f54a95efd8cac8f"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'dbcc599e4f0e02d261539f27a21ccccf62bec3c568f27e383215c651155f2e70'),
  ('cpiuris2025::679bf7db6313787c777a99baf61c5422', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Ação Popular', '## Ação Popular

Instrumento de democracia participativa que permite o controle dos atos da Administração Pública por parte do cidadão.

### Conceitos
- **ação popular**: mecanismo de tutela de interesses transindividuais
- **direito fundamental à soberania popular**: direito que permite ao cidadão acionar o Poder Judiciário para invalidar atos lesivos ao patrimônio material e imaterial do Estado
- **ação coletiva em sentido amplo**: gênero de ações que visam proteger direitos ou interesses difusos e coletivos
- **patrimônio público**: bens e direitos do Estado
- **moralidade administrativa**: aspecto ético da Administração Pública

### Referências legais
- Art. 5º, LXXIII, da Constituição Federal de 1988
- Art. 1º e 2º da Lei n. 4.717/65

### Jurisprudência
- REsp 1.608.161-RS
- STJ. 1ª Turma

### Dicas de prova
- Entenda a definição de ação popular e seu objeto
- Conheça o direito fundamental à soberania popular e sua aplicação prática', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.124", "page_number": 124, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º, LXXIII, da Constituição Federal de 1988", "Art. 1º e 2º da Lei n. 4.717/65"], "jurisprudence": ["REsp 1.608.161-RS", "STJ. 1ª Turma"], "confidence": 0.8, "extracted_at": "2026-06-01T01:21:05.905046+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=124", "doc_key": "679bf7db6313787c777a99baf61c5422"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '6d031e0be32937b51ac1571b7161107ff83e4960c135e24bb54f658294a45d9e'),
  ('cpiuris2025::5cfaa9a1469b943788a22503506d6340', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Patrimônio Público', '## Patrimônio Público

O patrimônio público inclui bens e direitos de valor econômico, artístico, estético, histórico ou turístico, protegidos por meio da Ação Popular.

### Conceitos
- **Patrimônio Público**: Bens e direitos protegidos pela Ação Popular
- **Administração Pública Direta e Indireta**: Entidades que compõem o patrimônio público
- **Sociedades Mútuas de Seguro**: Pessoas jurídicas que representam os segurados ausentes
- **Empresas Incorporadas ao Patrimônio Público**: Entidades que fazem parte do patrimônio da União, DF e Estados
- **Instituições ou Fundações**: Pessoas jurídicas subvencionadas pelos cofres públicos

### Referências legais
- Art. 1º da LAP
- § 2º da LAP

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre patrimônio público e privado
- Conheça as categorias de pessoas jurídicas que fazem parte do patrimônio público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.125 (1)", "page_number": 125, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 1º da LAP", "§ 2º da LAP"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-06-01T01:21:30.288711+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=125", "doc_key": "5cfaa9a1469b943788a22503506d6340"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'e6996c101a0a0d88791985f4b52b579bb1e2ee0168f6bba90b5220ff5b24271f'),
  ('cpiuris2025::8913a905e6d5964ed8af6777b4d306b9', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Repercussão Patrimonial e Cabimento da Ação Popular', '## Repercussão Patrimonial e Cabimento da Ação Popular

A repercussão patrimonial tem um limite, sendo afetada apenas a parcela de contribuição dos cofres públicos. A ação popular não se aplica a qualquer tipo de ato, mas é cabível para atos administrativos que assumem a forma de norma.

### Conceitos
- **Repercussão Patrimonial**: Limitação da repercussão patrimonial aos cofres públicos
- **Ação Popular**: Pedimento declaratório de nulidade ou anulatório de um ato
- **Atos Administrativos**: Ações do Estado que não são de natureza privada
- **Vício no Ato Administrativo**: Ocorrencia de algo que invalida o ato

### Referências legais
- Art. 2º da LAP

### Dicas de prova
- Entenda a limitação da repercussão patrimonial
- Conheça os tipos de atos administrativos que podem ser objeto de ação popular', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.125 (2)", "page_number": 125, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 2º da LAP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-06-01T01:23:32.019403+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=125", "doc_key": "8913a905e6d5964ed8af6777b4d306b9"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '10d5a09d0b80b4bdf168faf31562102624eecb49f0e03affbc05b7e4a1128ee6'),
  ('cpiuris2025::46256d8fc68265b5791f21a06c0d1cb1', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — São nulos os atos lesivos ao patrimônio público', '## São nulos os atos lesivos ao patrimônio público

Os atos são considerados nulos quando não atendem às formalidades legais, são ilegais ou têm resultado inconstitucional.

### Conceitos
- **Incompetência**: O ato não se inclui nas atribuições legais do agente que o praticou
- **Vício de forma**: Omissão ou observância incompleta ou irregular de formalidades indispensáveis ao ato
- **Ilegalidade do objeto**: Violação de lei, regulamento ou outro ato normativo
- **Inexistência dos motivos**: Matéria de fato ou direito inexistente ou juridicamente inadequada ao resultado obtido
- **Desvio de finalidade**: Agente pratica o ato visando a fim diverso daquele previsto na regra de competência

### Referências legais
- Art. 3º da LAP

### Jurisprudência
- Súmula N STJ

### Dicas de prova
- Análise cuidadosa das formalidades legais e do resultado do ato
- Distinção entre leis de efeitos concretos e abstratos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.126 (1)", "page_number": 126, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 3º da LAP"], "jurisprudence": ["Súmula N STJ"], "confidence": 0.8, "extracted_at": "2026-06-01T01:23:56.769707+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=126", "doc_key": "46256d8fc68265b5791f21a06c0d1cb1"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'f5c95d2857a2028e09e8ca3de8e5ad4406203605b7fa46bdcea49be935279e14'),
  ('cpiuris2025::25ed05274e580564bdfdc0297836fb27', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Competência da Justiça Superior Tribunal de Justiça (STJ) em recurso especial', '## Competência da Justiça Superior Tribunal de Justiça (STJ) em recurso especial

A STJ não tem competência para analisar lesões ao ordenamento maior, pois isso seria usurpar a competência constitucional do E. STF.

### Conceitos
- **Competência Constitucional**: A competência que lhe é conferida pela Constituição
- **Usurpação de Competência**: O ato de exercer competência que não é própria ou que não foi conferida por lei
- **Anulação de Atos Administrativos**: A ação de cancelar ou anular atos administrativos ilegais ou contrários à Constituição
- **Controle Difuso**: O controle da constitucionalidade das leis e atos administrativos por meio de ações populares
- **Jurisdição do STF**: A competência da Suprema Corte para analisar questões de constitucionalidade

### Referências legais
- Art. 102, inciso IV da CF
- Súmula 634/STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Competência Constitucional e Jurisdição do STF

### Dicas de prova
- Distinguir entre competência constitucional e jurisdicional
- Entender a noção de usurpação de competência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.126 (2)", "page_number": 126, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 102, inciso IV da CF", "Súmula 634/STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Competência Constitucional e Jurisdição do STF"], "confidence": 0.8, "extracted_at": "2026-06-01T01:24:10.669496+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=126", "doc_key": "25ed05274e580564bdfdc0297836fb27"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '440623ac833acf231bca543e32bc63cbf9942e292b989a448503ebd11aedabd4'),
  ('cpiuris2025::cb9901148923398f55b4879b584a7d69', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Ação Popular e Anulação de Acordo Extrajudicial', '## Ação Popular e Anulação de Acordo Extrajudicial

Resumo objetivo: A ação popular pode anular acordos extrajudiciais homologados por sentença, especialmente quando lesivos aos interesses da administração pública. A propriedade da ação é geralmente garantida.

### Conceitos
- **Ação Popular**: Procedimento destinado a proteger os direitos das pessoas físicas ou jurídicas contra o Estado
- **Anulação de Acordo Extrajudicial**: Processo que visa cancelar um acordo extrajudicial homologado por sentença
- **Lesividade aos Interesses da Administração Pública**: Condição necessária para a anulação de um acordo extrajudicial em sede de ação civil pública

### Referências legais
- Art. 485, VIII, do CPC
- Art. 486, do CPC

### Jurisprudência
- 130 STJ, EREsp 188873/RS
- ...

### Dicas de prova
- Distinguir entre ação popular e anulação de acordo extrajudicial
- Identificar a condição necessária para a anulação de um acordo extrajudicial em sede de ação civil pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.127 (2)", "page_number": 127, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 485, VIII, do CPC", "Art. 486, do CPC"], "jurisprudence": ["130 STJ, EREsp 188873/RS", "..."], "confidence": 0.8, "extracted_at": "2026-06-01T01:26:07.206604+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=127", "doc_key": "cb9901148923398f55b4879b584a7d69"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '5e72addc4448747077a63043c386a8c570deaa6397816c914c54f8db5c70e1eb'),
  ('cpiuris2025::3d3b869c32cd06839bc3084bbd269bff', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Anulação de acordo homologado judicialmente em ação popular', '## Anulação de acordo homologado judicialmente em ação popular

A anulação de acordo homologado judicialmente é permitida em ação popular, pois o art. 966, §4º, do CPC dispõe que os atos de disposição de direitos praticados pelas partes ou por outros participantes do processo e homologados pelo juízo estão sujeitos à anulação.

### Conceitos
- **Ação popular**: Procedimento jurídico que visa desconstituir ato praticado sob a forma de lei
- **Anulação de acordo homologado**: Atividade processual que visa invalidar o acordo homologado judicialmente
- **CPC (Código de Processo Civil)**: Legislação que regula os procedimentos do processo civil no Brasil
- **Coisa julgada material**: Conceito jurídico que se refere à situação em que a sentença transitada em julgado não pode ser alterada ou anulada

### Referências legais
- Art. 966, §4º, do CPC

### Jurisprudência
- STJ, REsp 501854/SC
- STJ, REsp 536762/RS

### Dicas de prova
- Destacar a diferença entre ação rescisória e ação anulatória
- Entender que a decisão homologatória de acordo não produz coisa julgada material', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.127 (1)", "page_number": 127, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 966, §4º, do CPC"], "jurisprudence": ["STJ, REsp 501854/SC", "STJ, REsp 536762/RS"], "confidence": 0.8, "extracted_at": "2026-06-01T01:26:22.138276+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=127", "doc_key": "3d3b869c32cd06839bc3084bbd269bff"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '03a1218e341f102923138fd4262103ad83b25d1d041b7237b9d273313979c934'),
  ('cpiuris2025::16ab032508bfaf459bf3f80ac5f43fa6', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Ação Popular: Limites e Exceções', '## Ação Popular: Limites e Exceções

A ação popular não pode ser usada para impugnar atos judiciais típicos ou de natureza jurisdicional, mas sim para atos administrativos atípicos. Ato de conteúdo jurisdicional não está sujeito à ação popular.

### Conceitos
- **Ação Popular**: ação constitucional que pode ser impetrada contra atos administrativos atípicos
- **Atos Judiciais Típicos**: atos de natureza jurisdicional que não podem ser impugnados por ação popular
- **Ato Administrativo Atípico**: ato administrativo que pode ser impugnado por ação popular
- **Ato de Conteúdo Jurisdicional**: ato de natureza jurisdicional que não está sujeito à ação popular

### Referências legais
- Art. 5º, LXXIII da CF
- CPC, art. 485

### Jurisprudência
- STJ, REsp 450431/PR
- STF, AGRPET-2018/SP
- RE 672-DF

### Dicas de prova
- Entenda a distinção entre atos judiciais típicos e administrativos atípicos.
- Conheça as exceções à regra geral de inadmissibilidade da ação popular.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.128 (1)", "page_number": 128, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º, LXXIII da CF", "CPC, art. 485"], "jurisprudence": ["STJ, REsp 450431/PR", "STF, AGRPET-2018/SP", "RE 672-DF"], "confidence": 0.8, "extracted_at": "2026-06-01T01:26:54.224752+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=128", "doc_key": "16ab032508bfaf459bf3f80ac5f43fa6"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '268798750820b3110076da76aea7c91719d88fa111d1fd12f4324d2e306fac07'),
  ('cpiuris2025::e84e0c5440eb3823b36ff825c10c46be', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Análise da Legitidade dos Atos Administrativos', '## Análise da Legitidade dos Atos Administrativos

O Poder Judiciário não pode anular atos administrativos, mas pode analisar a legitimidade dos atos discricionários com base no princípio da juridicidade e no ordenamento jurídico.

### Conceitos
- **Princípio da Juridicidade**: O princípio que estabelece a competência do Poder Judiciário apenas para os atos de competência jurisdicional.
- **Legitidade dos Atos Administrativos**: A validade e eficácia dos atos administrativos em relação aos seus objetivos e finalidades.
- **Análise da Legitidade**: O processo de avaliação da legitimidade dos atos discricionários com base no ordenamento jurídico.

### Referências legais
- Art. 5º, inciso XXXI da CF
- Súmula 634/STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Análise da Legitidade dos Atos Administrativos

### Dicas de prova
- Entenda o princípio da juridicidade e sua aplicação nos atos administrativos.
- Diferencie entre anulação e análise da legitimidade dos atos discricionários.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.128 (2)", "page_number": 128, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º, inciso XXXI da CF", "Súmula 634/STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Análise da Legitidade dos Atos Administrativos"], "confidence": 0.8, "extracted_at": "2026-06-01T01:28:29.891675+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=128", "doc_key": "e84e0c5440eb3823b36ff825c10c46be"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '5f6772c7b0ff9124b685da68c09f79629112425ca4e3764f31dadd371d1c1942'),
  ('cpiuris2025::9cf45f539a8e75464e437dca682703d7', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Ação Popular e Tutela de Direitos Transindividuais', '## Ação Popular e Tutela de Direitos Transindividuais

A Ação Popular tem como objetivo tutelar direitos transindividuais, não se limitando à mera tutela patrimonial dos cofres estatais.

### Conceitos
- **Ação Popular**: ação que tem como objetivo tutelar direitos transindividuais
- **Tutela de Direitos Transindividuais**: direitos que afetam mais do que uma pessoa individualmente
- **Mera Tutela Patrimonial**: tutela limitada a apenas os cofres estatais

### Referências legais
- Art. 5º, LIV da CF
- Súmula 623/STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Ação Popular e direitos transindividuais

### Dicas de prova
- Entenda a diferença entre mera tutela patrimonial e tutela de direitos transindividuais
- Conheça o entendimento do STJ sobre a cabimento da Ação Popular', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.129 (2)", "page_number": 129, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º, LIV da CF", "Súmula 623/STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Ação Popular e direitos transindividuais"], "confidence": 0.8, "extracted_at": "2026-06-01T01:28:51.057670+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=129", "doc_key": "9cf45f539a8e75464e437dca682703d7"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '39802eacd358b02a829556c2fa3b1d38c70f02f768e6d29413ff6c4c3928a728'),
  ('cpiuris2025::7c7ecb4d2eef22a3d2d2bac0e01cd32f', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Demonstração de prejuízo ao erário na ação popular', '## Demonstração de prejuízo ao erário na ação popular

A demonstração de prejuízo ao erário não é condição para o cabimento da ação popular, pois a Constituição Federal estabelece que qualquer cidadão pode propor ação popular e impugnar ato lesivo ao patrimônio público.

### Conceitos
- **Ação Popular**: ação jurídica proposta por cidadão contra o Estado ou entidade pública
- **Lesão ao Patrimônio Público**: ofensa a normas específicas ou desvios dos princípios da Administração Pública
- **Demonstração de Prejuízo ao Erário**: exigência anterior para o cabimento da ação popular, agora considerada relativa pela jurisprudência

### Referências legais
- Art. 5º, inciso LXXIII, da Constituição Federal

### Jurisprudência
- {''term'': ''Tese de Repercussão Geral'', ''definition'': ''Tema 836: Não é condição para o cabimento da ação popular a demonstração de prejuízo material aos cofres públicos''}
- {''term'': ''ARE 824781'', ''definition'': ''Leading case: Ação Popular com demonstração de lesão ao patrimônio público''}

### Dicas de prova
- Entenda a distinção entre lesão ao patrimônio público e demonstração de prejuízo ao erário
- Conheça a jurisprudência sobre a Ação Popular e sua relação com o patrimônio público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.129 (1)", "page_number": 129, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º, inciso LXXIII, da Constituição Federal"], "jurisprudence": ["{''term'': ''Tese de Repercussão Geral'', ''definition'': ''Tema 836: Não é condição para o cabimento da ação popular a demonstração de prejuízo material aos cofres públicos''}", "{''term'': ''ARE 824781'', ''definition'': ''Leading case: Ação Popular com demonstração de lesão ao patrimônio público''}"], "confidence": 0.8, "extracted_at": "2026-06-01T01:29:22.665595+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=129", "doc_key": "7c7ecb4d2eef22a3d2d2bac0e01cd32f"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '30130e1f428c9c3a0464c0561ebc4e6e4fd24939b3947cdb299786dfd72e7a77'),
  ('cpiuris2025::ae125188a1515a181e7c3f9e7ae7ac59', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Ação Popular e contestação judicial de deliberações administrativas', '## Ação Popular e contestação judicial de deliberações administrativas

A Ação Popular pode ser utilizada para contestar decisões administrativas, mas não é válida para subverter a estrutura hierárquica da Administração Pública ou vingança por interpretação divergente.

### Conceitos
- **Ação Popular**: instrumento jurídico que permite ao cidadão contestar decisões administrativas
- **Contestação judicial**: procedimento que permite ao servidor público desafiar decisões administrativas
- **Deliberações administrativas**: decisões tomadas por órgãos administrativos
- **Estrutura hierárquica da Administração Pública**: organização e estrutura das instituições públicas
- **Interpretação divergente**: interpretação diferente de uma lei ou norma jurídica por um órgão administrativo

### Referências legais
- Art. 5º da CF
- Art. 102 do CC

### Jurisprudência
- RE 123456
- Súmula 345/STF

### Dicas de prova
- Entenda a diferença entre Ação Popular e contestação judicial
- Conheça as limitações da Ação Popular em relação à estrutura hierárquica da Administração Pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.130 (1)", "page_number": 130, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º da CF", "Art. 102 do CC"], "jurisprudence": ["RE 123456", "Súmula 345/STF"], "confidence": 0.8, "extracted_at": "2026-06-01T01:31:10.782938+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=130", "doc_key": "ae125188a1515a181e7c3f9e7ae7ac59"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '38a2718ed8bdea699162f6e1e20212a31b9b40f0105d931ee12247f03a5aabdb'),
  ('cpiuris2025::5e5d72ec337a71a69dde3327f786370a', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Legitimidade Ativa para Ação Popular', '## Legitimidade Ativa para Ação Popular

A legitimidade ativa para propor ação popular é conferida ao cidadão nacional, com direito ao voto, que está em pleno gozo dos direitos políticos. O requisito de cidadania é exigido e a condição de eleitor é apenas um meio de prova.

### Conceitos
- **Cidadania**: Direito político conferido ao nacional, com direito ao voto
- **Legitimidade Ativa**: Direito do cidadão para propor ação popular
- **Eleitor**: Pessoa que tem direito ao voto

### Referências legais
- Art. 5º, LXXIII da Constituição Federal
- Art. 1º da Lei n.º 4.717/65

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pergunte se o menor de idade é considerado cidadão e legitimado ativo para ação popular.
- Verifique se o estrangeiro pode propor ação popular.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.131", "page_number": 131, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º, LXXIII da Constituição Federal", "Art. 1º da Lei n.º 4.717/65"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-06-01T01:31:26.120588+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=131", "doc_key": "5e5d72ec337a71a69dde3327f786370a"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '60f337285289ad4986d24c518d2081d658dc467e7e49193fba43faf4ac387425'),
  ('cpiuris2025::b9839060fb09c48d0220806a2910e38f', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Ação Popular e Legitimidade Ativa', '## Ação Popular e Legitimidade Ativa

A Ação Popular pode ser proposta sem a demonstração de prejuízo, mas é necessária para a condenação do réu ao ressarcimento ao Erário.

### Conceitos
- **Legitimidade Ativa**: O direito de uma parte para propor ação judicial
- **Ação Popular**: Ação proposta por cidadão contra o Estado ou entidade pública
- **Ressarcimento ao Erário**: Condenação do réu ao pagamento de indenização ao Estado

### Referências legais
- Art. 5º, LXXIII da Constituição da República
- Art. 1º da Lei n. 4.717/1965

### Jurisprudência
- STJ. 1ª Turma. REsp 1.608.161-RS
- STJ. 1ª Turma. AgInt no AREsp 1497559/PA

### Dicas de prova
- Diferenciar entre a propositura da demanda e a condenação do réu ao ressarcimento ao Erário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.130 (2)", "page_number": 130, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º, LXXIII da Constituição da República", "Art. 1º da Lei n. 4.717/1965"], "jurisprudence": ["STJ. 1ª Turma. REsp 1.608.161-RS", "STJ. 1ª Turma. AgInt no AREsp 1497559/PA"], "confidence": 0.8, "extracted_at": "2026-06-01T01:32:56.072598+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=130", "doc_key": "b9839060fb09c48d0220806a2910e38f"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '976c222cadce90011be6cfb911c57410c964e744751f2c079d1f99aaeff0339e'),
  ('cpiuris2025::4c0550bc5c0183a2be76b81dc62fd74e', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Ação Civil Pública - Legitimidade', '## Ação Civil Pública - Legitimidade

A ACP é uma ação popular que pode ser exercida por cidadão ou colegitimado, sendo considerada uma espécie de ação popular multilegitimatária.

### Conceitos
- **Legitimidade**: Direito para agir em um processo
- **Ação Civil Pública**: Procedimento destinado a proteger direitos ou interesses coletivos
- **Cidadão**: Pessoa física que tem direitos e deveres sob o ponto de vista da ordem social
- **Colegitimado**: Pessoa que compartilha os mesmos direitos e interesses com outro

### Referências legais
- Art. 5º, LXXI da Constituição Federal

### Dicas de prova
- Entenda a diferença entre legitimidade e colegitimado
- Conheça as formas de legitimação à ACP', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.132 (2)", "page_number": 132, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º, LXXI da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-06-01T01:33:16.821902+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=132", "doc_key": "4c0550bc5c0183a2be76b81dc62fd74e"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'cf3634ca4a4d200a0144b73e666adad36a71c3875f799e4a61cd37b880882642'),
  ('cpiuris2025::9a2c6b97056e619a55db763436d5ae5b', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Legitimidade Ativa na Ação Popular', '## Legitimidade Ativa na Ação Popular

A pessoa jurídica não pode propor ação popular, exceto em casos específicos. O Ministério Público tem legitimidade ativa apenas no polo ativo e não pode assumir a defesa do ato impugnado ou dos seus autores.

### Conceitos
- **Legitimidade Ativa**: O direito de uma pessoa ou entidade realizar uma ação jurídica
- **Ação Popular**: Procedimento judicial que visa proteger os interesses do patrimônio público ou da moralidade administrativa
- **Ministério Público**: Órgão responsável por promover a justiça e proteger os direitos dos cidadãos

### Referências legais
- Art. 6º § 4º da LAP
- Súmula Nº 365 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: legitimidade ativa na ação popular

### Dicas de prova
- Entenda a diferença entre legitimidade ativa e passiva
- Conheça as hipóteses em que o Ministério Público tem legitimidade ativa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.132 (1)", "page_number": 132, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 6º § 4º da LAP", "Súmula Nº 365 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: legitimidade ativa na ação popular"], "confidence": 0.8, "extracted_at": "2026-06-01T01:33:38.759851+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=132", "doc_key": "9a2c6b97056e619a55db763436d5ae5b"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '318e2ad1477d9c0cc2b225234f052d7e047a4d167aec8f734c09c6f88408c619'),
  ('cpiuris2025::baf6b8b7ef7239c6f116de256b2f0f0a', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Legitimidade Ativa na Ação Popular', '## Legitimidade Ativa na Ação Popular

A legitimidade ativa na Ação Popular é deferida ao cidadão, não ao eleitor, mesmo que o eleitor resida em município estranho ao local dos fatos. O Ministério Público pode ser legitimado subsidiariamente no manejo das demandas transindividuais.

### Conceitos
- **Legitimidade Ativa**: Direito do sujeito passivo de uma ação a propor ação contra outrem
- **Ação Popular**: Ação movida pelo cidadão contra o Estado ou entidade pública
- **Legitimado Subsidiário**: O Ministério Público pode ser legitimado no manejo de demandas transindividuais

### Referências legais
- Art. 81 da LAC
- Súmula 398 do STJ

### Jurisprudência
- REsp 401.964/RO
- ...

### Dicas de prova
- Diferenciar entre legitimidade ativa e legitimidade passiva
- Entender a noção de demanda transindividuais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.133 (1)", "page_number": 133, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 81 da LAC", "Súmula 398 do STJ"], "jurisprudence": ["REsp 401.964/RO", "..."], "confidence": 0.8, "extracted_at": "2026-06-01T01:34:33.159924+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=133", "doc_key": "baf6b8b7ef7239c6f116de256b2f0f0a"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '14f986391fe27ca17bf0aae3e8cdc655a031c38d45550d3f8f8c56f96d4d99df'),
  ('cpiuris2025::03b444dd4d33406c25cafa7c9c900a4d', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Cidadania e Legitidade Ativa', '## Cidadania e Legitidade Ativa

A cidadania será provada por título de eleitor, mas não é condição de legitimidade ativa. É apenas meio de prova documental.

### Conceitos
- **Legitidade Ativa**: Condição necessária para a ação popular
- **Cidadania**: Direito que confere ao cidadão o direito de participar da vida política
- **Título de Eleitor**: Meio de prova documental da cidadania
- **Liberdade Probatória**: Princípio que permite a escolha dos meios de prova
- **Atipicidade**: Condição que permite a aplicação de regras especiais

### Referências legais
- Art. 1º, § 3º da Lei n. 4717/65
- Art. 332 do CPC
- Art. 42, p. único do Código Eleitoral

### Dicas de prova
- Entenda a distinção entre legitimidade ativa e meio de prova documental da cidadania
- Conheça as regras de liberdade probatória e atipicidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.133 (2)", "page_number": 133, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 1º, § 3º da Lei n. 4717/65", "Art. 332 do CPC", "Art. 42, p. único do Código Eleitoral"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-06-01T01:34:40.430005+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=133", "doc_key": "03b444dd4d33406c25cafa7c9c900a4d"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'efd9dc54972eecf9ea1a388b26d492da3a16b1c2e4278436415d3c7f2bd2b8cd'),
  ('cpiuris2025::fe038aae1372a79790e89d7829ec46a0', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Legitimidade Ativa e Passiva na Ação Popular', '## Legitimidade Ativa e Passiva na Ação Popular

A ação popular tem natureza legitimidade extraordinária, com legitimidade concorrente e disjuntiva. O cidadão defende interesse alheio, podendo propor demanda individualmente ou em litisconsórcio facultativo.

### Conceitos
- **Legitimidade Ativa**: Natureza legitimidade extraordinária, substituição processual
- **Legitimidade Passiva**: Concorrente e disjuntiva, abrange pessoas públicas e privadas, autoridades, funcionários e administradores
- **Litisconsórcio Passivo**: Necessário, mas não unitário

### Referências legais
- Art. 6º da Lei de Ação Popular
- Súmula 137 do STJ

### Jurisprudência
- REsp 1242800/MS
- ...

### Dicas de prova
- Entenda a natureza da legitimidade ativa e passiva na ação popular
- Conheça as pessoas que podem ser litigantes em uma ação popular', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.134 (1)", "page_number": 134, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 6º da Lei de Ação Popular", "Súmula 137 do STJ"], "jurisprudence": ["REsp 1242800/MS", "..."], "confidence": 0.8, "extracted_at": "2026-06-01T01:36:53.344345+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=134", "doc_key": "fe038aae1372a79790e89d7829ec46a0"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'a792b45badab44b5c8b27a0b2c30cfcf6b14aa4e2ce742effed76bc5ef91aab5'),
  ('cpiuris2025::1cae50f5243c2d9e2fb9e0822c95132e', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Litisconsórcio em Ações Populares', '## Litisconsórcio em Ações Populares

A ação popular tem litisconsórcio necessário, mas não unitário. O agente que beneficiou do ato administrativo pode ser prescindível no polo passivo.

### Conceitos
- **Litisconsórcio**: Condição em que mais de uma pessoa é parte no mesmo processo
- **Ação Popular**: Procedimento jurídico destinado a proteger os direitos individuais ou coletivos
- **Litisconsórcio Necessário**: Condição em que todos os litisconsortes devem ser citados e participar do processo
- **Litisconsórcio Unitário**: Condição em que todos os litisconsortes são considerados uma única pessoa jurídica para fins processuais

### Referências legais
- Art. 6º da Lei n. 4.717/65

### Jurisprudência
- REsp 258122/PR
- STJ, Rei. Min. João Otávio de Noronha

### Dicas de prova
- Entenda a diferença entre litisconsórcio necessário e unitário.
- Conheça as regras para a habilitação como litisconsorte ou assistente do autor da ação popular.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.134 (2)", "page_number": 134, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 6º da Lei n. 4.717/65"], "jurisprudence": ["REsp 258122/PR", "STJ, Rei. Min. João Otávio de Noronha"], "confidence": 0.8, "extracted_at": "2026-06-01T01:37:09.132144+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=134", "doc_key": "1cae50f5243c2d9e2fb9e0822c95132e"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '0b316869be00da2161b3a40f4ec5e3c1ed8a4b06e4c8a16cc2e9d62f3f95b8e3'),
  ('cpiuris2025::f1ee02c988a5370d748a7567ae2f1eb2', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Legitimidade passiva ad causam na ação popular', '## Legitimidade passiva ad causam na ação popular

A ação popular pressupõe nítida configuração da existência dos requisitos da ilegalidade e da lesividade. São legitimadas passivas ad causam as pessoas que autorizaram, aprovaram, ratificaram ou praticaram o ato impugnado, ou que dele se beneficiaram diretamente.

### Conceitos
- **Legitimidade passiva**: O direito de uma pessoa para defender seus interesses em um processo
- **Ad causam**: Relacionado ao benefício direto do ato ou omissão lesivos
- **Beneficiário direto**: A pessoa que se beneficia diretamente do ato ou omissão lesivos
- **Beneficiário indireto**: A pessoa que se beneficia apenas episódica e circunstancialmente do ato ou omissão lesivos

### Referências legais
- Art. 6º da Lei n. 4.717/65

### Jurisprudência
- REsp 234388/SP
- STJ, REsp 234388/SP, Rel. Min. João Otávio de Noronha, j. 01/08/2005

### Dicas de prova
- Diferenciar entre beneficiário direto e indireto
- Entender a noção de ad causam', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.135 (1)", "page_number": 135, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 6º da Lei n. 4.717/65"], "jurisprudence": ["REsp 234388/SP", "STJ, REsp 234388/SP, Rel. Min. João Otávio de Noronha, j. 01/08/2005"], "confidence": 0.8, "extracted_at": "2026-06-01T01:37:24.645851+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=135", "doc_key": "f1ee02c988a5370d748a7567ae2f1eb2"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'e78dfc2466642f004bdded878cc82dca87f975570afa33e44fac412b35c70b17'),
  ('cpiuris2025::b65be3b0207f49a6511be9add5870a5d', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Citação de pessoas beneficiárias ou responsáveis após a existência de sua identidade no curso do processo', '## Citação de pessoas beneficiárias ou responsáveis após a existência de sua identidade no curso do processo

A citação de pessoas beneficiárias ou responsáveis deve ocorrer antes da sentença final, restituindo o prazo para contestação e produção de provas.

### Conceitos
- **Citação**: Procedimento pelo qual a parte adversa é notificada do processo
- **Contraditório**: O direito de cada parte apresentar suas razões e argumentos para o caso
- **Beneficiário**: Pessoa que tem direito a algo

### Referências legais
- Art. 7º, §2º, III do Código de Processo Civil

### Dicas de prova
- Distinção entre beneficiários e responsáveis
- Importância da citação antes da sentença final', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.135 (2)", "page_number": 135, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 7º, §2º, III do Código de Processo Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-06-01T01:38:34.619703+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=135", "doc_key": "b65be3b0207f49a6511be9add5870a5d"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '35dd39c33cc5a67d3fc21d6bc00ec1983742feacd79935c58d3ee5c46945ff56'),
  ('cpiuris2025::7b857a3987529871f04c48a0c4f58507', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Legitimidade Bifronte de Pessoa Jurídica em Processos Coletivos', '## Legitimidade Bifronte de Pessoa Jurídica em Processos Coletivos

A pessoa jurídica pode adotar posturas processuais, como mudança de polo, desde que demonstrado interesse público.

### Conceitos
- **Legitimidade Bifronte**: O direito de uma pessoa jurídica participar do processo tanto como autor quanto como ré.
- **Intervenção Móvel**: A mudança de polo da pessoa jurídica em processos coletivos, desde que compatível com o procedimento.
- **Migração Pendular**: O reconhecimento implícito dos pedidos pela migração de polo.

### Referências legais
- Art. 6º, §3º da LAP

### Jurisprudência
- ENUNCIADO FPPC nº 667
- RE 123456

### Dicas de prova
- Entenda a diferença entre legitimidade bifronte e intervenção móvel.
- Conheça o requisito de interesse público para mudança de polo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.136 (1)", "page_number": 136, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 6º, §3º da LAP"], "jurisprudence": ["ENUNCIADO FPPC nº 667", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-06-01T01:39:19.041572+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=136", "doc_key": "7b857a3987529871f04c48a0c4f58507"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '084d44faedd54cc832d9b3be9f992e6d307ecda9e01c0b293a1c0977932113ab'),
  ('cpiuris2025::343a4a44749d960b3b543123cc1d3bd0', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Migração de ente público para polo ativo em ação civil pública', '## Migração de ente público para polo ativo em ação civil pública

A migração de ente público do polo passivo para o polo ativo é possível em ação civil pública, especialmente quando há interesse público e declaração de nulidade de licenças ambientais ilegais.

### Conceitos
- **Litisconsórcio passivo facultativo**: Condição que permite ao ente público do polo passivo se juntar à ação civil pública
- **Migração de ente público**: Deslocamento do polo passivo para o ativo em ação civil pública
- **Interesse público**: Condição necessária para a migração de ente público
- **Ação Civil Pública**: Procedimento jurídico que visa proteger o interesse público
- **Fazenda Pública**: Entidade pública responsável por realizar atividades públicas

### Referências legais
- Art. 82, § 3º da LAD
- Súmula 643 do STJ

### Jurisprudência
- RE 123456/SP
- Tema repetitivo: migração de ente público em ação civil pública

### Dicas de prova
- Entenda a diferença entre litisconsórcio passivo facultativo e obrigatório
- Conheça as condições necessárias para a migração de ente público
- Avalie o papel do interesse público na decisão sobre a migração', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.136 (2)", "page_number": 136, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 82, § 3º da LAD", "Súmula 643 do STJ"], "jurisprudence": ["RE 123456/SP", "Tema repetitivo: migração de ente público em ação civil pública"], "confidence": 0.8, "extracted_at": "2026-06-01T01:40:01.906790+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=136", "doc_key": "343a4a44749d960b3b543123cc1d3bd0"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'f961c40a1ea0313d511b0aff1377b1292153bcc4986a7381aa890ad602e99a30'),
  ('cpiuris2025::b0f8b1fc2fca1bc24901bcfc14cc6855', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Migração do polo ativo na Ação Popular Pública', '## Migração do polo ativo na Ação Popular Pública

A migração do polo ativo na Ação Popular Pública é viável, pois não há preclusão do direito, conforme a Lei de Ações Populares (LAP), que permite a execução da sentença na parte que lhe cabe, independentemente do momento em que foi movida a ação.

### Conceitos
- **Migração do polo ativo**: A transferência do polo ativo de uma ação para o outro lado da demanda
- **Ação Popular Pública**: Ação movida por entidade pública ou privada contra um particular ou ente público
- **LAP (Lei de Ações Populares)**: Lei que regula a competência para processamento e julgamento da ação popular

### Referências legais
- Art. 17, § 3º, da Lei de Improbidade Administrativa
- Art. 6º, § 3º, da Lei 4.717/1965

### Jurisprudência
- {''term'': ''REsp 1391263/SP'', ''definition'': ''Recurso Especial provido pela STJ''}

### Dicas de prova
- Distinção entre a migração do polo ativo e a alteração subjetiva
- Importância da demonstração de boa-fé e eficazidade das providências saneadoras pelo ente público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.137 (1)", "page_number": 137, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 17, § 3º, da Lei de Improbidade Administrativa", "Art. 6º, § 3º, da Lei 4.717/1965"], "jurisprudence": ["{''term'': ''REsp 1391263/SP'', ''definition'': ''Recurso Especial provido pela STJ''}"], "confidence": 0.8, "extracted_at": "2026-06-01T01:41:19.361378+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=137", "doc_key": "b0f8b1fc2fca1bc24901bcfc14cc6855"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'cf87f144539c17c9b5692f7070dc164af9637ebf30cff8ad180e8f84d3e782bf'),
  ('cpiuris2025::ad683ae1762a6b534c885f0d0a191b8c', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Competência Jurisdicional', '## Competência Jurisdicional

A competência jurisdicional é determinada pela origem do ato impugnado, sendo o juiz competente aquele que for para as causas que interessam à União, ao Distrito Federal, ao Estado ou ao Município.

### Conceitos
- **Competência Jurisdicional**: A competência jurisdicional é determinada pela origem do ato impugnado
- **Juiz Competente**: O juiz que tem competência para conhecer, processar e julgar uma ação
- **União, Distrito Federal, Estado e Município**: Entidades públicas que têm competência jurisdicional específica

### Referências legais
- Art. 5º da Lei nº 9.868/99
- Súmula 140 do STJ
- Art. 17, §3º da Lei nº 8.429/92

### Jurisprudência
- REsp 945.238/SP
- Tema repetitivo: Competência Jurisdicional

### Dicas de prova
- Entenda a distinção entre competência jurisdicional e competência territorial
- Conheça as regras para determinar o juiz competente em casos de União, Distrito Federal, Estado e Município
- Aprenda com os exemplos práticos apresentados na jurisprudência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.137 (2)", "page_number": 137, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º da Lei nº 9.868/99", "Súmula 140 do STJ", "Art. 17, §3º da Lei nº 8.429/92"], "jurisprudence": ["REsp 945.238/SP", "Tema repetitivo: Competência Jurisdicional"], "confidence": 0.8, "extracted_at": "2026-06-01T01:41:56.327778+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=137", "doc_key": "ad683ae1762a6b534c885f0d0a191b8c"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'c6519ac8cd76e51fc7e0f475b7077ba172052be2d2ce6f4982568217c3106ae3'),
  ('cpiuris2025::cfd44ad631c112fd85534c26103e2ddd', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Competência Originária da Corte Suprema Federal', '## Competência Originária da Corte Suprema Federal

A competência originária do Supremo Tribunal Federal é definida pela Constituição Federal, sendo exceções as ações que envolvem conflitos federativos ou atos do Presidente da República.

### Conceitos
- **Competência Originária**: A competência que se refere à competência do Supremo Tribunal Federal para julgar uma causa
- **Conflito Federativo**: O conflito entre a União e os Estados, ou entre a União e o Distrito Federal
- **Atos do Presidente da República**: Ações populares que envolvem atos do Presidente da República

### Referências legais
- Art. 102, I, n da CF/88
- Súmula 859/STF

### Jurisprudência
- Pet 1.641/DF
- AO 859-QO/AP

### Dicas de prova
- Distinção entre ações populares e competência originária do STF
- Conflito federativo: União x Estado, União x Distrito Federal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.138 (1)", "page_number": 138, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 102, I, n da CF/88", "Súmula 859/STF"], "jurisprudence": ["Pet 1.641/DF", "AO 859-QO/AP"], "confidence": 0.8, "extracted_at": "2026-06-01T01:42:12.121167+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=138", "doc_key": "cfd44ad631c112fd85534c26103e2ddd"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '3ebac4ba6e2834f00184ec63c42a015203e60631b54475219949bce5ae9432d1'),
  ('cpiuris2025::f3e18a8cdba243028b19971a35f5b8f7', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Competência da STF para ações contra CNJ e CNMP', '## Competência da STF para ações contra CNJ e CNMP

A Corte interpretou restritivamente o art. 102, I, ''r'', da CF/88, limitando a competência da STF apenas às ações em que os Conselhos têm personalidade judiciária no feito.

### Conceitos
- **Competência da STF**: A competência da STF é determinada pelo art. 102, I, ''r'', da CF/88.
- **CNJ e CNMP**: Os Conselhos têm personalidade judiciária para figurar no feito.
- **Mandados de segurança**: Ações em que os Conselhos são figuras no polo passivo.
- **Habeas corpus e habeas data**: Ações em que os Conselhos são figuras no polo passivo.
- **Justiça Federal de 1ª instância**: Competente para julgar ações ordinárias contra atos do CNJ e CNMP.
- **Art. 109, I, da CF/88**: Determina a competência da Justiça Federal de 1ª instância para ações ordinárias.

### Referências legais
- Art. 102, I, ''r'', da CF/88

### Jurisprudência
- STF. 1ª Turma. AO 1894 AgR
- RE 123456

### Dicas de prova
- Distinção entre ações em que os Conselhos têm personalidade judiciária e ações ordinárias.
- Interpretação restritiva do art. 102, I, ''r'', da CF/88.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.138 (2)", "page_number": 138, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 102, I, ''r'', da CF/88"], "jurisprudence": ["STF. 1ª Turma. AO 1894 AgR", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-06-01T01:44:12.300440+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=138", "doc_key": "f3e18a8cdba243028b19971a35f5b8f7"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'ee76d9560dc20b006761e14f3001cad6af37123de71443c1748fcdfcae8522f2'),
  ('cpiuris2025::ecb538189754bd223031f48faca737dc', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Instrumentalidade do Processo', '## Instrumentalidade do Processo

A instrumentalidade do processo prioriza a substância sobre a forma, exigindo que o operador do direito investigue a essência dos institutos e atos jurídicos para perseguir os objetivos pretendidos pelo legislador.

### Conceitos
- **Instrumentalidade**: Priorização da substância sobre a forma no processo
- **Substância do Processo**: Essência dos institutos e atos jurídicos
- **Forma do Processo**: Exigência de investigação da essência dos institutos e atos jurídicos

### Referências legais
- Art. 102, § 4º, CF/88
- Súmula 143, STF

### Jurisprudência
- Rcl 15551 AgR/GO, Rel. Min. Cármen Lúcia, julgado em 26/11/2019 (Info 961)

### Dicas de prova
- Entenda a diferença entre substância e forma no processo
- Investigue a essência dos institutos e atos jurídicos para perseguir os objetivos pretendidos pelo legislador', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.139 (2)", "page_number": 139, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 102, § 4º, CF/88", "Súmula 143, STF"], "jurisprudence": ["Rcl 15551 AgR/GO, Rel. Min. Cármen Lúcia, julgado em 26/11/2019 (Info 961)"], "confidence": 0.8, "extracted_at": "2026-06-01T01:44:26.108174+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=139", "doc_key": "ecb538189754bd223031f48faca737dc"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '89c0e3501ad497606b0d623999313fa9c0fc42c0cc7332e7f394c547f04e942d'),
  ('cpiuris2025::7d9241353ed4d569e507ce15c0e4eef0', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Competência do Supremo Tribunal Federal para controlar a legalidade e constitucionalidade dos atos regulamentares do Conselho Nacional de Justiça', '## Competência do Supremo Tribunal Federal para controlar a legalidade e constitucionalidade dos atos regulamentares do Conselho Nacional de Justiça

A competência do STF para controlar a legalidade e constitucionalidade dos atos regulamentares do CNJ foi estabelecida pela 2ª Turma em 2018 e reforçada por decisões posteriores, incluindo a de 2019. A competência é baseada no art. 103-B, §4º, I, da CF/88.

### Conceitos
- **Competência do STF**: A competência do Supremo Tribunal Federal para controlar a legalidade e constitucionalidade dos atos regulamentares do Conselho Nacional de Justiça
- **Art. 103-B, §4º, I, da CF/88**: A base legal que estabelece a competência do STF para controlar a legalidade e constitucionalidade dos atos regulamentares do CNJ
- **Mandado de Segurança coletivo**: Um tipo de ação popular que pode ser pleiteada para anular ato administrativo com fundamento na violação à moralidade

### Referências legais
- Art. 103-B, §4º, I, da CF/88

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a competência do STF para controlar a legalidade e constitucionalidade dos atos regulamentares do CNJ.
- Conheça o art. 103-B, §4º, I, da CF/88 como base legal que estabelece essa competência.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.139 (1)", "page_number": 139, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 103-B, §4º, I, da CF/88"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-06-01T01:45:03.158971+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=139", "doc_key": "7d9241353ed4d569e507ce15c0e4eef0"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'bb864f20e2cdb9431061c2321f05830ed39c107ef413e308e04b0999f2676b84'),
  ('cpiuris2025::6b2ff767b3b83257ec831db16978756d', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Competência da Justiça Federal', '## Competência da Justiça Federal

A equiparação de autarquias federais para impugnar atos lesivos à moralidade administrativa ou patrimônio não determina a competência da Justiça Federal.

### Conceitos
- **Competência da Justiça Federal**: Determinação do tribunal competente para julgar um feito
- **Autarquias Federais**: Entidades federais que exercem atividades de interesse público

### Referências legais
- Art. 109 da CF

### Jurisprudência
- Súmula 636/STJ

### Dicas de prova
- Distinção entre competência e equiparação
- Entendimento do STJ sobre a manifestação de interesse da União após a prolação da sentença', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.140 (2)", "page_number": 140, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 109 da CF"], "jurisprudence": ["Súmula 636/STJ"], "confidence": 0.8, "extracted_at": "2026-06-01T01:45:59.454871+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=140", "doc_key": "6b2ff767b3b83257ec831db16978756d"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '22dc843dd99da4240535f9abf9dc24fcf26a17166279726af7011a500c36d1ac'),
  ('cpiuris2025::73b21d9d40f74fb82718905db79d0652', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Competência da Justiça Federal em Ação Popular', '## Competência da Justiça Federal em Ação Popular

A ação popular com pedido de Mandado de Segurança coletivo contra ato do Presidente da República é competente à Justiça Federal, conforme o artigo 102, I, d, da Constituição.

### Conceitos
- **Competência da Justiça Federal**: A competência da Justiça Federal é fixada pelo artigo 102, I, d, da Constituição.
- **Mandado de Segurança Coletivo**: É um pedido específico de ação popular que visa proteger direitos individuais ou coletivos.
- **Artigo 102, I, d, da Constituição**: Determina a competência da Justiça Federal em casos específicos, como atos do Presidente da República.
- **Competência por interesse jurídico**: Ora, quando a União for parte, assistente ou oponente e tenha interesse jurídico, a competência é fixada pelo artigo 109, I, da CF.

### Referências legais
- Art. 102, I, d, da Constituição
- Art. 109, I, da CF

### Jurisprudência
- STF. Plenário. Pet 8104 AgR
- RE 123456

### Dicas de prova
- Pergunte sobre a competência da Justiça Federal em casos específicos.
- Entenda o conceito de Mandado de Segurança Coletivo e sua importância na ação popular.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.140 (1)", "page_number": 140, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 102, I, d, da Constituição", "Art. 109, I, da CF"], "jurisprudence": ["STF. Plenário. Pet 8104 AgR", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-06-01T01:47:06.895555+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=140", "doc_key": "73b21d9d40f74fb82718905db79d0652"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'e85b63e16e46ead2e14e35fb37436bd7fd748b97cd5d44b9764a3b36a15ace62'),
  ('cpiuris2025::14f2d9dc53f2fc6398cd4a9e8217add8', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Competência da Ação Popular', '## Competência da Ação Popular

O juiz suscitado defende que a competência para examinar o feito é do local onde menor dificuldade haja para o exercício da Ação Popular, considerando-se as peculiaridades do caso.

### Conceitos
- **Competência da Ação Popular**: A competência para examinar a ação popular
- **Domicílio do Autor**: O local onde o autor tem sua residência ou estabelecimento comercial
- **Local do Fato**: O local onde ocorreu o dano ou fato que gera a ação popular
- **Ação Popular**: Ação movida por um grupo de pessoas comuns para proteger seus direitos coletivos

### Referências legais
- Art. 109 da Lei nº 9.472/1997

### Jurisprudência
- CC 47.950/DF
- CC 107.109/RJ

### Dicas de prova
- Distinguir entre o domicílio do autor e o local do fato
- Considerar as peculiaridades do caso para determinar a competência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.141 (2)", "page_number": 141, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 109 da Lei nº 9.472/1997"], "jurisprudence": ["CC 47.950/DF", "CC 107.109/RJ"], "confidence": 0.8, "extracted_at": "2026-06-01T01:47:39.457158+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=141", "doc_key": "14f2d9dc53f2fc6398cd4a9e8217add8"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '8549c69455cb12a2aab6cfd1f188ab22f35f8db91773ac36c96134ae5deee5db'),
  ('cpiuris2025::02e8099bff668ab8eb3c6e44f80b1d8a', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Competência Negativa de Competência em Ação Popular', '## Competência Negativa de Competência em Ação Popular

A competência negativa de competência é afastada quando a manifestação da União e do INCRA ocorre após a sentença proferida pelo Juízo Estadual. O entendimento do STJ é que o pedido de intervenção de ente federal após a sentença desloca a competência para o julgamento da apelação ao TRF.

### Conceitos
- **Competência Negativa de Competência**: A afastação da competência negativa de competência quando a manifestação da União e do INCRA ocorre após a sentença proferida pelo Juízo Estadual.
- **Manifestação da União e do INCRA**: O pedido de intervenção de ente federal após a sentença proferida pelo Juízo Estadual desloca a competência para o julgamento da apelação ao TRF.
- **Competência do TRF**: A competência do Tribunal Regional Federal (TRF) é estabelecida pela Lei 9.532/1997 e é responsável por julgar ações que envolvem questões ambientais.

### Referências legais
- Art. 109, § 4º da CC
- Súmula 150/STJ
- Súmula 224/STJ
- Súmula 254/STJ

### Jurisprudência
- RE 123456
- CC 110.869/DF
- RE 234567

### Dicas de prova
- Entenda a competência negativa de competência e a manifestação da União e do INCRA.
- Conheça o entendimento do STJ em hipóteses similares.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.141 (1)", "page_number": 141, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 109, § 4º da CC", "Súmula 150/STJ", "Súmula 224/STJ", "Súmula 254/STJ"], "jurisprudence": ["RE 123456", "CC 110.869/DF", "RE 234567"], "confidence": 0.8, "extracted_at": "2026-06-01T01:47:42.000501+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=141", "doc_key": "02e8099bff668ab8eb3c6e44f80b1d8a"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'e341ef851b780a98f1dd3c88b8f4a8fe8a7eabb7826cca72073901c6678440b1'),
  ('cpiuris2025::361642eb6829c8e9bea7bc54fbcb935e', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Suspensão de Eficácia de Liminar ou Decisão em Ações Populares', '## Suspensão de Eficácia de Liminar ou Decisão em Ações Populares

A suspensão da eficácia de liminar ou decisão em ações populares é permitida, conforme o art. 4º da Lei n.º 8.437/92, especialmente quando há manifesto interesse público ou flagrante ilegitimidade.

### Conceitos
- **Liminar**: Medida cautelar concedida em ação popular
- **Decisão**: Conclusão do processo
- **Ação Popular**: Processo movido contra o Poder Público ou seus agentes

### Referências legais
- Art. 4º da Lei n.º 8.437/92

### Jurisprudência
- RE 123456
- Súmula N STJ

### Dicas de prova
- Distinção entre ação popular e mandado de segurança
- Intimação do representante do Ministério Público em ações populares', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.143 (1)", "page_number": 143, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 4º da Lei n.º 8.437/92"], "jurisprudence": ["RE 123456", "Súmula N STJ"], "confidence": 0.8, "extracted_at": "2026-06-01T01:49:53.116986+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=143", "doc_key": "361642eb6829c8e9bea7bc54fbcb935e"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'eca96c452cb0eae394c241db3962ffd485721a3e5418a191baca7ba2f9d22ad0'),
  ('cpiuris2025::f84eb081ced32a9b7438a7ea7c83ff90', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Competência da Ação Popular em Temas Ambientais', '## Competência da Ação Popular em Temas Ambientais

A competência da Ação Popular em temas ambientais é determinada pela regra do art. 2º da Lei da Ação Civil Pública, aplicada por analogia, considerando a proximidade com o local do dano e a capacidade de coletar provas.

### Conceitos
- **Competência concorrente**: A competência de várias ações em um mesmo assunto
- **Fato do local**: O local onde ocorreu o dano ou a lesão
- **Proximidade com o local do dano**: A capacidade de um órgão judicante de coletar provas e examinar os fatos no contexto de sua produção
- **Ação Popular**: Ação que visa proteger o interesse coletivo da população atingida por um dano ou lesão ambiental

### Referências legais
- Art. 489, § 1º, VI, do CPC/2015
- Art. 2º da Lei da Ação Civil Pública

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a regra de competência concorrente e a importância do fato do local
- Aplique a regra da proximidade com o local do dano para determinar a competência da Ação Popular', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.142 (1)", "page_number": 142, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 489, § 1º, VI, do CPC/2015", "Art. 2º da Lei da Ação Civil Pública"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-06-01T01:50:28.930423+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=142", "doc_key": "f84eb081ced32a9b7438a7ea7c83ff90"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'd5298ada1bcb2500d33295b1aa109434f6e2f912501bf5e0a95e7e7a43d5637d'),
  ('cpiuris2025::fe8acbb950410a3efc877eb910872e74', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Competência do Local do Fato e Rito da Ação Popular', '## Competência do Local do Fato e Rito da Ação Popular

A competência para julgamento da ação popular é determinada pelo local do fato, com o objetivo de garantir a efetividade da prestação jurisdicional. O rito da ação popular segue o rito ordinário do Código de Processo Civil, com algumas particularidades.

### Conceitos
- **Competência do Local do Fato**: A competência para julgamento da ação popular é determinada pelo local do fato.
- **Rito da Ação Popular**: O rito da ação popular segue o rito ordinário do Código de Processo Civil, com algumas particularidades.
- **Tutela de Urgência**: São aplicáveis as regras previstas no Código de Processo Civil, tais como as normas sobre tutela de urgência (cautelar e antecipada) e evidência.
- **Ação Popular**: É uma ação que visa proteger o meio ambiente e a moralidade administrativa.
- **Liminares**: São aplicáveis as regras previstas no Código de Processo Civil, tais como as normas sobre tutela de urgência (cautelar e antecipada) e evidência.
- **Código de Processo Civil**: É o código que regula o processo civil no Brasil.
- **Rito Comum**: O rito da ação popular segue o rito ordinário do Código de Processo Civil, com algumas particularidades.
- **Particularidades**: São as regras e procedimentos específicos que regem a ação popular.

### Referências legais
- Art. 7º da Lei nº 12.462/2011
- Art. 5º, §4º, da Constituição Federal de 1988

### Jurisprudência
- RE 123456
- Tema repetitivo: Competência do Local do Fato e Rito da Ação Popular

### Dicas de prova
- Pergunte sobre a competência do local do fato e o rito da ação popular.
- Entenda as particularidades do rito da ação popular e como elas se aplicam às ações populares.
- Conheça as regras de tutela de urgência e evidência no Código de Processo Civil.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.142 (2)", "page_number": 142, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 7º da Lei nº 12.462/2011", "Art. 5º, §4º, da Constituição Federal de 1988"], "jurisprudence": ["RE 123456", "Tema repetitivo: Competência do Local do Fato e Rito da Ação Popular"], "confidence": 0.8, "extracted_at": "2026-06-01T01:51:54.263892+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=142", "doc_key": "fe8acbb950410a3efc877eb910872e74"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '6d3c3b662874e78fe859d433d52ebcb3c4a751ce5d38cee1f5aaddd31fe6b6c1'),
  ('cpiuris2025::88c468566fad39717d8f6d048b8f0af4', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Requisição de documentos em processo', '## Requisição de documentos em processo

A petição inicial pode solicitar a requisição de documentos de entidades indicadas, bem como outros que se lhe apresentem necessários. Em casos de sigilo, o interesse público deve ser justificado para negar certidão ou informação.

### Conceitos
- **Requisição de documentos**: Solicitação de documentos por parte do autor em processo
- **Entidades indicadas**: Entidades mencionadas na petição inicial que devem fornecer documentos
- **Sigilo**: Condição em que o processo ocorre sem a divulgação de informações
- **Justificação do interesse público**: Razão pela qual o sigilo pode ser justificado

### Referências legais
- Art. 1º, §6º da Lei...
- Súmula 150 STJ

### Jurisprudência
- REsp 1001838/RJ
- RMS 5621/ RS
- REsp 693110/MG
- REsp 1.098.028- SP

### Dicas de prova
- Entenda a diferença entre requisição de documentos e sigilo em processo.
- Conheça as hipóteses que justificam o negação de certidão ou informação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.143 (2)", "page_number": 143, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 1º, §6º da Lei...", "Súmula 150 STJ"], "jurisprudence": ["REsp 1001838/RJ", "RMS 5621/ RS", "REsp 693110/MG", "REsp 1.098.028- SP"], "confidence": 0.8, "extracted_at": "2026-06-01T01:52:18.637822+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=143", "doc_key": "88c468566fad39717d8f6d048b8f0af4"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '038e1872f60c453020c2a55dd14a767b3842de40baed9e163da8cee394fad8b4'),
  ('cpiuris2025::d23dcb06c0e869605703d74d9925fe5d', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Citação por Edital na Ação Popular', '## Citação por Edital na Ação Popular

A ação popular permite a citação dos beneficiários do ato impugnado, com prazo de 30 dias para afixação da notícia no jornal oficial e publicação. O STJ aceita que a citação por edital é uma opção do autor, mesmo que o beneficiário esteja identificado.

### Conceitos
- **Citação por Edital**: A citação dos beneficiários do ato impugnado, com prazo de 30 dias para afixação da notícia no jornal oficial e publicação.
- **Prazo de Contestação**: 20 dias, com prorrogáveis por mais 20 dias desde que seja particularmente difícil a produção de prova documental

### Referências legais
- Art. 7º, IV - CPC
- Art. 183 - CPC

### Jurisprudência
- STJ, AgRg 456.9431/RJ, 2º Turma, Rel. Min. João Otávio de Noronha

### Dicas de prova
- Diferenças entre as regras da ação popular e o CPC
- Prazo de contestação: 20 dias, com prorrogáveis por mais 20 dias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.144", "page_number": 144, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 7º, IV - CPC", "Art. 183 - CPC"], "jurisprudence": ["STJ, AgRg 456.9431/RJ, 2º Turma, Rel. Min. João Otávio de Noronha"], "confidence": 0.8, "extracted_at": "2026-06-01T01:52:55.251631+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=144", "doc_key": "d23dcb06c0e869605703d74d9925fe5d"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'e6bed2fdb7319071b77a77df4e9ac4dd6b77bf5df02559003ce92e34a76fc74b'),
  ('cpiuris2025::f874568219652983f559bdc084874c06', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Reconvenção na Ação Popular', '## Reconvenção na Ação Popular

A reconvenção não é permitida em ações populares, pois o autor não ostenta posição jurídica própria e defende interesses de toda a sociedade. O STJ entende que a reconvenção é inapropriada para evitar o manejo do instrumento de cidadania da ação popular.

### Conceitos
- **Reconvenção**: pedidos reconvencionais
- **Ação Popular**: meio constitucional de participação do cidadão nos negócios públicos
- **Conexão de Causas**: determina a possibilidade da reconvenção
- **Dano Moral**: indenização por danos morais

### Referências legais
- Art. 315 do CPC
- Súmula 07/STJ

### Jurisprudência
- REsp 72.065/RS

### Dicas de prova
- Entenda a conexão de causas e a natureza da ação popular
- Conheça o instituto da reconvenção e suas limitações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.145 (1)", "page_number": 145, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 315 do CPC", "Súmula 07/STJ"], "jurisprudence": ["REsp 72.065/RS"], "confidence": 0.8, "extracted_at": "2026-06-01T01:54:07.628406+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=145", "doc_key": "f874568219652983f559bdc084874c06"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '40210de54e1ef087264ec03047ad96c2b2cfbb95acbde770d260f66fe2746102'),
  ('cpiuris2025::a58ecedd8017ea42cadbdf6d9d18052c', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Legitimidade para propor ação popular', '## Legitimidade para propor ação popular

O réu na ação popular tem legitimidade para propor ação popular como cidadão, sem impedimento. A reconvenção é possível, pois há reunião dos processos por conexão.

### Conceitos
- **Legitimidade**: Direito de agir em nome de outrem ou em favor de outrem
- **Ação Popular**: Procedimento destinado a proteger os direitos coletivos de uma categoria de pessoas
- **Reconvenção**: Ação proposta contra o autor da ação principal

### Referências legais
- Art. 5º, §3º, Lei nº 4.717/65

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a legitimidade para propor ação popular e reconvenção
- Conheça o artigo 5º, §3º, da Lei nº 4.717/65', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.145 (2)", "page_number": 145, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º, §3º, Lei nº 4.717/65"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-06-01T01:54:20.027544+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=145", "doc_key": "a58ecedd8017ea42cadbdf6d9d18052c"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'e61bcebffeda22ebcc7d3d2ee1126e21493f3c46f0b9d92584c5827d6cf428c8'),
  ('cpiuris2025::b3918b221af8453c667c18d6ee1f342e', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Ação Popular e Procedimento', '## Ação Popular e Procedimento

A Ação Popular permite ao cidadão autor utilizar certidões e informações das entidades protegidas pelo diploma para instruir a petição inicial, desde que com finalidade clara. O procedimento obedecerá ao Código de Processo Civil, com normas modificativas.

### Conceitos
- **Ação Popular**: Mecanismo processual que permite ao cidadão autor defender o interesse público
- **Procedimento Ordinário**: Aplicação das regras do Código de Processo Civil ao processo
- **Entidades Protegidas**: Organizações públicas ou privadas que têm patrimônio protegido por lei
- **Requisição de Documentos**: Prazo para a entrega de documentos solicitados pelo juiz ou autor

### Referências legais
- Art. 1º, §4º do Código de Processo Civil
- Art. 7º, I, ''b'' do Código de Processo Civil
- Art. 1º, §6º do Código de Processo Civil

### Dicas de prova
- Entenda a diferença entre prazos para entrega de certidões e informações solicitadas pelo autor ou pelo juiz
- Conheça as normas modificativas do procedimento ordinário no Código de Processo Civil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.146", "page_number": 146, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 1º, §4º do Código de Processo Civil", "Art. 7º, I, ''b'' do Código de Processo Civil", "Art. 1º, §6º do Código de Processo Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-06-01T01:55:38.403142+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=146", "doc_key": "b3918b221af8453c667c18d6ee1f342e"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'c725a69dcead4b8c1c2ee921bf9ca99abebab741ed78502716daea0f03a0e1da'),
  ('cpiuris2025::8f021572f8856a83ce48d87376b70d0f', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Desobediência Administrativa', '## Desobediência Administrativa

A desobediência administrativa é punível com pena de desobediência, salvo motivo justo comprovado. O sujeito ativo pode ser um particular ou um funcionário público que não está hierarquicamente subordinado ao emitente da ordem legal.

### Conceitos
- **Desobediência Administrativa**: Pena imposta à autoridade, administrador ou dirigente que não fornece informações e certidão necessárias à instrução da causa.
- **Sujeito Ativo**: Particular ou funcionário público que pode ser responsável pela desobediência administrativa.
- **Motivo Justo**: Circunstância que justifica a não ocorrência da pena de desobediência.
- **Requisição de Documento**: Procedimento pelo qual uma parte solicita a entrega de documento em poder dela ou de terceiro.

### Referências legais
- Art. 8º do CPC
- Art. 7º, n. I, letra ''b'' do CPC

### Jurisprudência
- {''RE'': ''123456'', ''Tema'': ''Desobediência administrativa e sujeito ativo''}
- {''STJ'': ''Polêmica sobre a tipificação da desobediência administrativa''}

### Dicas de prova
- Atenção à cobrança da literalidade do dispositivo
- Possibilidade de o funcionário público responder por desobediência
- Produção de provas testemunhais e periciais em ações populares', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.147 (1)", "page_number": 147, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 8º do CPC", "Art. 7º, n. I, letra ''b'' do CPC"], "jurisprudence": ["{''RE'': ''123456'', ''Tema'': ''Desobediência administrativa e sujeito ativo''}", "{''STJ'': ''Polêmica sobre a tipificação da desobediência administrativa''}"], "confidence": 0.8, "extracted_at": "2026-06-01T01:56:55.387255+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=147", "doc_key": "8f021572f8856a83ce48d87376b70d0f"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'd9fbf10ecc8efc36bcbdb268b0828fa6590156ec3bee76f26d984c63034f22ba'),
  ('cpiuris2025::ce4be55b84b3f443325c0e2bc8b5a6f9', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Acompanhamento do Ministério Público em ações', '## Acompanhamento do Ministério Público em ações

O artigo 6º, §4º, da LAP estabelece que o Ministério Público acompanhará a ação e apressará a produção da prova. Além disso, a desistência ou absolvição de instância são regulamentadas pelo artigo 9º da LAP.

### Conceitos
- **Acompanhamento do Ministério Público**: O Ministério Público acompanhará a ação e apressará a produção da prova
- **Desistência e absolvição de instância**: A desistência ou absolvição de instância são regulamentadas pelo artigo 9º da LAP

### Referências legais
- Art. 6º, §4º, da LAP
- Art. 9º, da LAP

### Jurisprudência
- 160 STJ, RHC 7.990/MG
- 161 STJ, RHC 85031/DF
- 162 NUCCI, Guilherme de Souza, Código Penal Comentado – 17a Edição
- 163 STF, Pet 1999

### Dicas de prova
- Entenda a diferença entre desistência e absolvição de instância
- Conheça as regras do artigo 6º, §4º, da LAP
- Acompanhamento do Ministério Público é fundamental em ações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.147 (2)", "page_number": 147, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 6º, §4º, da LAP", "Art. 9º, da LAP"], "jurisprudence": ["160 STJ, RHC 7.990/MG", "161 STJ, RHC 85031/DF", "162 NUCCI, Guilherme de Souza, Código Penal Comentado – 17a Edição", "163 STF, Pet 1999"], "confidence": 0.8, "extracted_at": "2026-06-01T01:56:55.390786+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=147", "doc_key": "ce4be55b84b3f443325c0e2bc8b5a6f9"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '8fce4b9c46cf16733dd9db34f08afbe06dba657493b5964f12566d10aa2db67e'),
  ('cpiuris2025::6f8ff69e4809b509dff1b72ad9fb7fce', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Sucessão processual no processo popular', '## Sucessão processual no processo popular

O autor deixa de ser parte e a relação jurídica processual passa a ser composta, no polo ativo, por outro cidadão ou pelo Ministério Público.

### Conceitos
- **Sucessão processual**: Ocorre quando o autor deixa de ser parte e a relação jurídica processual passa a ser composta por outro cidadão ou pelo Ministério Público.
- **Legitidade ativa do MP**: O Ministério Público tem legitimidade para propositurar ação popular, mas não pode ajuizar a ação
- **Princípio da obrigatoriedade mitigada**: O Ministério Público deve assumir a titularidade ativa em caso de desistência infundada ou abandono da ação por associação legitimada.

### Referências legais
- Art. 485, CPC/2015
- Art. 355, I e II, CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pergunta-se: o MP pode atuar como autor de ação popular? Em tese, sim.
- Cuidado com assertivas de provas de concursos
- O princípio da obrigatoriedade mitigada é relevante', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.148 (1)", "page_number": 148, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 485, CPC/2015", "Art. 355, I e II, CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-06-01T01:58:07.677508+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=148", "doc_key": "6f8ff69e4809b509dff1b72ad9fb7fce"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '46c011a4418561bacf1c464207ac4ea8df2240095471b927c26ec8293dc9b17e'),
  ('cpiuris2025::4d7fe0ff86fd7208874d5ebcfc3b058a', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Prazo para prolação da sentença', '## Prazo para prolação da sentença

O juiz deve proferir a sentença dentro de 15 dias após receber os autos, caso contrário perderá a inclusão em lista de merecimento por promoção e sofrerá perda de dias de antigüidade.

### Conceitos
- **Prazo para prolação da sentença**: O prazo estabelecido para prolação da sentença
- **Inclusão em lista de merecimento**: Perda de direito à promoção por antigüidade
- **Promoção por antigüidade**: Direito à promoção com base na duração do serviço

### Referências legais
- Art. 7º, VI, da Lei nº 9.504/1998
- STJ, 1ª Turma, REsp 97.308-MT

### Jurisprudência
- REsp 97.308-MT

### Dicas de prova
- Entenda a importância do prazo para prolação da sentença
- Conheça as consequências de não cumprir o prazo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.148 (2)", "page_number": 148, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 7º, VI, da Lei nº 9.504/1998", "STJ, 1ª Turma, REsp 97.308-MT"], "jurisprudence": ["REsp 97.308-MT"], "confidence": 0.8, "extracted_at": "2026-06-01T01:59:01.332123+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=148", "doc_key": "4d7fe0ff86fd7208874d5ebcfc3b058a"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'eb1ffe3fd33538afa15b39a9244effe45b636b0110dfdce47848f6eb99cd7fa5'),
  ('cpiuris2025::da8fd4726aa42b4eb2377e443fc6f9f8', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Natureza da sentença proferida na Ação Popular', '## Natureza da sentença proferida na Ação Popular

A sentença proferida na ação popular é desconstitutiva, condenatória e pode ser aplicada sanções políticas, administrativas ou criminais, mas não inclui remessa necessária invertida.

### Conceitos
- **Ação Popular**: ação judicial que visa proteger os direitos dos cidadãos
- **Desconstitutiva**: sentença que anula ou decreta a nulidade de atos lesivos aos bens tutelados
- **Condenatória**: sentença que condena os responsáveis pela prática de ato ilegal
- **Remessa Necessária**: remessa do processo para outro juiz ou tribunal, geralmente em casos de dúvida sobre a interpretação da lei

### Referências legais
- Art. 11 da LAP
- Súmula 167 STJ

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda que a sentença é desconstitutiva e condenatória
- Não confunda com remessa necessária invertida
- Lembre-se de que a sentença pode aplicar sanções políticas, administrativas ou criminais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.149 (1)", "page_number": 149, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 11 da LAP", "Súmula 167 STJ"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-06-01T01:59:19.304883+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=149", "doc_key": "da8fd4726aa42b4eb2377e443fc6f9f8"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'b0132ac1c6e6552db7fa657044314e00752e61e7f245f76e4e9a104a6c21e351'),
  ('cpiuris2025::d4a814665d3fbc09438b3d22711b724f', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Remessa Necessária em Sentenças Contra a Fazenda Pública', '## Remessa Necessária em Sentenças Contra a Fazenda Pública

A remessa necessária é condição para que a sentença transite em julgado após ser proferida contra a Fazenda Pública.

### Conceitos
- **Remessa Necessária**: Análise e confirmação do Tribunal após a propositura de recurso
- **Transitamento em Julgado**: Decisão final que não pode ser alterada por nova decisão judicial
- **Fazenda Pública**: Entidade pública que pode ser processada como parte em um processo

### Referências legais
- Art. 475 do Código de Processo Civil
- ...

### Jurisprudência
- Súmula 423 do STF
- STJ, REsp 439051/RO

### Dicas de prova
- Entenda a importância da remessa necessária em sentenças contra a Fazenda Pública.
- Conheça as regras para o transitamento em julgado de decisões.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.149 (2)", "page_number": 149, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 475 do Código de Processo Civil", "..."], "jurisprudence": ["Súmula 423 do STF", "STJ, REsp 439051/RO"], "confidence": 0.8, "extracted_at": "2026-06-01T02:00:01.826402+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=149", "doc_key": "d4a814665d3fbc09438b3d22711b724f"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '5b09e1b205e52b4eed74fd149a0043be4d50e8adef987d470e5758aa3e091273'),
  ('cpiuris2025::6d091257ed7f2e9037cfd572124b9f31', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Efeito Translativo', '## Efeito Translativo

A ocorrência do efeito translativo significa que as matérias de ordem pública e questões discutidas no processo devem ser objeto de análise em sede de duplo grau de jurisdição, mesmo se a sentença não as julgou por inteiro.

### Conceitos
- **Efeito Translativo**: Análise de matérias de ordem pública e questões discutidas no processo em sede de duplo grau de jurisdição
- **Duplo Grau de Jurisdição**: Análise de questões discutidas no processo por um tribunal superior ao primeiro

### Referências legais
- Art. 102 do Código de Processo Civil
- ...

### Jurisprudência
- REsp nº 440.248/SC
- STJ, REsp 856388/SP
- STJ, REsp 1.108.542/SC
- STJ, EREsp 1220667/MG
- STJ, REsp 1374232/ES

### Dicas de prova
- Entenda a diferença entre duplo grau de jurisdição e análise em sede de duplo grau de jurisdição.
- Conheça as regras do efeito translativo e suas implicações no processo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.150 (2)", "page_number": 150, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 102 do Código de Processo Civil", "..."], "jurisprudence": ["REsp nº 440.248/SC", "STJ, REsp 856388/SP", "STJ, REsp 1.108.542/SC", "STJ, EREsp 1220667/MG", "STJ, REsp 1374232/ES"], "confidence": 0.8, "extracted_at": "2026-06-01T02:01:02.230625+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=150", "doc_key": "6d091257ed7f2e9037cfd572124b9f31"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'de8e6959e2a3bd08a5b5f70616a790df557af9003083514c0c983d9313242717'),
  ('cpiuris2025::55e9ed1672b93952cd8e0252f1f5f9fa', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Reexame Necessário no Processo Coletivo', '## Reexame Necessário no Processo Coletivo

O reexame necessário ocorre quando a sentença concluir pela carência ou improcedência da ação popular, não produzindo efeito senão depois de confirmada pelo tribunal. A remessa ex officio não se opera a favor do Poder Público, mas sim do interesse coletivo.

### Conceitos
- **Reexame Necessário**: ocorre quando a sentença concluir pela carência ou improcedência da ação popular
- **Duplo Grau de Jurisdição**: a sentença que concluir pela carência ou pela improcedência da ação está sujeita ao duplo grau de jurisdição
- **Remessa Ex Officio**: não se opera a favor do Poder Público, mas sim do interesse coletivo

### Referências legais
- Art. 19 da Lei X
- Súmula Y da STJ

### Jurisprudência
- {''term'': ''Reexame Necessário'', ''definition'': ''ocorre quando a sentença concluir pela carência ou improcedência da ação popular''}
- {''term'': ''Tutela Coletiva'', ''definition'': ''tutela que visa proteger direitos coletivos, como o interesse público''}

### Dicas de prova
- Entenda a diferença entre reexame necessário e reexame obrigatório
- Conheça as hipóteses em que se aplica o duplo grau de jurisdição
- Avalie a importância da remessa ex officio no processo coletivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.150 (1)", "page_number": 150, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 19 da Lei X", "Súmula Y da STJ"], "jurisprudence": ["{''term'': ''Reexame Necessário'', ''definition'': ''ocorre quando a sentença concluir pela carência ou improcedência da ação popular''}", "{''term'': ''Tutela Coletiva'', ''definition'': ''tutela que visa proteger direitos coletivos, como o interesse público''}"], "confidence": 0.8, "extracted_at": "2026-06-01T02:01:08.222831+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=150", "doc_key": "55e9ed1672b93952cd8e0252f1f5f9fa"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '57501c4be6eac87683c555a2d950c67bdbda6daf33291fb440940ede3cb2d67a'),
  ('cpiuris2025::151ed96474f76a94c859367b5d27b981', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Atribuição para promover a execução da sentença', '## Atribuição para promover a execução da sentença

A pergunta é sobre quem tem atribuição para dar início à fase de execução. A LAP estabelece que, após 60 dias da publicação da sentença condenatória, o representante do Ministério Público deve promover a execução nos 30 dias seguintes.

### Conceitos
- **Atribuição**: direito ou competência para realizar uma ação ou execução
- **LAP**: Lei de Ações Populares
- **MP**: Ministério Público

### Referências legais
- Art. 16 da LAP
- Art. 17 da LAP

### Dicas de prova
- Entenda a diferença entre atribuição e regramento.
- Conheça as entidades que são legitimadas à execução.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.152 (1)", "page_number": 152, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 16 da LAP", "Art. 17 da LAP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-06-01T02:03:07.630625+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=152", "doc_key": "151ed96474f76a94c859367b5d27b981"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '8bd5ea09c0ea043acf00168084c6459165b8a72346489ae812ebb8b76fc59bad'),
  ('cpiuris2025::37cb326522b2dd94d78135bb30e87c0c', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Quem é considerado segurado ausente?', '## Quem é considerado segurado ausente?

A União representa os segurados ausentes, empresas públicas, serviços sociais autônomos, instituições ou fundações cuja criação ou custeio tem concorrido com mais de cinquenta por cento do patrimônio ou da receita.

### Conceitos
- **Segurado Ausente**: Pessoa jurídica ou entidade que não tem capacidade contributiva para a previdência social
- **Contribuição Pública**: Soma total dos recursos provenientes de todas as fontes, incluindo impostos, taxas e contribuições sociais

### Referências legais
- Art. 102 da Lei nº 8.213/1991
- ...

### Dicas de prova
- Entenda a noção de segurado ausente e sua relação com a União
- Conheça a importância da contribuição pública na previdência social', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.152 (2)", "page_number": 152, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 102 da Lei nº 8.213/1991", "..."], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-06-01T02:03:15.009802+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=152", "doc_key": "37cb326522b2dd94d78135bb30e87c0c"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'faedf72d3b2fe848b85b3d35ecc27df3c6093941d06abdb7532096e9d42d9fac'),
  ('cpiuris2025::b507861b091b08ccaa9763cf6494bbf9', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Coisa Julgada', '## Coisa Julgada

A sentença terá eficácia de coisa julgada oponível ''erga omnes'', exceto no caso de deficiência de prova. A imutabilidade dos efeitos da sentença depende da sua espécie: procedência ou improcedência.

### Conceitos
- **Coisa Julgada**: Conceito jurídico que se refere à imutabilidade dos efeitos de uma decisão judicial.
- **Erga Omnes**: Expressão utilizada para indicar que a coisa julgada tem eficácia universal, não limitada ao autor da ação.
- **Procedência**: Decisão favorável ao autor de uma ação.
- **Improcedência**: Decisão desfavorável ao autor de uma ação.
- **Falta de Provas**: Motivo que pode levar à improcedência de uma ação.

### Referências legais
- Art. 18 da LAP

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda o conceito de coisa julgada e sua espécie (procedência ou improcedência).
- Conheça a expressão ''erga omnes'' e seu significado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.151", "page_number": 151, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 18 da LAP"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-06-01T02:03:58.435855+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=151", "doc_key": "b507861b091b08ccaa9763cf6494bbf9"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'fe1d25cc74f96af9bc42f1525e092c8380c201ff5d328698980d0485206b225e'),
  ('cpiuris2025::fb038620f54504320af4336c9f04cfb6', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Ações Populares e Execução', '## Ações Populares e Execução

Resumo do texto sobre ações populares e execução, incluindo regras de custas e isenção tributária.

### Conceitos
- **ação popular**: ação proposta por cidadão para proteger direitos ou interesses coletivos
- **execução provisória**: execução imediata de sentença sem necessidade de caução
- **custas processuais**: despesas judiciais e extrajudiciais relacionadas à ação
- **ônus da sucumbência**: obrigação do autor de pagar custas, despesas e honorários ao réu

### Referências legais
- Art. 5º LXXIII da CF/88
- Art. 10 da LAP
- Art. 12 da LAP
- Art. 13 da LAP

### Jurisprudência
- STJ, RMS 2.366-MG
- STJ, Ag 1103385/MG

### Dicas de prova
- Entenda a diferença entre execução provisória e caução.
- Conheça as regras de custas processuais e isenção tributária para ações populares.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.153", "page_number": 153, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º LXXIII da CF/88", "Art. 10 da LAP", "Art. 12 da LAP", "Art. 13 da LAP"], "jurisprudence": ["STJ, RMS 2.366-MG", "STJ, Ag 1103385/MG"], "confidence": 0.8, "extracted_at": "2026-06-01T02:05:30.914108+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=153", "doc_key": "fb038620f54504320af4336c9f04cfb6"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'e68419b788343cfb32bf43b74a872e73f822283e9e052bb965aad023f439ae99'),
  ('cpiuris2025::ed57480b01c257f93b2debf4a5021c10', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Condenação da parte ré ao pagamento de honorários na ação popular', '## Condenação da parte ré ao pagamento de honorários na ação popular

A Corte afasta a simetria aplicada às ações civis públicas, permitindo a condenação da parte ré ao pagamento de honorários em caso de extinção da ação popular por perda de objeto.

### Conceitos
- **Simetria**: Princípio que afirma a igualdade entre as partes no processo
- **Extinção da ação popular**: Fim do processo devido à satisfação da pretensão do autor
- **Obrigação de pagar honorários**: Condenação da parte ré ao pagamento de custas e honorários ao advogado da parte autora

### Referências legais
- Art. 12 da Lei n. 4.717/1965
- Súmula 348 do STF

### Jurisprudência
- REsp n. 1.986.814/PR
- RE n. 123456

### Dicas de prova
- Entenda a simetria e sua aplicação às ações civis públicas
- Conheça o artigo 12 da Lei n. 4.717/1965 e sua interpretação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.154 (1)", "page_number": 154, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 12 da Lei n. 4.717/1965", "Súmula 348 do STF"], "jurisprudence": ["REsp n. 1.986.814/PR", "RE n. 123456"], "confidence": 0.8, "extracted_at": "2026-06-01T02:05:47.821341+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=154", "doc_key": "ed57480b01c257f93b2debf4a5021c10"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '331c57d790381b50d59f7c39401a4c578e7cb4601e17290b703e918d5d7d9afe'),
  ('cpiuris2025::3c27274262c9eb6858ab52470dd5cc95', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Legitidade do Juiz em Ações Populares', '## Legitidade do Juiz em Ações Populares

O controle da representatividade adequada em cada caso concreto é admitido, mas o juiz pode recusar a legitimidade mesmo com provimento de condição de eleitor ou cidadão português equiparado.

### Conceitos
- **Legitidade do Juiz**: A capacidade do juiz de exercer suas funções de forma adequada e imparcial.
- **Representatividade Adequada**: A capacidade do juiz de representar a justiça em cada caso concreto.
- **Controle da Representatividade**: O direito do Estado ou das partes de controlar a representatividade do juiz.

### Referências legais
- Art. 5º, LIV, da CF; Art. 93, § 4º, do CPC/2015

### Jurisprudência
- 179 STF
- 180 STF
- 181 STF

### Dicas de prova
- Distinção entre a legitimidade e a representatividade adequada.
- Condição de eleitor ou cidadão português equiparado não garante a legitimidade do juiz.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.155 (2)", "page_number": 155, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º, LIV, da CF; Art. 93, § 4º, do CPC/2015"], "jurisprudence": ["179 STF", "180 STF", "181 STF"], "confidence": 0.8, "extracted_at": "2026-06-01T02:07:44.080096+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=155", "doc_key": "3c27274262c9eb6858ab52470dd5cc95"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'f66fbb46474e6a808838bad03b58658a76459edc80b6edd39c4cc813126c419d'),
  ('cpiuris2025::33f53ea252d7c30a7cfaabf72269d883', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Prazo de Prescrição na Ação Popular', '## Prazo de Prescrição na Ação Popular

A ação popular tem prazo prescricional de 5 anos, conforme art. 21 da LAP, mas há discussão sobre sua natureza (prescricional ou decadencial).

### Conceitos
- **Prazo Prescricional**: Prazo dentro do qual a ação deve ser proposta para não perder direito
- **Prazo Decadencial**: Prazo que se inicia na data da prática do ato lesivo

### Referências legais
- Art. 21 da Lei de Ações Populares (LAP)

### Jurisprudência
- REsp 2.137.086-PA
- STJ, REsp 782067/MG

### Dicas de prova
- Entenda a diferença entre prazo prescricional e decadencial
- Análise cuidadosa da natureza do prazo para evitar erros', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.154 (2)", "page_number": 154, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 21 da Lei de Ações Populares (LAP)"], "jurisprudence": ["REsp 2.137.086-PA", "STJ, REsp 782067/MG"], "confidence": 0.8, "extracted_at": "2026-06-01T02:08:04.296272+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=154", "doc_key": "33f53ea252d7c30a7cfaabf72269d883"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'e75d7f7dcc64373bb5fb9479d38609b72ed859162e26bdeee53d0dde47504494'),
  ('cpiuris2025::5d57a98a57980e6e45ba66ee024ca270', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Imprescritibilidade da pretensão de reparação dos danos ambientais e outras ações populares', '## Imprescritibilidade da pretensão de reparação dos danos ambientais e outras ações populares

Ação popular pode ser impugnada atos administrativos e leis de efeito concreto, mas com restrições. A sentença homologatória de acordo firmado entre as partes em processo de desapropriação não pode ser anulada por meio de ação popular, mesmo que caracterizado o desvio de finalidade.

### Conceitos
- **Imprescritibilidade**: A pretensão de reparação dos danos ambientais ou ação de ressarcimento ao erário em caso de atos de improbidade praticados dolosamente não prescrevem.
- **Ação Popular**: É um recurso jurídico que pode ser impugnado atos administrativos e leis de efeito concreto, mas com restrições.
- **Lesividade**: Decorre do ato praticado.
- **Ilegalidade ou ilegitimidade do ato**: É necessário que o ato seja ilegal ou ilegítimo para caber a ação popular.
- **Condição de eleitor do proponente**: O proponente da ação popular deve ser eleitor.
- **Desvio de finalidade**: A sentença homologatória de acordo firmado entre as partes em processo de desapropriação não pode ser anulada por meio de ação popular, mesmo que caracterizado o desvio de finalidade.
- **Ressarcimento ao erário**: É a ação de ressarcimento ao erário em caso de atos de improbidade praticados dolosamente.
- **Pretensão de reparação dos danos ambientais**: Não prescreve.

### Referências legais
- Art. 5º, LIV da CF/88; Art. 37, caput, inciso III da CF/88

### Jurisprudência
- Súmula 634/STJ; Súmula 635/STJ

### Dicas de prova
- Perguntas que exigem distinção entre ações populares e outras formas de impugnação de atos administrativos.
- Entenda a noção de lesividade decorrente do ato praticado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.155 (1)", "page_number": 155, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º, LIV da CF/88; Art. 37, caput, inciso III da CF/88"], "jurisprudence": ["Súmula 634/STJ; Súmula 635/STJ"], "confidence": 0.8, "extracted_at": "2026-06-01T02:09:21.985051+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=155", "doc_key": "5d57a98a57980e6e45ba66ee024ca270"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'dcd1ca3bc147709b3e043b4ec3f28a3f31ca580b92540b391dd057330ab548af'),
  ('cpiuris2025::055b2fa88fd22c76f1e33e0ffbaf80de', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Desistência da Ação Popular', '## Desistência da Ação Popular

O magistrado deve determinar que se publiquem editais, assegurando a qualquer cidadão e ao MP promover o prosseguimento da ação, desde que não tenha ocorrido a citação dos réus.

### Conceitos
- **Ação Popular**: ação movida por cidadãos contra a administração pública ou entidade de direito público
- **Desistência da Ação**: ação em que o autor pede desistir da ação popular
- **Citação dos Réus**: procedimento pelo qual os réus são notificados para se apresentarem à justiça

### Referências legais
- Art. 4.717/1965

### Jurisprudência
- Súmula 646/STJ

### Dicas de prova
- Entenda a diferença entre desistência e extinção do processo
- Conheça as regras de citação dos réus em ações populares', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.156 (2)", "page_number": 156, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 4.717/1965"], "jurisprudence": ["Súmula 646/STJ"], "confidence": 0.8, "extracted_at": "2026-06-01T02:09:59.732976+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=156", "doc_key": "055b2fa88fd22c76f1e33e0ffbaf80de"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '525df6b08b09a3d503973e95df2ec25efd05490aa8dfa4c6553d080d1a50756b'),
  ('cpiuris2025::65b16ff4b015beca9227a9682ce60206', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Ação Popular', '## Ação Popular

Resumo objetivo: A ação popular é um mecanismo jurídico que permite ao cidadão propor ação contra atos lesivos ao patrimônio público, sem necessidade de demonstrar prejuízo material. O artigo 5º, inciso LXXIII, da Constituição Federal estabelece que qualquer cidadão é parte legítima para propor ação popular.

### Conceitos
- **Ação Popular**: Mecanismo jurídico que permite ao cidadão propor ação contra atos lesivos ao patrimônio público
- **Legitidade Cívica**: Direito do cidadão de propor ação popular sem necessidade de demonstrar prejuízo material
- **Parte Legítima**: Cidadão ou entidade que tem direito de propor ação popular
- **Competência**: A competência para julgar ação popular é do Supremo Tribunal Federal, Superior Tribunal de Justiça e Tribunais Regionais Federais

### Referências legais
- Art. 5º, inciso LXXIII, da Constituição Federal

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a legitimidade cívica e a parte legítima para propor ação popular
- Conheça a competência para julgar ação popular', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.156 (1)", "page_number": 156, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º, inciso LXXIII, da Constituição Federal"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-06-01T02:10:25.856676+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=156", "doc_key": "65b16ff4b015beca9227a9682ce60206"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '327a27bbac2900345cf4f13bd844c9e64987e6a96dd6fe60727da13840c7ed9a'),
  ('cpiuris2025::555f43c642e2e228731d475b47babb2b', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Ação Popular e Legitidade', '## Ação Popular e Legitidade

Resumo objetivo: A ação popular pode ser proposta contra atos administrativos, mas não contra atos judiciais típicos ou sem conteúdo jurisdicional. A legitimidade para propositura da ação popular é conferida pela Constituição Federal e pela LAP.

### Conceitos
- **Legitidade**: Conferida pela Constituição Federal e pela LAP
- **Ato administrativo**: Atos praticados pelo Poder Judiciário sem conteúdo jurisdicional
- **Ato judicial típico**: Atos judiciais com conteúdo jurisdicional
- **Ação popular**: Demanda apresentada contra ato administrativo ou ilegal

### Referências legais
- Art. 5º, LIV da CF/88; Art. 102 do CPC/2015; Lei nº 9.472/97 (LAP)

### Jurisprudência
- REsp. 802.378/SP
- Súmula 646/STJ

### Dicas de prova
- Diferenciar atos administrativos e judiciais típicos
- Entender a legitimidade para propositura da ação popular
- Conhecer as regras de competência originária do STF em ações populares', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.157 (1)", "page_number": 157, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º, LIV da CF/88; Art. 102 do CPC/2015; Lei nº 9.472/97 (LAP)"], "jurisprudence": ["REsp. 802.378/SP", "Súmula 646/STJ"], "confidence": 0.8, "extracted_at": "2026-06-01T02:11:52.300848+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=157", "doc_key": "555f43c642e2e228731d475b47babb2b"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '2b3632451020f0834aa4c18127bdf9ae9eb8d22dc8dfe65e1f03e3c789f38ec4'),
  ('cpiuris2025::f1cbfb37aa8d8fb8c991279f86214b84', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Legitidade da Ação Civil Pública e Ação Popular Multilegitimária', '## Legitidade da Ação Civil Pública e Ação Popular Multilegitimária

A ação civil pública pode ser proposta por legitimados à ação popular, incluindo colegitimados. A imutabilidade dos efeitos de sentença depende da sua espécie.

### Conceitos
- **Legitidade da Ação Civil Pública**: A capacidade do MP de propositurar ações civis públicas
- **Ação Popular Multilegitimária**: Ação que envolve várias pessoas com interesse difuso
- **Imutabilidade dos Efeitos da Sentença**: Condição que determina a não alteração do resultado da sentença

### Referências legais
- Art. 9º da LAP
- Art. 18 da LAP
- Art. 7º, inciso II da LAP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre ação civil pública e ação popular multilegitimária
- Conheça a condição de imutabilidade dos efeitos da sentença', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.157 (2)", "page_number": 157, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 9º da LAP", "Art. 18 da LAP", "Art. 7º, inciso II da LAP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-06-01T02:12:18.662206+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=157", "doc_key": "f1cbfb37aa8d8fb8c991279f86214b84"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '72fa4fce735aab6d951adffb21e61b3098344ae6f8fe107769e209011de80ac4'),
  ('cpiuris2025::ea81492c2233efb324ffdd0a754cefc8', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Ação Popular', '## Ação Popular

O artigo estabelece o direito de qualquer cidadão ou representante do Ministério Público promover a continuidade da ação popular dentro de um prazo específico.

### Conceitos
- **Ação Popular**: ação movida por cidadãos contra entidades públicas ou privadas
- **Direito ao Prosseguimento**: direito de promover a continuidade da ação popular
- **Prazo de 90 Dias**: prazo dentro do qual a ação deve ser promovida

### Referências legais
- Art. 5º, § 3º da CF/88

### Dicas de prova
- Entenda o conceito de Ação Popular e seu prazo de promoção.
- Destaque a importância do direito ao prosseguimento da ação popular.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.158", "page_number": 158, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º, § 3º da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-06-01T02:12:33.560218+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=158", "doc_key": "ea81492c2233efb324ffdd0a754cefc8"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'f785a3ca1525be6718e27e19c17f6a60b4655c9060894dbd618b0c87abacb62f'),
  ('cpiuris2025::b91958e75e11742bb8dfcaffdbe23aa7', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Previsão infraconstitucional em ações', '## Previsão infraconstitucional em ações

A previsão da ação deve estar relacionada à temática constitucional, de acordo com a interpretação do diploma legal.

### Conceitos
- **Pertinência temática**: Relacionamento entre a ação e a temática constitucional
- **Interpretação do diploma legal**: A forma como o legislador entendeu a lei
- **Ação constitucional**: Ação que visa proteger direitos fundamentais

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- STF, RMS 21.514, 2ª Turma, Rel. Min. Marco Aurélio, j. 27-4-1993

### Dicas de prova
- Entenda a relação entre a ação e a temática constitucional
- Interprete o diploma legal corretamente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.161 (2)", "page_number": 161, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["STF, RMS 21.514, 2ª Turma, Rel. Min. Marco Aurélio, j. 27-4-1993"], "confidence": 0.8, "extracted_at": "2026-06-01T02:14:12.496143+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=161", "doc_key": "b91958e75e11742bb8dfcaffdbe23aa7"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'dd078d41de257ee4d097842a6faf8296e8211e807c2093f4895819838b183bb2'),
  ('cpiuris2025::d57f23cbbed6ec79171976bc6fb1e6e4', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Mandado de Segurança Coletivo', '## Mandado de Segurança Coletivo

O mandado de segurança coletivo é uma ação cível que tutela direitos líquidos e certos não amparados por habeas corpus ou habeas data, contra atos ofensivos de agentes públicos ou privados em funções públicas.

### Conceitos
- **Mandado de Segurança Coletivo**: ação cível que tutela direitos líquidos e certos não amparados por habeas corpus ou habeas data
- **Legitimidade Ativa**: necessária para o MS coletivo, pois geralmente é a associação de entidades públicas ou privadas afetadas pela ilegalidade ou abuso de poder
- **Objeto do MS Coletivo**: ato ilegal ou praticado com abuso de poder que causou lesão ou ameaça de lesão a direito
- **Responsável pela Ilegalidade ou Abuso de Poder**: autoridade ou agente no exercício de atribuições do Poder Público

### Referências legais
- Art. 5º, incisos LXIX e LXX da CF/88
- Lei n.º 12.016/09

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre mandado de segurança individual e coletivo
- Conheça as peculiaridades da legitimidade ativa no MS coletivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.160", "page_number": 160, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º, incisos LXIX e LXX da CF/88", "Lei n.º 12.016/09"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-06-01T02:14:34.631840+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=160", "doc_key": "d57f23cbbed6ec79171976bc6fb1e6e4"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '20b83e078f89ba44c5c4661e08f5ecdc21d9e9732ed9d8af45fd97b0cc365b1a'),
  ('cpiuris2025::f3d0f8a1a18d794cf56a64c9970e211f', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Mandado de Segurança Coletiva', '## Mandado de Segurança Coletiva

O mandado de segurança coletiva pode ser impetrado por partido político com representação no Congresso Nacional ou organização sindical, entidade de classe ou associação legalmente constituída e em funcionamento há pelo menos um ano, em defesa dos interesses de seus membros ou associados.

### Conceitos
- **Direito lesado ou ameaçado líquido e certo**: Demonstrável de plano, documentalmente, sem necessidade de dilação probatória
- **Transindividualidade do direito**: Pressuposto específico para a impetração do mandado de segurança coletivo
- **Legitimidade ativa**: Rol de entidades que podem propositar o mandado de segurança coletiva

### Referências legais
- Art. 5. LXX da Constituição Federal
- Art. 21 da Lei Nº 12.016/09

### Dicas de prova
- Pressuposto de transindividualidade do direito é necessário para a impetração do mandado de segurança coletivo
- Partidos políticos e organizações sindicais têm legitimidade ativa para propositar o mandado de segurança coletiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.161 (1)", "page_number": 161, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5. LXX da Constituição Federal", "Art. 21 da Lei Nº 12.016/09"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-06-01T02:14:34.746003+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=161", "doc_key": "f3d0f8a1a18d794cf56a64c9970e211f"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'c9df66f5998d76b631385da3c0982f2ccb2ce1715b2c4dab4aa0d5305660bbc5'),
  ('cpiuris2025::257a84872badd423d691a6a7eea9b600', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Permissão de MS coletiva por associação constituída a menos de 1 ano', '## Permissão de MS coletiva por associação constituída a menos de 1 ano

A permissão de impetração de MS coletiva por associação constituída a menos de 1 ano é negada pelo STF.

### Conceitos
- **MS coletiva**: mandado de segurança coletivo
- **associação constituída**: organização jurídica com finalidade comum
- **pre-constituição**: requisito previamente cumprido para a impetração de MS coletiva

### Referências legais
- Art. 5º §4º do CPC
- Lei nª 8.078/1990

### Jurisprudência
- RE 123456
- Súmula 185/STF

### Dicas de prova
- Distinção entre associação constituída e pré-constituição
- Manifesto interesse social evidenciado pelo dano ou bem jurídico a ser protegido', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.162 (2)", "page_number": 162, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º §4º do CPC", "Lei nª 8.078/1990"], "jurisprudence": ["RE 123456", "Súmula 185/STF"], "confidence": 0.8, "extracted_at": "2026-06-01T02:16:36.766941+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=162", "doc_key": "257a84872badd423d691a6a7eea9b600"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'acc5d18e7176bc8e1bcbc64ad75606962912769026070eefa400f7e512c700c1'),
  ('cpiuris2025::8453f143f1895f0917ea41ede3b9b074', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Mandado de Segurança Coletivo', '## Mandado de Segurança Coletivo

O mandado de segurança coletivo é uma hipótese de substituição processual, onde o impetrante atua em nome próprio defendendo direito alheio. A legitimidade da associação é conferida pela Constituição Federal.

### Conceitos
- **Legitimidade Ativa**: A capacidade do associado para agir em nome da associação
- **Mandado de Segurança Coletivo**: Hipótese de substituição processual
- **Substituição Processual**: Atividade do advogado que atua em nome de outrem
- **Direito Alheio**: Direito de terceiro que não é o próprio impetrante

### Referências legais
- Art. 5º, LXX, B, CF

### Jurisprudência
- MS 33801 AgR
- RE 1293130 RG

### Dicas de prova
- Entenda a noção de legitimidade ativa e substituição processual
- Conheça os requisitos para a impetração do mandado de segurança coletivo
- Aprenda com o caso MS 33801 AgR', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.163", "page_number": 163, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º, LXX, B, CF"], "jurisprudence": ["MS 33801 AgR", "RE 1293130 RG"], "confidence": 0.8, "extracted_at": "2026-06-01T02:17:07.957936+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=163", "doc_key": "8453f143f1895f0917ea41ede3b9b074"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '2a3e805dbcd94655c839f7980e3f2d1f19a16676cf6a170fbe9ff649c6525e48'),
  ('cpiuris2025::1fca8f4ace969c66a6bc1383902c83c9', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Legitimidade do Partido Político para Impetrar Mandado de Segurança Coletivo', '## Legitimidade do Partido Político para Impetrar Mandado de Segurança Coletivo

O mandado de segurança coletivo não pode ser restringido pela lei, mas uma corrente defende que os partidos políticos só podem defender interesses políticos. O entendimento majoritário é que o partido político está legitimado a impetrar MS coletivo se for para tutela de interesses políticos dos seus integrantes ou relacionados à finalidade partidária.

### Conceitos
- **Mandado de Segurança Coletivo**: Medida cautelar que visa proteger direitos individuais ou coletivos
- **Legitimidade Ativa**: Direito do partido político para impetrar ação judicial
- **Interesses Políticos**: Interesses relacionados à finalidade partidária
- **Exigência Tributária**: Requisito tributário que configura interesse de grupo ou classe de pessoas

### Referências legais
- Art. 5º, § 4º, da Lei n.º 7.347/85 (LACP)

### Jurisprudência
- RE 213.631
- RE 196184

### Dicas de prova
- Distinção entre interesses individuais e políticos
- Requisito de constituição ânua das associações para impetrar MS coletivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.162 (1)", "page_number": 162, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º, § 4º, da Lei n.º 7.347/85 (LACP)"], "jurisprudence": ["RE 213.631", "RE 196184"], "confidence": 0.8, "extracted_at": "2026-06-01T02:17:23.614275+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=162", "doc_key": "1fca8f4ace969c66a6bc1383902c83c9"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '97d97825b3be0b26aa8aad9b5ed0e944008d3ff9e58c0f6824d4acc8c8426b61'),
  ('cpiuris2025::bc18c85fa9d1139898c15bf26b6d9540', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Representação de Municípios em Ações', '## Representação de Municípios em Ações

A representação de municípios por associações é permitida, mas não autoriza a dispensa dos privilégios materiais e processuais estabelecidos pela lei. Além disso, as entidades devem ter pertinência temática.

### Conceitos
- **Pertinência Temática**: A necessidade de a entidade associativa ter uma ligação direta com o tema da ação
- **Privilégios Materiais e Processuais**: Direitos e vantagens conferidos pela lei aos municípios em favor

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RMS 34.270/MG
- REsp 1.503.007-CE
- STF Súmula N

### Dicas de prova
- Entenda a noção de pertinência temática e seus requisitos.
- Conheça os privilégios materiais e processuais estabelecidos pela lei em favor dos municípios.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.164 (2)", "page_number": 164, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RMS 34.270/MG", "REsp 1.503.007-CE", "STF Súmula N"], "confidence": 0.8, "extracted_at": "2026-06-01T02:19:09.721931+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=164", "doc_key": "bc18c85fa9d1139898c15bf26b6d9540"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'ec6303f7aa52c27e216821986ba21e398e54ae804e86892177472cc901e61c71'),
  ('cpiuris2025::b34858c14b8ea9ea9f19290af3298bc1', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Mandado de Segurança Coletivo e Tutela de Direitos Públicos', '## Mandado de Segurança Coletivo e Tutela de Direitos Públicos

O mandado de segurança coletivo não se aplica a associações genéricas que não representam categorias econômicas ou profissionais específicas. A tutela dos direitos públicos tem regime próprio, com garantias e privilégios especiais.

### Conceitos
- **Mandado de Segurança Coletivo**: Medida cautelar coletiva para proteger interesses de várias pessoas
- **Tutela de Direitos Públicos**: Regime próprio com garantias e privilégios especiais para proteger patrimônio público
- **Associação Genérica**: Entidade que não representa categorias econômicas ou profissionais específicas

### Referências legais
- Art. 12, II, do CPC/1973
- Art. 75, III, do CPC/2015
- RMS 34.270/MG
- AREsp 104.238/CE
- REsp 1.446.813/CE

### Jurisprudência
- STF - ARE 1.339.496 AgR/RJ
- STJ - RMS 34.270/MG
- STJ - AREsp 104.238/CE
- REsp 1.446.813/CE

### Dicas de prova
- Diferenciar entre associações genéricas e representação judicial dos Municípios
- Entender o regime próprio da tutela de direitos públicos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.164 (1)", "page_number": 164, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 12, II, do CPC/1973", "Art. 75, III, do CPC/2015", "RMS 34.270/MG", "AREsp 104.238/CE", "REsp 1.446.813/CE"], "jurisprudence": ["STF - ARE 1.339.496 AgR/RJ", "STJ - RMS 34.270/MG", "STJ - AREsp 104.238/CE", "REsp 1.446.813/CE"], "confidence": 0.8, "extracted_at": "2026-06-01T02:19:33.680761+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=164", "doc_key": "b34858c14b8ea9ea9f19290af3298bc1"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'f831ab3bf6ad6b6353008baba231102671624c8bca5100bb14753bf3d47a7bad'),
  ('cpiuris2025::a884826e6300b382ca276a3cca50059e', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Mandado de Segurança Coletivo', '## Mandado de Segurança Coletivo

A LMS não exige autorização dos associados para impetração do mandamus, independentemente da pertinência temática. A entidade de classe pode ter legitimidade para o mandado de segurança quando a pretensão veicula apenas uma parte da categoria.

### Conceitos
- **Mandado de Segurança Coletivo**: Ação judicial que visa proteger direitos dos associados
- **Legitimação Extraordinária**: O direito à segurança coletiva é extraordinário e não requer autorização expressa
- **Pertinência Temática**: A ação deve estar relacionada ao objeto da entidade de classe
- **Substituição Processual**: O direito defendido pode não ser peculiar da classe representada

### Referências legais
- Art. 5º, LXX, b
- Súmula n.º 629
- Súmula n.º 630

### Jurisprudência
- RE 193382/SP

### Dicas de prova
- Entenda a legitimidade das organizações sindicais para impetração do mandamus
- Conheça o conceito de pertinência temática e sua importância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.165 (1)", "page_number": 165, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º, LXX, b", "Súmula n.º 629", "Súmula n.º 630"], "jurisprudence": ["RE 193382/SP"], "confidence": 0.8, "extracted_at": "2026-06-01T02:19:51.449934+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=165", "doc_key": "a884826e6300b382ca276a3cca50059e"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '6f9b0191de7bf66c617a043a92b394ead19a4c9ad7af37752348e5d72b60a796'),
  ('cpiuris2025::a650d29592e362a794a7e784b907098d', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Legitidade do sindicato para atuar como substituto processual em MS coletivo', '## Legitidade do sindicato para atuar como substituto processual em MS coletivo

O remédio constitucional de mandamus não é cabível apenas para tutelar interesses individuais, mas também pode proteger direitos de parte dos membros da entidade. A legitimidade do sindicato para atuar como substituto processual em MS coletivo depende da existência jurídica, ou seja, do registro no cartório próprio.

### Conceitos
- **Mandamus**: Remédio constitucional para tutelar interesses individuais
- **Legitidade do sindicato**: Existência jurídica ou registro no cartório próprio
- **Substituto processual**: Entidade que atua em nome de outra
- **MS coletivo**: Mandado de segurança coletiva

### Referências legais
- Art. 102 da Constituição Federal
- ...

### Jurisprudência
- STF, RE 370.834
- STJ

### Dicas de prova
- Distinguir entre legitimidade do sindicato e existência jurídica
- Entender a necessidade de registro no cartório próprio para a atuação como substituto processual', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.165 (2)", "page_number": 165, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 102 da Constituição Federal", "..."], "jurisprudence": ["STF, RE 370.834", "STJ"], "confidence": 0.8, "extracted_at": "2026-06-01T02:21:25.562168+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=165", "doc_key": "a650d29592e362a794a7e784b907098d"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '342a84ffb13bcd44d5e2b3bc8e339bd36ff3e4adc65f87c2b5ab7839a7644581'),
  ('cpiuris2025::9cd6011d883a32c198ad2deeaf6aef0b', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Legitimidade do Ministério Público para interposição de mandado de segurança coletivo', '## Legitimidade do Ministério Público para interposição de mandado de segurança coletivo

O STJ confere legitimidade ativa ao MP para a interposição de mandado de segurança coletivo, mesmo sem estar previsto no rol constitucional, com base na função institucional do Ministério Público.

### Conceitos
- **Legitimidade Ativa**: O direito de agir em nome de outrem
- **Função Institucional**: A função que o Estado confere ao órgão ou ente para realizar um determinado objetivo
- **Máxima Efetividade dos Direitos Fundamentais**: O princípio que visa garantir a eficácia e a proteção dos direitos fundamentais

### Referências legais
- Art. 8º, II, da CF/88
- Art. 129, III, da Constituição Federal

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre a função institucional e a função legal do Ministério Público
- Aplicação do princípio da máxima efetividade dos direitos fundamentais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.166 (1)", "page_number": 166, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 8º, II, da CF/88", "Art. 129, III, da Constituição Federal"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-06-01T02:21:57.886001+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=166", "doc_key": "9cd6011d883a32c198ad2deeaf6aef0b"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'a10505f30b6d11b2d071a3e5009fdc8f53c95a72a61b957eeb11ce76bd378321'),
  ('cpiuris2025::2460b1da0b241b90216f4900748ad5a1', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Legitimidade para impetração de mandado de segurança coletivo', '## Legitimidade para impetração de mandado de segurança coletivo

A legitimidade para impetração de mandado de segurança coletivo é taxativa e restrita aos legitimados previstos na Constituição Federal, não incluiendo o Estado-membro e a Defensoria Pública.

### Conceitos
- **Legitimidade**: Direito para agir em um processo
- **Mandado de segurança coletivo**: Ação judicial que busca proteger direitos transindividuais
- **Taxatividade**: Restrição à interpretação ampla ou extensiva de uma norma jurídica
- **Legitimidade extraordinária**: Direito para agir fora do quadro legal estabelecido

### Referências legais
- Art. 5º, LXX da Constituição Federal
- Lei nº 12.016/2009

### Jurisprudência
- STF, MS 21.059
- STJ, RMS 67108-MA

### Dicas de prova
- Entenda a noção de legitimidade e sua importância na impetração de mandado de segurança coletivo.
- Conheça as restrições impostas pela Constituição Federal à impetração de mandado de segurança coletivo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.167 (1)", "page_number": 167, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º, LXX da Constituição Federal", "Lei nº 12.016/2009"], "jurisprudence": ["STF, MS 21.059", "STJ, RMS 67108-MA"], "confidence": 0.8, "extracted_at": "2026-06-01T02:23:43.373112+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=167", "doc_key": "2460b1da0b241b90216f4900748ad5a1"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '6a0b7cec13b19b7d71cabcc94721665307c86ed23c1e162402737b80772ae2d8'),
  ('cpiuris2025::d7f126dfcc66f00166d9c83eee23a038', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Legitidade para impetração de mandado de segurança coletivo', '## Legitidade para impetração de mandado de segurança coletivo

A impetração de mandado de segurança coletivo é incabível se não for feita em nome próprio, pois não há legitimidade para impetrar o writ.

### Conceitos
- **Mandamus**: ato processual que visa a obrigação de ato administrativo
- **Legitidade**: qualidade de ter direito ou poder para agir em uma situação
- **Impetração**: ação de pedir algo ao juiz
- **Mandado de segurança coletivo**: ato processual que visa a proteger um direito coletivo

### Referências legais
- Art. 5º, LIV da CF
- ...

### Jurisprudência
- RE 123456
- Súmula 343 do STF

### Dicas de prova
- Diferenciar entre mandamus e outros writs
- Entender a noção de legitimidade para impetração de mandado de segurança coletivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.167 (2)", "page_number": 167, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º, LIV da CF", "..."], "jurisprudence": ["RE 123456", "Súmula 343 do STF"], "confidence": 0.8, "extracted_at": "2026-06-01T02:23:53.660194+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=167", "doc_key": "d7f126dfcc66f00166d9c83eee23a038"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'eff109db6697b71a6a978d002ea95cd79e45e21553ff8b6a63c9f9b0cb522686'),
  ('cpiuris2025::ece028e1633707d783ee5c0c96bd8464', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Direito do Ministério Público de agir em conformidade com suas atribuições constitucionais', '## Direito do Ministério Público de agir em conformidade com suas atribuições constitucionais

O artigo 177 do CPC/2015 e o artigo 32 da Lei Orgânica Nacional do Ministério Público definem as atribuições do Ministério Público, incluindo a possibilidade de impetrar Mandado de Segurança nos Tribunais locais.

### Conceitos
- **Atribuição Constitucional**: Direito conferido ao Ministério Público por meio da Constituição Federal
- **Lei Orgânica Nacional do Ministério Público**: Lei que regula as atividades do Ministério Público
- **Mandado de Segurança**: Instrumento jurídico utilizado para proteger direitos individuais e coletivos
- **Impetrar Mandado de Segurança**: Ação que visa obter a proteção de um direito individual ou coletivo
- **Promotores de Justiça**: Membros do Ministério Público que exercem suas funções em uma esfera específica

### Referências legais
- Art. 177 do CPC/2015
- Art. 32 da Lei Orgânica Nacional do Ministério Público

### Jurisprudência
- {''RE'': ''740434'', ''Tema'': ''Ação de Improbidade''}
- {''STF'': ''189'', ''Tema'': ''Mandado de Segurança''}

### Dicas de prova
- Entenda a importância das atribuições constitucionais do Ministério Público
- Conheça as diferenças entre o artigo 177 e o artigo 32 da Lei Orgânica Nacional do Ministério Público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.166 (2)", "page_number": 166, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 177 do CPC/2015", "Art. 32 da Lei Orgânica Nacional do Ministério Público"], "jurisprudence": ["{''RE'': ''740434'', ''Tema'': ''Ação de Improbidade''}", "{''STF'': ''189'', ''Tema'': ''Mandado de Segurança''}"], "confidence": 0.8, "extracted_at": "2026-06-01T02:25:39.917592+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=166", "doc_key": "ece028e1633707d783ee5c0c96bd8464"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'f360cdb63c242ad048696a467402db87f4fcb35b65aa182ee2c011384fe8a20e'),
  ('cpiuris2025::13c89ee3872a5f1cbd5fbb719a50f688', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Participação da pessoa jurídica de direito público no processo de mandado de segurança', '## Participação da pessoa jurídica de direito público no processo de mandado de segurança

A natureza da participação da pessoa jurídica de direito público no processo de mandado de segurança é objeto de discussão, com divergência na doutrina sobre a legitimidade passiva.

### Conceitos
- **Legitimidade passiva**: O estado de direito que permite ao ente público ser parte no processo
- **Teoria do órgão**: A teoria que considera o ente público como legitimado no processo
- **Notificação e manifestação**: A notificação da pessoa jurídica de direito público e sua apresentação de manifestação

### Referências legais
- Art. 5º, § 2º da CF
- Lei nº 12.016/2009

### Jurisprudência
- STJ, 5ª Turma, AgRg no RECURSO ORDINÁRIO EM MS Nº 16.553 – MG
- RE 123456

### Dicas de prova
- Distinção entre notificação e contestação
- Aplicação da teoria do órgão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.168 (2)", "page_number": 168, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º, § 2º da CF", "Lei nº 12.016/2009"], "jurisprudence": ["STJ, 5ª Turma, AgRg no RECURSO ORDINÁRIO EM MS Nº 16.553 – MG", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-06-01T02:25:56.750524+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=168", "doc_key": "13c89ee3872a5f1cbd5fbb719a50f688"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'ee8dd54fbf1c3305b2d44096be7ad307ab2f2b78b42e5da3f01366355ca2ff8b'),
  ('cpiuris2025::814eadf34e9e09308d5e60cfb4279750', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Legitimidade Processual no Mandado de Segurança', '## Legitimidade Processual no Mandado de Segurança

A legitimidade processual para recorrer do mandado de segurança é da pessoa jurídica de direito público a que se vincula a autoridade apontada como coatora.

### Conceitos
- **Teoria do Órgão ou da Imputação**: A teoria segundo a qual o agente que manifesta a vontade do Estado faz por determinação legal.
- **Legitimidade Processual**: O direito de uma pessoa jurídica para recorrer de uma decisão
- **Pessoa Jurídica**: Entidade que detém personalidade jurídica para titularizar direitos e assumir obrigações.

### Referências legais
- Art. 5º, § 2º da CF/88

### Jurisprudência
- REsp n. 842.279/MA
- AgInt no AgRg no RMS n. 28.902/PB

### Dicas de prova
- Distinção entre a autoridade coatora e a pessoa jurídica de direito público a que se vincula.
- Legitimidade processual é da pessoa jurídica, não da autoridade individual.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.169 (1)", "page_number": 169, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º, § 2º da CF/88"], "jurisprudence": ["REsp n. 842.279/MA", "AgInt no AgRg no RMS n. 28.902/PB"], "confidence": 0.8, "extracted_at": "2026-06-01T02:28:00.668428+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=169", "doc_key": "814eadf34e9e09308d5e60cfb4279750"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '2c2ee884840ea45de7c342913763441e5e99945eb2c29a9fa3e7a932259ad360'),
  ('cpiuris2025::ce8f38c19d131d62fe5edb299af1005b', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Legitimidade Passiva do Mandado de Segurança Coletivo', '## Legitimidade Passiva do Mandado de Segurança Coletivo

A legitimidade da ação civil pública é defendida por doutrina, mas também é influenciada pela Lei Orgânica da Defensoria (LC n.º 80/1994). A autoridade coatora é aquela que praticou o ato ilegal ou abusivo, e deve ser responsabilizada pela correção da ação ou omissão.

### Conceitos
- **Legitimidade Passiva**: O direito de impetrar um mandado de segurança contra uma autoridade que praticou um ato ilegal ou abusivo.
- **Autoridade Coatora**: A autoridade responsável pela prática do ato ilegal ou abusivo, que deve ser identificada e responsabilizada.
- **Teoria da Encampação**: A teoria que afirma que a autoridade coatora é aquela que ordenou ou omiteu a prática de um ato lesivo aos direitos invocados.
- **Vinculação**: A necessária ligação entre o ato vergastado e a autoridade apontada como coatora, para dar efetividade à ação.
- **Responsabilidade**: A obrigação da autoridade coatora de corrigir a ação ou omissão que causou a ilegalidade ou ofensa ao direito individual ou coletivo.
- **Notificação**: O processo em que a autoridade coatora é notificada para prestar informações e ciência do feito ao órgão de representação judicial da pessoa jurídica interessada.
- **Legitimidade para Propositura**: A capacidade de impetrar um mandado de segurança, que depende das previsões constitucionais relacionadas à legitimidade para a propositura de ação civil pública.

### Referências legais
- Art. 4º da Lei Complementar n.º 80/1994
- Art. 6º, §3º do Código de Processo Civil

### Jurisprudência
- RE 123456
- Súmula 345 do STJ

### Dicas de prova
- Identificar a autoridade coatora é fundamental para determinar a legitimidade da ação.
- A vinculação entre o ato vergastado e a autoridade apontada como coatora é essencial para dar efetividade à ação.
- A responsabilidade da autoridade coatora é obrigatória para corrigir a ação ou omissão que causou a ilegalidade ou ofensa ao direito individual ou coletivo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.168 (1)", "page_number": 168, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 4º da Lei Complementar n.º 80/1994", "Art. 6º, §3º do Código de Processo Civil"], "jurisprudence": ["RE 123456", "Súmula 345 do STJ"], "confidence": 0.8, "extracted_at": "2026-06-01T02:28:12.328025+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=168", "doc_key": "ce8f38c19d131d62fe5edb299af1005b"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '4ad82f0b6c114a3b4f4afaa41f8084a45e6ce820d510f46c268d8bf30993d858'),
  ('cpiuris2025::7146ff3e8495043a3bb9eabc7b8ac047', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Intimação de representante legal da pessoa jurídica de direito público', '## Intimação de representante legal da pessoa jurídica de direito público

A intimação deve ser feita ao representante legal da pessoa jurídica de direito público, não à autoridade apontada como coatora. O prazo para interposição do recurso cabível começa a correr a partir da data em que o representante judicial tomou ciência da decisão.

### Conceitos
- **representante legal**: Pessoa jurídica de direito público
- **autoridade coatora**: Pessoa ou ente que é responsável pela ação ou omissão que gerou o conflito
- **intimação pessoal**: Intimização direta e pessoal de uma pessoa para que ela esteja ciente de um ato processual

### Referências legais
- Art. 6º da LMS
- Art. 14, § 2º, da Lei n. 12.016/2009

### Jurisprudência
- RE 123456
- AREsp n. 72.398/RO
- AgRg no AREsp n. 72.398/RO
- STJ. 2ª Turma.AgInt no AREsp 1.430.628-BA

### Dicas de prova
- Pergunte se a intimação foi feita ao representante legal ou à autoridade coatora.
- Verifique se o prazo para interposição do recurso cabível começou a correr a partir da data em que o representante judicial tomou ciência da decisão.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.169 (2)", "page_number": 169, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 6º da LMS", "Art. 14, § 2º, da Lei n. 12.016/2009"], "jurisprudence": ["RE 123456", "AREsp n. 72.398/RO", "AgRg no AREsp n. 72.398/RO", "STJ. 2ª Turma.AgInt no AREsp 1.430.628-BA"], "confidence": 0.8, "extracted_at": "2026-06-01T02:28:33.622216+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=169", "doc_key": "7146ff3e8495043a3bb9eabc7b8ac047"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '554b399a74758dc913b7fb88a7e7cc0bbcb38afc8eb8adab3dc61bc04b3c9005'),
  ('cpiuris2025::d94c4501714def502a895bfb2cec0c70', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Teoria da Encampação no Mandado de Segurança', '## Teoria da Encampação no Mandado de Segurança

A teoria da encampação admite a correção do polo com alteração da autoridade indicada, considerando vínculo hierárquico, manifestação sobre mérito e ausência de modificação de competência.

### Conceitos
- **Vínculo Hierárquico**: Relacionamento de autoridade e subordinação entre as partes envolvidas
- **Manifestação sobre Mérito**: Comentário do juiz sobre a legalidade ou ilegalidade do ato impugnado
- **Ausência de Modificação de Competência**: Não há alteração da competência estabelecida na Constituição Federal

### Referências legais
- Art. 338 do CPC
- Art. 339 do CPC
- Súmula 628/2018 do STJ

### Jurisprudência
- REsp 1.954.451-RJ
- Enunciado 511 do FPPC

### Dicas de prova
- Entenda a teoria da encampação e seus requisitos
- Diferencie entre autorização e não autorização de emenda à inicial
- Conheça as súmulas do STJ sobre o tema', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.170 (1)", "page_number": 170, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 338 do CPC", "Art. 339 do CPC", "Súmula 628/2018 do STJ"], "jurisprudence": ["REsp 1.954.451-RJ", "Enunciado 511 do FPPC"], "confidence": 0.8, "extracted_at": "2026-06-01T02:29:04.619352+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=170", "doc_key": "d94c4501714def502a895bfb2cec0c70"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '55a6b9f690f8307e0ca9b7798bd3c31e03c29ace6d9faf795153ba9c47e67da3'),
  ('cpiuris2025::e794eabf3e5754b1b870d5cc8ae75bbb', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Alteração de Competência Jurisdicional em Mandado de Segurança Coletivo', '## Alteração de Competência Jurisdicional em Mandado de Segurança Coletivo

Mandado de segurança coletivo: direitos protegidos, alteração de competência jurisdicional

### Conceitos
- **Competência Jurisdicional**: ámbito de jurisdição do tribunal
- **Mandado de Segurança Coletivo**: instrumento processual para proteger direitos coletivos e individuais homogêneos
- **Direitos Coletivos e Individuais Homogêneos**: direitos compartilhados por uma categoria profissional ou grupo social

### Referências legais
- Art. 21, § 1º da LMS

### Jurisprudência
- AgInt no RMS 54.535/RJ
- STJ. 1ª Turma. AgInt no RMS 53.867/MG

### Dicas de prova
- Entenda a competência jurisdicional do mandado de segurança coletivo
- Identifique os direitos protegidos pelo mandado de segurança coletivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.170 (2)", "page_number": 170, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 21, § 1º da LMS"], "jurisprudence": ["AgInt no RMS 54.535/RJ", "STJ. 1ª Turma. AgInt no RMS 53.867/MG"], "confidence": 0.8, "extracted_at": "2026-06-01T02:31:02.153721+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=170", "doc_key": "e794eabf3e5754b1b870d5cc8ae75bbb"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '1f362be4f30d8b176a4a3827f3bdd4edb7abdec149118dcaea32afbb188c4873'),
  ('cpiuris2025::594fb6ea2ff7a1560a8d706a0a981a42', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Recurso Ordinário no Mandado de Segurança', '## Recurso Ordinário no Mandado de Segurança

O Supremo Tribunal Federal tem competência para julgar, em recurso ordinário, o mandado de segurança decidido em única instância pelos Tribunais Superiores.

### Conceitos
- **Competência do STF**: A competência do Supremo Tribunal Federal para julgar recursos ordinários
- **Mandado de Segurança**: Um pedido judicial que visa a proteger um direito fundamental ou garantia constitucional
- **Tribunais Superiores**: Os tribunais federais mais altos do país, com competência para julgar recursos ordinários

### Referências legais
- CF, art. 102, I, d
- CF, art. 102, II, a

### Jurisprudência
- STJ, REsp 700.206/MG
- RE 123456

### Dicas de prova
- Distinção entre recurso ordinário e mandado de segurança
- Competência do STF para julgar recursos ordinários', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.171 (2)", "page_number": 171, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["CF, art. 102, I, d", "CF, art. 102, II, a"], "jurisprudence": ["STJ, REsp 700.206/MG", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-06-01T02:31:17.661602+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=171", "doc_key": "594fb6ea2ff7a1560a8d706a0a981a42"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '7012a2ba8327871a6f75c3983d7c5e2e6558c6df609a68514543930d36298fd9'),
  ('cpiuris2025::d28214d99acacdc2757ac6c5bfb16659', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Mandado de Segurança Coletivo', '## Mandado de Segurança Coletivo

O Mandado de Segurança Coletivo abrange direitos coletivos, individuais homogêneos e difusos, sendo competência do STF determinar a regra de competência.

### Conceitos
- **Direitos Coletivos**: direitos que são comuns a um grupo ou categoria de pessoas
- **Direitos Individuais Homogêneos**: direitos que são semelhantes, mas não idênticos, aos direitos coletivos
- **Direitos Difusos**: direitos que são comuns a uma categoria de pessoas, mas não estão abrangidos pela tutela via mandado de segurança coletivo

### Referências legais
- Art. 5º, XXXV da CF/88
- Súmula N STF

### Jurisprudência
- RE 196.184/AM
- voto da Min. Ellen Gracie

### Dicas de prova
- Entenda a distinção entre direitos coletivos, individuais homogêneos e difusos.
- Leia atentamente o voto da Min. Ellen Gracie para entender a jurisprudência do STF.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.171 (1)", "page_number": 171, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º, XXXV da CF/88", "Súmula N STF"], "jurisprudence": ["RE 196.184/AM", "voto da Min. Ellen Gracie"], "confidence": 0.8, "extracted_at": "2026-06-01T02:31:35.254600+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=171", "doc_key": "d28214d99acacdc2757ac6c5bfb16659"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'c974f9622f677c32115dc1c994107819c70023220bcba26ba52a8c9922029dcb'),
  ('cpiuris2025::af13410439a01265d3d33ba707455bdb', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Requisitos para a concessão de liminares', '## Requisitos para a concessão de liminares

Os requisitos para a concessão de liminares são os mesmos exigidos no mandado de segurança individual, incluindo fundamento relevante (fummus bonis iuris) e risco de ineficácia da medida (periculum in mora).

### Conceitos
- **Fummus Bonis Iuris**: fundamento relevante
- **Periculum in Mora**: risco de ineficácia da medida

### Referências legais
- Art. 7º do Código de Processo Civil

### Jurisprudência
- STF, RE 266.689 AgR, rel. min. Ellen Gracie, j. 17-8-2004, 2ª Turma

### Dicas de prova
- Entenda o conceito de fummus bonis iuris e periculum in mora
- Identifique os requisitos para a concessão de liminares', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.172 (2)", "page_number": 172, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 7º do Código de Processo Civil"], "jurisprudence": ["STF, RE 266.689 AgR, rel. min. Ellen Gracie, j. 17-8-2004, 2ª Turma"], "confidence": 0.8, "extracted_at": "2026-06-01T02:33:05.158988+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=172", "doc_key": "af13410439a01265d3d33ba707455bdb"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '934f05de393af02c18b86abf3129804f0c1ac770cbcf4102c3774f4aae12830c'),
  ('cpiuris2025::bcb15bcd25cc3c4aca11495611f26925', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Competência para julgar mandados de segurança coletivos', '## Competência para julgar mandados de segurança coletivos

Discute a competência para julgar mandados de segurança coletivos, destacando as autoridades federais e estaduais competentes, bem como a Justiça Federal.

### Conceitos
- **Competência**: A capacidade do juiz ou tribunal de processar e julgar uma causa
- **Mandado de segurança coletivo**: Um pedido judicial que visa proteger direitos individuais em relação a atos de autoridades federais ou estaduais
- **Justiça Federal**: A competência da Justiça Federal é determinada pela Constituição e se aplica às causas envolvendo autoridades federais ou entidades federalmente controladas
- **Autoridade federal**: Uma autoridade que atua em nome do Estado federal, como um ministro de estado ou um juiz federal
- **Competência estatal**: A capacidade do tribunal estadual de processar e julgar uma causa

### Referências legais
- Art. 105, I, b da Constituição; Art. 108, I, c; Art. 114, IV; Art. 109, VIII

### Jurisprudência
- RE 176.881
- RE 123456

### Dicas de prova
- Entenda a distinção entre competência federal e estatal
- Conheça as autoridades que são consideradas autoridades federais para fins de impetração do mandado de segurança coletivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.172 (1)", "page_number": 172, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 105, I, b da Constituição; Art. 108, I, c; Art. 114, IV; Art. 109, VIII"], "jurisprudence": ["RE 176.881", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-06-01T02:33:45.259817+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=172", "doc_key": "bcb15bcd25cc3c4aca11495611f26925"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '6e5e5e772e948a5d79f73e6510c4fc2db5ea92aaa0f6878370bc6b23e301ce15'),
  ('cpiuris2025::4a9facd9c8037402faf2bd525ba3f0db', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Mandado de Segurança Coletivo', '## Mandado de Segurança Coletivo

O dispositivo prevê regras para a concessão de medida liminar em mandado de segurança coletivo, incluindo a necessidade de ouvir o representante judicial da pessoa jurídica de direito público e limitações às concessões de liminares.

### Conceitos
- **Mandado de Segurança Coletivo**: Medida liminar em processo coletivo para proteger direitos líquidos e certos
- **Caução ou fiança**: Garantia necessária para deferimento de medida liminar em mandado de segurança coletivo
- **Oitiva do representante judicial da pessoa jurídica de direito público**: Necessidade de ouvir o representante judicial antes da concessão de medida liminar
- **Limitações às concessões de liminares**: Regras que restrinjam a concessão de medidas liminares em certos casos

### Referências legais
- Art. 22, §2º da Lei n.º 13.964/2021 (LMS)
- Art. 2º da Lei n.º 7.347/85 (LACP)
- ADI 496
- Súmula N da STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Mandado de Segurança Coletivo e Caução ou Fiança

### Dicas de prova
- Entenda a necessidade de ouvir o representante judicial da pessoa jurídica de direito público antes da concessão de medida liminar
- Conheça as limitações às concessões de liminares previstas na LMS e LACP', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.173 (1)", "page_number": 173, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 22, §2º da Lei n.º 13.964/2021 (LMS)", "Art. 2º da Lei n.º 7.347/85 (LACP)", "ADI 496", "Súmula N da STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Mandado de Segurança Coletivo e Caução ou Fiança"], "confidence": 0.8, "extracted_at": "2026-06-01T02:34:38.092729+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=173", "doc_key": "4a9facd9c8037402faf2bd525ba3f0db"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'd0cb59d44b775b7526e07130dee9acccd886e9989d4cdbbe1439414f20d2c632'),
  ('cpiuris2025::410d9bd569f26d7c7349c0cabb24e6b8', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Concessão de medida liminar na via mandamental', '## Concessão de medida liminar na via mandamental

A concessão de medida liminar na via mandamental é permitida, desde que não viola a garantia de pleno acesso à jurisdição e à defesa do direito líquido e certo. A previsão normativa que veda a concessão da medida liminar em mandado de segurança não prevalece.

### Conceitos
- **Medida Liminar**: ordem provisória que visa proteger direito líquido e certo
- **Acesso à Jurisdição**: direito de todos os cidadãos a ser ouvido em juízo
- **Cosa Julgada Ultra Partes**: coisa julgada que se forma apenas com os membros do grupo ou categoria substituídos pelo autor coletivo

### Referências legais
- Art. 5º, LXXI da Constituição Brasileira de 1988

### Jurisprudência
- {''ref'': ''197 STF'', ''description'': ''Plenário. ADI 4296/DF''}
- {''ref'': ''198 STJ'', ''description'': ''Agravo de Instrumento nº 1.294.964/PA''}

### Dicas de prova
- Distinção entre medida liminar e mandado de segurança
- Garantia do acesso à jurisdição e defesa do direito líquido e certo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.173 (2)", "page_number": 173, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º, LXXI da Constituição Brasileira de 1988"], "jurisprudence": ["{''ref'': ''197 STF'', ''description'': ''Plenário. ADI 4296/DF''}", "{''ref'': ''198 STJ'', ''description'': ''Agravo de Instrumento nº 1.294.964/PA''}"], "confidence": 0.8, "extracted_at": "2026-06-01T02:35:37.583662+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=173", "doc_key": "410d9bd569f26d7c7349c0cabb24e6b8"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '8da89af6e725d136bba430b2db028bb6c20e93669bcdf77b6bf6183fe46b6807'),
  ('cpiuris2025::1a4df8dfa9c2bd0decb6d62e5f77b2ca', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Mandado de Segurança Coletivo', '## Mandado de Segurança Coletivo

O artigo 22 da LMS estabelece que a sentença em mandado de segurança coletivo beneficia apenas os membros do grupo ou categoria substituídos pela impetrante, independentemente de vínculo associativo.

### Conceitos
- **Mandado de Segurança Coletivo**: ação judicial que visa proteger os direitos de uma categoria ou grupo
- **Substituição Processual**: substituição dos membros do grupo ou categoria por outra pessoa, nesse caso, a impetrante
- **Benefício da Substituição Processual**: benefício concedido aos titulares do direito defendido na ação, independentemente de vínculo associativo

### Referências legais
- Art. 22 da LMS

### Jurisprudência
- Súmula 211/STJ
- REsp 1.603.862/PE
- REsp 1669078/SC

### Dicas de prova
- Entenda a noção de substituição processual e seu benefício aos titulares do direito defendido na ação.
- Conheça a jurisprudência do STF e STJ sobre o tema.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.174 (1)", "page_number": 174, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 22 da LMS"], "jurisprudence": ["Súmula 211/STJ", "REsp 1.603.862/PE", "REsp 1669078/SC"], "confidence": 0.8, "extracted_at": "2026-06-01T02:36:01.494538+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=174", "doc_key": "1a4df8dfa9c2bd0decb6d62e5f77b2ca"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '78987a6fa15be82944fcacb87c3c5e34d1269109dfa384587d90a6efec9284cc'),
  ('cpiuris2025::90ae32b691139953b8565e16ddb65233', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Cosa Julgada', '## Cosa Julgada

A coisa julgada se perfaz segundo o evento litis e o evento probationis, independentemente da espécie de direito coletivo tutelado.

### Conceitos
- **Cosa Julgada**: Conceito jurídico que se refere à decisão final do juiz em um processo
- **Evento Litis**: Ocorre quando o autor apresenta ação contra o réu
- **Evento Probacionis**: Ocorre quando o réu apresenta defesa contra o autor

### Referências legais
- Art. 185 do Código de Processo Civil
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre coisa julgada material e improcedência
- Conheça os eventos litis e probationis', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.174 (2)", "page_number": 174, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 185 do Código de Processo Civil", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-06-01T02:36:19.898688+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=174", "doc_key": "90ae32b691139953b8565e16ddb65233"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'dbf186fc2afdc035105d2b2bc5c2ac698b807223498768cbe69fc6f22683bd30'),
  ('cpiuris2025::6e3c222ae73bc69c41ffb3800d1ed3e0', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Litispendência em Mandado de Segurança Coletivo', '## Litispendência em Mandado de Segurança Coletivo

O mandado de segurança coletivo não induz litispendência para as ações individuais, mas os efeitos da coisa julgada não beneficiarão o impetrante a título individual se não requerer a desistência do seu mandado de segurança no prazo de 30 dias.

### Conceitos
- **Litispendência**: Conceito jurídico que se refere à impossibilidade de processar uma causa após outra
- **Mandado de Segurança Coletivo**: Ação coletiva que visa proteger direitos ou interesses de várias pessoas
- **Cosa Julgada**: Conceito jurídico que se refere à decisão final de um processo que não pode ser reavaliado

### Referências legais
- Art. 22 §1º da Lei n.º 9.868/1990
- Súmula 304 do STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre litispendência e coisa julgada
- Conheça as regras sobre desistência de demanda individual em face da segurança coletiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.175 (1)", "page_number": 175, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 22 §1º da Lei n.º 9.868/1990", "Súmula 304 do STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-06-01T02:37:56.675442+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=175", "doc_key": "6e3c222ae73bc69c41ffb3800d1ed3e0"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '3aef2df3ee66e1b6cd0c521a74176304bce35b5769867701f3a55654a46dfe81'),
  ('cpiuris2025::9f693fadb9e53302fa71af9b40fc6835', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Litispendência nas ações coletivas', '## Litispendência nas ações coletivas

As ações coletivas não induzem litispendência para as ações individuais, mas os efeitos da coisa julgada erga omnes podem afetar as ações individuais se não for requerida sua suspensão.

### Conceitos
- **Litispendência**: Condição em que duas ou mais ações judiciais têm como objeto o mesmo direito e são apresentadas perante o mesmo juiz
- **Ações coletivas**: Ações que visam proteger um grupo de pessoas com interesses semelhantes
- **Coisa julgada erga omnes**: Efeito da decisão judicial que se estende a todos os interessados, independentemente do seu envolvimento na causa

### Referências legais
- Art. 81, incisos I e II, CDC
- Parágrafo único do art. 81, CDC

### Dicas de prova
- Diferenciar entre litispendência e coisa julgada erga omnes
- Entender a importância da suspensão da demanda individual em ações coletivas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.175 (2)", "page_number": 175, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 81, incisos I e II, CDC", "Parágrafo único do art. 81, CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-06-01T02:38:14.399799+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=175", "doc_key": "9f693fadb9e53302fa71af9b40fc6835"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'b95ce64047d6d7fc40b6cb904e28a2b4f1d22b5478540625447b3445c45b27eb'),
  ('cpiuris2025::ea000a3f0e224cdbe1c39a8ed8f1f7c0', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Recurso Ordinário em Mandado de Segurança', '## Recurso Ordinário em Mandado de Segurança

O recurso ordinário em mandado de segurança é cabível, mas há situações específicas que devem ser consideradas. A decisão do STJ estabelece que o recurso ordinário não cabe contra apelação em mandado de segurança e que a fungibilidade recursal é afastada.

### Conceitos
- **Recurso Ordinário**: Ação recursal cabível em determinadas situações
- **Fungibilidade Recursal**: Princípio que permite a interposição de recurso ordinário contra apelação em certas situações

### Referências legais
- Art. 14 da LMS
- Súmula 201 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo sobre fungibilidade recursal

### Dicas de prova
- Distinguir entre mandado de segurança impetrado diretamente no TJ ou TRF e decisão denegatória
- Entender a situação em que o recurso ordinário é cabível', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.176 (1)", "page_number": 176, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 14 da LMS", "Súmula 201 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre fungibilidade recursal"], "confidence": 0.8, "extracted_at": "2026-06-01T02:38:27.474226+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=176", "doc_key": "ea000a3f0e224cdbe1c39a8ed8f1f7c0"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '987c89539e119e5133e1250f77fe4e267aed7e82092e6769b1f53a9e2be375aa'),
  ('cpiuris2025::5523d839cdf6afe95d497bcdfec5abf0', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Legitidade Ativa do Sindicato em Processos de Pensão', '## Legitidade Ativa do Sindicato em Processos de Pensão

O sindicato tem legitimidade ativa para substituir a pensionista diante da natureza do vínculo que a pensão gera em relação à viúva do servidor, sem necessidade de sua efetiva filiação.

### Conceitos
- **Legitidade Ativa**: Direito do sindicato para agir em nome da pensionista
- **Vínculo de Pensão**: Relação jurídica entre o servidor e a pensão
- **Representação Sindical**: Categoria representada pelo sindicato

### Referências legais
- Art. 9º da CLT
- ...

### Jurisprudência
- REsp 1.848.480/PE
- AgInt nos EDcl no AgInt no REsp 1632524/RS
- RMS 66.905-SP

