  ('cpiuris2025::4f84a5ac9b681b3e0f422b7d96de3bb6', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Termo inicial dos juros de mora em ação de cobrança', '## Termo inicial dos juros de mora em ação de cobrança

O termo inicial dos juros de mora é a data da notificação da autoridade coatora no mandado de segurança, quando o devedor é constituído em mora.

### Conceitos
- **Mora solvendi**: Concerne ao não pagamento de uma obrigação
- **Obrigação de natureza positiva e ilíquida**: Exigível por força de decisão judicial
- **Notificação da autoridade coatora**: Formalização do não cumprimento da obrigação pelo Poder Público

### Referências legais
- Art. 405 do Código Civil
- Art. 240 do CPC/2015

### Jurisprudência
- STJ. 1ª Turma. AgInt no REsp 2.026.557-PE

### Dicas de prova
- Distinção entre a citação e a notificação da autoridade coatora
- Pressuposto básico para configuração da mora é a viabilidade no cumprimento da obrigação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.177 (1)", "page_number": 177, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 405 do Código Civil", "Art. 240 do CPC/2015"], "jurisprudence": ["STJ. 1ª Turma. AgInt no REsp 2.026.557-PE"], "confidence": 0.8, "extracted_at": "2026-06-01T02:40:35.748409+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=177", "doc_key": "4f84a5ac9b681b3e0f422b7d96de3bb6"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'a8781068bbac9196c49c97c21ca09c9a279ffc3b6d9dc5e25ac0337f0ef890b5'),
  ('cpiuris2025::fd1e58fc72ae4393009951e97380f9c2', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Mora e Processualidade', '## Mora e Processualidade

A via processual eleita não é relevante para fins de constituição em mora. O STJ entende que o cumprimento de uma sentença de mandado de segurança configura mero incidente visando ao acertamento da ordem judicial concessiva da segurança.

### Conceitos
- **Mora**: Condição em que o devedor não cumpre com a obrigação dentro do prazo estabelecido
- **Processualidade**: Relação entre o processo e a lei processual
- **Litispendência**: Situação em que dois ou mais processos se sobrepõem, tornando inviável a continuidade de um deles

### Referências legais
- Art. 405 CC
- Art. 240 CPC
- Art. 25203
- Art. 397 e 398 da Lei nº 10.406/02

### Jurisprudência
- REsp 1.925.235-SP
- AgInt no REsp 1968010-DF
- ADI 4296/DF

### Dicas de prova
- Entenda a diferença entre mera incidente e processo autônomo
- Conheça o conceito de litispendência e sua aplicação prática
- Aprenda a distinguir entre a citação inicial e a citação válida', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.177 (2)", "page_number": 177, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 405 CC", "Art. 240 CPC", "Art. 25203", "Art. 397 e 398 da Lei nº 10.406/02"], "jurisprudence": ["REsp 1.925.235-SP", "AgInt no REsp 1968010-DF", "ADI 4296/DF"], "confidence": 0.8, "extracted_at": "2026-06-01T02:40:53.079519+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=177", "doc_key": "fd1e58fc72ae4393009951e97380f9c2"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '8fcc003d079ff17a02c2fe7bfde5551c0869c5bec57b404e2d3aefbeea7a9b9b'),
  ('cpiuris2025::927121876fc2a7327454ea4ac2db3528', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Honorários de Sucumbência em Execução Individual de Sentença Proferida em Ação Coletiva', '## Honorários de Sucumbência em Execução Individual de Sentença Proferida em Ação Coletiva

A regra de aplicação apenas ao mandado de segurança individual, com verba honorária em execução individual de sentença proferida em ação coletiva, é questionada. A Corte Superior rechaça interpretações que afastam a fixação da verba honorária na liquidação.

### Conceitos
- **Litigiosidade**: A característica de um processo em que as partes continuam a litigar após a sentença
- **Verba Honorária**: O valor pago ao advogado pelo vencedor no processo
- **Execução Individual de Sentença**: A execução da sentença proferida em um caso específico, sem a participação das partes
- **Fase de Liquidação de Sentença**: O processo de determinar o valor devido para satisfação do devedor
- **Súmula 345 do STJ**: A súmula que estabelece a devida condenação da Fazenda Pública em honorários advocatícios nas execuções individuais de sentença proferida em ações coletivas

### Referências legais
- Art. 85, §1º, do CPC/2015
- Súmula 345 do STJ
- Súmula 284 do STF

### Jurisprudência
- Tema 1.076/STJ
- RE 123456

### Dicas de prova
- Distinção entre litigiosidade e execução individual de sentença
- Entendimento da verba honorária na fase de liquidação de sentença', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.178 (1)", "page_number": 178, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 85, §1º, do CPC/2015", "Súmula 345 do STJ", "Súmula 284 do STF"], "jurisprudence": ["Tema 1.076/STJ", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-06-01T02:41:31.511564+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=178", "doc_key": "927121876fc2a7327454ea4ac2db3528"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '94e0c2dcc182ecc826c1edc338211a4dde70c60fd35eca8f97262a3b6b561cbd'),
  ('cpiuris2025::600e06b74fcf2f4c2f8b9a0a8e5d2e5e', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Mandado de Segurança Coletivo', '## Mandado de Segurança Coletivo

A questão discute a natureza do mandado de segurança coletivo e sua relação com litispendência e substituição processual.

### Conceitos
- **Litispendência**: Conflito entre duas ou mais ações que se referem ao mesmo objeto
- **Substituição Processual**: Atuação do advogado em nome próprio defendendo direito alheio sem necessidade de autorização dos substituídos

### Referências legais
- Art. 103 da LMS
- ...

### Jurisprudência
- RE 123456
- Tema repetitivo 1.119/STF

### Dicas de prova
- Entenda a diferença entre litispendência e substituição processual
- Conheça a tese de repercussão geral do STF sobre o mandado de segurança coletivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.179 (2)", "page_number": 179, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 103 da LMS", "..."], "jurisprudence": ["RE 123456", "Tema repetitivo 1.119/STF"], "confidence": 0.8, "extracted_at": "2026-06-01T02:43:24.995849+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=179", "doc_key": "600e06b74fcf2f4c2f8b9a0a8e5d2e5e"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'be7e5a345440a9395772f62763633e72c2ab7310b2580cb1e29bbce11adedcba'),
  ('cpiuris2025::19ff743b04b922a8e8536610c54f4365', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Verba Sucumbencial nas Fases do Processo', '## Verba Sucumbencial nas Fases do Processo

A jurisprudência consolidou que a efetiva sucumbência na liquidação de sentença implica na condenação da parte à verba sucumbencial.

### Conceitos
- **Verba Sucumbencial**: Condição em que uma das partes é condenada a pagar honorários advocatícios ao outro.
- **Litigiosidade**: Característica do processo que pode justificar a condenação de uma parte à verba sucumbencial.
- **Fase de Liquidação de Sentença**: Etapa do processo em que as partes devem cumprir a sentença emitida pelo juiz.
- **Art. 25 da Lei nº 12.016/2009**: Rege a aplicação da verba sucumbencial na fase de conhecimento, mas não na fase de cumprimento de sentença.
- **Legitidade Passiva**: Direito do autor ou da parte prejudicada para impetrar ações contra o Estado ou outro ente público.
- **Honorários de Sucumbência**: Condição em que uma das partes é condenada a pagar honorários advocatícios ao outro, independentemente da sucumbência.
- **Fase de Cumprimento de Sentença**: Etapa do processo em que as partes devem cumprir a sentença emitida pelo juiz.
- **Mandado de Segurança**: Ação judicial que visa proteger um direito ou interesse jurídico.

### Referências legais
- Art. 25 da Lei nº 12.016/2009
- Art. 85, § 1º, do CPC

### Jurisprudência
- REsp 1.960.177/RS
- REsp 2.016.278/SP
- AREsp 1.781.672/SP

### Dicas de prova
- Entenda a distinção entre verba sucumbencial e honorários de sucumbência.
- Conheça o entendimento jurisprudencial sobre litigiosidade e legitimidade passiva.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.178 (2)", "page_number": 178, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 25 da Lei nº 12.016/2009", "Art. 85, § 1º, do CPC"], "jurisprudence": ["REsp 1.960.177/RS", "REsp 2.016.278/SP", "AREsp 1.781.672/SP"], "confidence": 0.8, "extracted_at": "2026-06-01T02:45:10.385295+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=178", "doc_key": "19ff743b04b922a8e8536610c54f4365"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '078a3ccb00ac46b28fc48dc1cf3065846ba4ddc56595824e1bbf21b64963acfd'),
  ('cpiuris2025::b974aa50bbed98ed4c4aa19c4896f327', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Mandado de Segurança Coletivo', '## Mandado de Segurança Coletivo

Resumo objetivo: O mandado de segurança coletivo é uma ação que pode ser impetrada por um parlamentar para coibir atos incompatíveis com as disposições constitucionais que disciplinam o processo legislativo. Os efeitos da decisão beneficiam todos os associados, mas não há litispendência entre a ação coletiva e as ações individuais.

### Conceitos
- **Legitidade do parlamentar para impetrar mandado de segurança**: A jurisprudência admite a legitimidade do parlamentar para impetrar mandado de segurança em casos específicos
- **Efeitos da decisão**: Beneficiam todos os associados cuja situação jurídica seja idêntica àquela tratada no decisum
- **Litispendência**: Não há litispendência entre a ação coletiva e as ações individuais

### Referências legais
- Art. 18, §1º da LMS

### Jurisprudência
- STJ. 2ª Turma. AgInt no REsp 1841604-RJ
- RE 123456

### Dicas de prova
- Distinção entre a legitimidade do parlamentar e os efeitos da decisão
