  ('cpiuris2025::edd7a500bc3fd1c21c812dbcc18818ff', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Mandado de Segurança Coletivo', '## Mandado de Segurança Coletivo

O mandado de segurança coletivo é uma ação que pode ser impetrada por entidades associativas de caráter civil, com autorização expressa dos associados e comprovação de filiação prévia. A sentença decorrente dessa ação deve ser cobrada como verba honorária.

### Conceitos
- **Legitimidade das associações**: A exigência de expressa autorização dos associados é necessária para a legitimação das associações em ações coletivas.
- **Verba honorária**: A sentença decorrente do mandado de segurança coletivo deve ser cobrada como verba honorária, mesmo que proveniente de ação mandamental.
- **Filiação prévia**: É necessária a comprovação de filiação prévia dos associados para a cobrança de valores pretéritos do título judicial.
- **Mandado de segurança coletivo**: É uma ação que pode ser impetrada por entidades associativas de caráter civil com autorização expressa dos associados e comprovação de filiação prévia.
- **Legitimação ad causam**: A exigência de expressa autorização dos associados condiciona a legitimação das associações para promoção de ações coletivas.
- **Substituição processual**: Não se aplica à legitimidade das associações em ações coletivas.
- **Partidos políticos**: Têm legitimidade para impetrar mandado de segurança para coibir atos praticados no processo de aprovação de leis e emendas constitucionais.
- **Execução do título extrajudicial**: Aquele que se filiar após a impetração do mandado de segurança coletivo será parte ilegítima para execução do título.

### Referências legais
- Art. 5º, XXI da Constituição de 1988
- Súmula 345/STJ

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Perguntas sobre a legitimidade das associações em ações coletivas e a exigência de expressa autorização dos associados.
- Verba honorária como consequência da sentença decorrente do mandado de segurança coletivo.
- Importância da comprovação de filiação prévia para a cobrança de valores pretéritos do título judicial.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.179 (1)", "page_number": 179, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º, XXI da Constituição de 1988", "Súmula 345/STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-06-01T02:45:51.128825+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=179", "doc_key": "edd7a500bc3fd1c21c812dbcc18818ff"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'ca40923f870b602f665baa751fc20c1b019dd809814ce556f22e2d7a60d0cdcd'),
  ('cpiuris2025::f6c783a65528ff24082ac050eec7fd86', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Exceções ao Mandado de Segurança', '## Exceções ao Mandado de Segurança

A norma amplia o rol previsto na lei que regulamenta o mandado de segurança, com uma preocupação com a ''representação adequada'', especialmente em casos relevantes para a promoção dos direitos humanos e a defesa dos direitos individuais e coletivos dos necessitados.

### Conceitos
- **Mandado de Segurança**: ato processual que visa garantir a observância das leis e normas superiores
- **Exceção ao Mandado de Segurança**: situação em que o mandado de segurança não pode ser concedido
- **Representação Apropriada**: necessidade de uma representação adequada para a promoção dos direitos humanos e a defesa dos direitos individuais e coletivos dos necessitados

### Referências legais
- Art. 5º, LXXIV da CF

### Dicas de prova
- Entenda o conceito de Mandado de Segurança e suas exceções.
- Identifique a importância da ''representação adequada'' nos casos relevantes.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.183 (2)", "page_number": 183, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º, LXXIV da CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-06-01T02:47:50.609746+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=183", "doc_key": "f6c783a65528ff24082ac050eec7fd86"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'e70816cd0f3c3bda975af5e260dc622f3f6404e3105b961351fdfed0168ee18f'),
  ('cpiuris2025::842a92a77216c75cac04676bf662631b', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Mandado de Injunção Coletivo', '## Mandado de Injunção Coletivo

O mandado de injunção coletivo é um instrumento de tutela coletiva que pode ser impetrado por legitimados específicos para viabilizar direitos das coletividades.

### Conceitos
- **Mandado de Injunção Coletivo**: instrumento de tutela coletiva
- **Legitimidade Ativa**: direito para propositura do mandado coletivo
- **Mandado de Injunção Total**: há falta de norma regulamentadora de norma constitucional
- **Mandado de Injunção Parcial**: há normas insuficientes para viabilizar o exercício do direito
- **Mandado de Injunção Individual**: impetrado por pessoas físicas e jurídicas para viabilizar direitos individuais

### Referências legais
- Art. 2º da Lei em discussão
- Art. 12 da Lei em discussão
- Súmula N da STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre mandado de injunção total, parcial e coletivo
- Entender a legitimidade ativa para propositura do mandado coletivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.183 (1)", "page_number": 183, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 2º da Lei em discussão", "Art. 12 da Lei em discussão", "Súmula N da STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-06-01T02:48:30.149010+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=183", "doc_key": "842a92a77216c75cac04676bf662631b"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'a4c0cb6366e24943116564aaecfdae58bfb45a8f0e05f2bed05fda9b2d17f440'),
  ('cpiuris2025::c89b07bce8535262ebbcbb5a62778ece', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Mandado de Injunção Coletivo', '## Mandado de Injunção Coletivo

O mandado de injunção coletivo é um instrumento do processo constitucional criado para tutelar direitos subjetivos em face de omissão estatal. Ele busca sanar a ''síndrome de inefetividade das normas constitucionais'' e tem como requisitos: existência de norma constitucional desprovida de aplicabilidade imediata, dever estatal de editar normas infraconstitucionais e omissão do Poder Público em cumprir esse dever.

### Conceitos
- **Mandado de Injunção Coletivo**: Instrumento do processo constitucional criado para tutelar direitos subjetivos em face de omissão estatal.
- **Síndrome de Inefetividade das Normas Constitucionais**: Conceito que descreve a situação em que as normas constitucionais não são eficazes ou não são aplicadas corretamente pelo Estado.
- **Norma Constitucional de Eficácia Limitada**: Norma constitucional que não tem aplicabilidade imediata e requer regulamentação por meio de normas infraconstitucionais.
- **Dever Estatal de Editar Normas Infraconstitucionais**: Obrigação do Estado de criar e regular as normas que devem ser aplicadas para tornar efetivos os direitos previstos na norma constitucional de eficácia limitada.
- **Omissão do Poder Público**: Falta de ação ou inação do Estado em cumprir o dever de editar as normas infraconstitucionais que regulamentem os direitos previstos na norma constitucional de eficácia limitada.

### Referências legais
- Art. 5º LXXI da Constituição Federal
- Lei n.º 13.300/2016

### Dicas de prova
- Entenda a diferença entre mandado de segurança e mandado de injunção coletivo.
- Conheça as hipóteses em que pode ser impetrada uma ação de mandado de injunção coletivo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.182", "page_number": 182, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º LXXI da Constituição Federal", "Lei n.º 13.300/2016"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-06-01T02:49:15.767611+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=182", "doc_key": "c89b07bce8535262ebbcbb5a62778ece"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '50847989038153d3d12fcd85d6d3f17b3fd42d3bf9283d34c32897398633170c'),
  ('cpiuris2025::aa84abce2c45d64943f025cb3a6ed57f', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Legitimidade para impetrar mandado de injunção coletivo', '## Legitimidade para impetrar mandado de injunção coletivo

O Ministério Público, partido político com representação no Congresso Nacional e organizações sindicais têm legitimidade para impetrar mandado de injunção coletivo, desde que atendam a requisitos específicos.

### Conceitos
- **Legitimidade**: Qualidade jurídica que permite agir em nome de outrem
- **Mandado de Injunção Coletivo**: Ação coletiva que visa proteger direitos e interesses sociais ou individuais indisponíveis
- **Ministério Público**: Instituição permanente que defende a ordem jurídica e os interesses sociais e individuais indisponíveis
- **Partido Político**: Entidade política que tem representação no Congresso Nacional
- **Organização Sindical**: Entidade que representa os interesses de uma categoria profissional ou social

### Referências legais
- Art. 2º, I, da LMI
- Constituição Federal/88
- Código de Processo Civil/2015

### Jurisprudência
- RE 123456
- Tema repetitivo do mandado de segurança coletivo

### Dicas de prova
- Entenda a legitimidade para impetrar mandado de injunção coletivo e os requisitos específicos para cada caso
