  ('cpiuris2025::1a32df18ff0d11185242b4ff961b0c11', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Mandado de Injunção Coletivo', '## Mandado de Injunção Coletivo

O mandado de injunção coletivo é uma medida constitucional que exige demonstração da pertinência temática e não depende de autorização dos membros ou associados. A Defensoria Pública pode ser legitimada para propositura desse tipo de mandado, especialmente quando a tutela requerida for relevante para promoção dos direitos humanos.

### Conceitos
- **Mandado de Injunção**: Medida constitucional que exige demonstração da pertinência temática
- **Legitimidade**: Direito para agir em nome de outrem ou de uma entidade
- **Defensoria Pública**: Orgão do Estado responsável por prestar assistência jurídica integral e gratuita aos necessitados
- **Princípio da Indisponibilidade**: Princípio que proíbe a desistência de ações constitucionais

### Referências legais
- Art. 5º, LXXIV da CF
- CB/88

### Jurisprudência
- RE 712/PA QO
- MI 712/PA QO

### Dicas de prova
- Entenda a legitimidade para propositura do mandado de injunção coletivo
