  ('cpiuris2025::05d254c7ed5fb5f0b81365e947e35cff', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Legitimidade passiva no processo coletivo', '## Legitimidade passiva no processo coletivo

A legitimidade passiva é estabelecida para o Poder, órgão ou autoridade com atribuição para editar a norma regulamentadora.

### Conceitos
- **Legitimidade passiva**: O direito de uma parte ser considerada como responsável por um processo.
- **Poder**: A entidade pública que exerce autoridade para editar normas regulamentadoras.
- **Órgão**: Unidade administrativa que executa as atividades do Poder.
- **Autoridade**: Entidade pública que tem competência para editar normas regulamentadoras.

### Referências legais
- Art. 2º da LMI

### Dicas de prova
- Distinção entre legitimidade passiva e legitimidade activa.
- Entendimento do termo ''Poder'', ''Órgão'' e ''Autoridade''.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.185 (2)", "page_number": 185, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 2º da LMI"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-06-01T02:51:10.158510+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=185", "doc_key": "05d254c7ed5fb5f0b81365e947e35cff"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '1014118efb0de732d3cb5a03024d8a26a3c6f2c2455d309ba9745e55e3e44fd1'),
  ('cpiuris2025::16f18904a6a3203791b139d9494bbc54', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Exercício dos Direitos e Liberdades', '## Exercício dos Direitos e Liberdades

Resumo do artigo sobre as condições para o exercício dos direitos e liberdades, incluindo a administração pública e o direito de greve.

### Conceitos
- **Administração Pública**: Obedecerá aos princípios de legalidade, impessoalidade, moralidade, publicidade e eficiência
- **Direito de Greve**: Exercido nos termos e limites definidos em lei específica

### Referências legais
- Art. 37 da CF
- Art. 214 do texto não existe, mas é referência ao artigo anterior

### Dicas de prova
- Perguntas sobre a administração pública e o direito de greve podem ser respondidas com base nos princípios estabelecidos na Constituição.
