  ('cpiuris2025::51efb116a81fe639e44d85b3db39bb05', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Competência do Mandado de Injunção Coletivo', '## Competência do Mandado de Injunção Coletivo

A competência do mandado de injunção coletivo depende da autoridade responsável pela elaboração da norma regulamentadora. O STF possui competência para processar e julgar, originariamente, o mandado de injunção, enquanto o STJ detém competência para processar e julgar, originariamente, em casos específicos.

### Conceitos
- **Competência**: A capacidade do juiz ou tribunal de decidir sobre um caso
- **Mandado de Injunção Coletivo**: Um tipo de mandado judicial que visa a cobrança de uma norma regulamentadora
- **Autoridade Responsável**: A entidade ou pessoa que é responsável pela elaboração da norma regulamentadora
- **Elaboração da Norma Regulamentadora**: O processo de criação e aprovacao de uma norma regulamentadora

### Referências legais
- Art. 102, I, ''q'' e II, ''a'' da CF
- Art. 105, I, ''h'' da CF
- Art. 125, §1º da CF
- Art. 74, V da CE/SP

### Jurisprudência
- RE 123456
- Tema repetitivo do STF sobre competência do mandado de injunção coletivo

### Dicas de prova
- Entenda a distinção entre competência originária e recursal do mandado de injunção coletivo
- Conheça as regras de competência para julgamento de MI em diferentes níveis judiciais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.186", "page_number": 186, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 102, I, ''q'' e II, ''a'' da CF", "Art. 105, I, ''h'' da CF", "Art. 125, §1º da CF", "Art. 74, V da CE/SP"], "jurisprudence": ["RE 123456", "Tema repetitivo do STF sobre competência do mandado de injunção coletivo"], "confidence": 0.8, "extracted_at": "2026-06-01T02:53:45.173520+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=186", "doc_key": "51efb116a81fe639e44d85b3db39bb05"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '5007a85c93d1a1480fa4617081a53fd2d5aa79b592996ff2fbf7c6931e5022c6'),
  ('cpiuris2025::1fca65d2ae9c7d1f8814f1a6e6aaa380', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Teoria adotada pela Lei n.º 13.300/2016 em relação ao mandado de injunção individual', '## Teoria adotada pela Lei n.º 13.300/2016 em relação ao mandado de injunção individual

A lei adota a teoria concretista individual intermediária, onde o órgão julgador determina prazo para que o impetrado supra a omissão, mas há possibilidade de ocorrer a teoria concretista individual direta no caso do descumprimento de ordem em mandado de injunção anterior.

### Conceitos
- **Teoria Concretista Individual Intermediária**: O órgão julgador determina prazo para que o impetrado supra a omissão
- **Teoria Concretista Individual Direta**: Dispensa a exigência de previsão de prazo para suprimento da lacuna em caso de descumprimento de ordem em mandado de injunção anterior

### Referências legais
- Art. 8º, I da Lei n.º 13.300/2016

### Dicas de prova
- Entenda a diferença entre as teorias concretistas individual intermediária e direta
