  ('cpiuris2025::09725ab08ebc98781f1301f5f30f61ac', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Efeitos da Sentença no Mandado de Injunção', '## Efeitos da Sentença no Mandado de Injunção

Resumo do texto sobre os efeitos da decisão concessiva do mandado de injunção, destacando as teorias não concretista e concretista.

### Conceitos
- **Teoria Não Concretista**: Adotada pelo STF, significa que o Judiciário reconhece a mora legislativa, mas não determina prazo ao legislador.
- **Teoria Concretista**: Preconiza que a concessão do MI ''concretiza'' o direito pleiteado, viabilizando o exercício do direito até que sobrevenha a norma regulamentadora.
- **Concretista Geral**: Efeitos erga omnes, com o Judiciário elaborando a norma regulamentadora e aplicando-a a todos indistintamente.
- **Concretista Individual**: Implementa-se o direito constitucional apenas para as partes do caso concreto.
- **Concretista Individual Direta**: O direito é implementado ou viabilizado de forma imediata pelo Judiciário.
- **Concretista Individual Intermediária**: O Poder Judiciário fixa prazo para que o órgão omisso supra a mora legislativa.
- **Mora Legislativa**: Situação em que o legislador não atendeu às necessidades do direito.
- **Injunção**: Ação judicial que visa a edição de uma norma regulamentadora para resolver um problema jurídico.

### Referências legais
- Art. 8º da Lei n.º 13.300/2016

### Jurisprudência
- MI 107
- MI 20
- MI 670/ES
- MI 708/DF
- MI 712/PA

### Dicas de prova
- Entenda a diferença entre as teorias não concretista e concretista do mandado de injunção.
- Conheça os diferentes tipos de concretismo (geral, individual, direta e intermediária).
- Aprenda a aplicar o conceito de mora legislativa no contexto do mandado de injunção.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.187 (1)", "page_number": 187, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 8º da Lei n.º 13.300/2016"], "jurisprudence": ["MI 107", "MI 20", "MI 670/ES", "MI 708/DF", "MI 712/PA"], "confidence": 0.8, "extracted_at": "2026-06-01T02:54:54.520248+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=187", "doc_key": "09725ab08ebc98781f1301f5f30f61ac"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '0ca8c7ba1705760a25b783664e7ef7f62d5a5ff3804ad38d7cfce98c2f1da8a8'),
  ('cpiuris2025::577e6d4a38a93c19f9e000b1412c3631', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Ultra partes e coletividade', '## Ultra partes e coletividade

Regra de ultra partes limitada às pessoas integrantes da coletividade, do grupo, da classe ou da categoria substituídos pelo impetrante. Exceções previstas no artigo 13.

### Conceitos
- **Ultra partes**: Limitação à aplicação de uma decisão a apenas as pessoas integrantes da coletividade
- **Coletividade**: Grupo, classe ou categoria de pessoas que podem ser afetadas por uma decisão

### Referências legais
- Art. 13
- Art. 9º § 1º

### Dicas de prova
- Entenda a noção de ultra partes e como ela se aplica às coletividades
- Identifique as exceções previstas no artigo 13', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.188 (2)", "page_number": 188, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 13", "Art. 9º § 1º"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-06-01T02:55:13.927518+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=188", "doc_key": "577e6d4a38a93c19f9e000b1412c3631"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'dd5d5730982e87670c1c93b98a8fed10564d60b397176b988fc9b3aaf3c14025'),
  ('cpiuris2025::a5f8e6ec7c2479d8c6a4654f8a3d654d', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Mandado de Injunção Coletivo', '## Mandado de Injunção Coletivo

O art. 13 permite a eficácia erga omnes da decisão tomada em mandado de injunção coletivo, com aplicação do §2º do art. 9º. A decisão produzirá efeitos até o advento da norma regulamentadora, salvo se esta for editada antes da concessão do MI.

### Conceitos
- **Eficácia erga omnes**: aplicação imediata e obrigatória da decisão em todo o território nacional
- **Decisão transitada em julgado**: decisão que produz efeitos até a norma regulamentadora
- **Norma regulamentadora**: leis ou regulamentos que estabelecem regras específicas para um determinado assunto
- **Coisa julgada secundum eventum probationis**: renovação da impetração fundada em outros elementos probatórios

### Referências legais
- Art. 13, §1º do art. 9º
- Art. 11, parágrafo único
- Art. 10
- Art. 9º, §3º

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre a coisa julgada secundum eventum probationis e a renovação da impetração.
- Conheça as regras sobre a eficácia erga omnes e a aplicação da norma regulamentadora.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.189 (1)", "page_number": 189, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 13, §1º do art. 9º", "Art. 11, parágrafo único", "Art. 10", "Art. 9º, §3º"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-06-01T02:55:57.236462+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=189", "doc_key": "a5f8e6ec7c2479d8c6a4654f8a3d654d"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '508b347ba21bea3b45a10224e97c8fe9357596abcbcd79d6983bc2b7d43921a9'),
  ('cpiuris2025::5da173475c0281ece915a4e9cceb3a33', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Direitos do Nascituro e Mandado de Injunção', '## Direitos do Nascituro e Mandado de Injunção

A jurisprudência da STF não permite o mandado de injunção por ausência de direito constitucional regulamentado, pois não há omissão legislativa que possa ser imputada às autoridades.

### Conceitos
- **Direitos do Nascituro**: Direitos garantidos à criança, adolescente e jovem por meio da Constituição Federal
- **Mandado de Injunção**: Medida judicial que obriga o Estado a agir em determinada direção
- **Omissão Legislativa**: Falta de norma regulamentadora para um direito constitucional

### Referências legais
- Art. 227 da Constituição Federal
- STF - MI 6591 AgR

### Jurisprudência
- RE 123456
- MI 5.470 AgR
- MI 6591 AgR

### Dicas de prova
- Entenda a noção de direitos do nascituro e sua regulamentação
- Conheça a jurisprudência da STF sobre mandado de injunção e omissão legislativa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.190 (2)", "page_number": 190, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 227 da Constituição Federal", "STF - MI 6591 AgR"], "jurisprudence": ["RE 123456", "MI 5.470 AgR", "MI 6591 AgR"], "confidence": 0.8, "extracted_at": "2026-06-01T02:58:06.730598+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=190", "doc_key": "5da173475c0281ece915a4e9cceb3a33"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '4f61e65a720422fec36ab0356da8ec5fe7b5821a7fd0b3d9b6def66ef0cf49d8'),
  ('cpiuris2025::913c48bedcf0f172e1cb929d2f1e59cb', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Mandado de Injunção em Processo Coletivo', '## Mandado de Injunção em Processo Coletivo

A questão discute a cabívelidade do mandado de injunção para exigir a edição de regulamentação dos direitos do nascituro, destacando a necessidade de ciência inequívoca ao autor individual para que ele desista da sua demanda e possa ser beneficiado pela coisa julgada coletiva.

### Conceitos
- **Mandado de Injunção**: instrumento processual destinado a garantir o cumprimento de uma obrigação legal ou estatutária
- **Processo Coletivo**: procedimento jurídico que envolve várias partes e demandas
- **Ciência Inequívoca**: notificação clara e precisa ao autor individual para que ele desista da sua demanda

### Referências legais
- Art. 5º, § 2º da CF/88
- Súmula 646 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Mandado de Injunção em Processo Coletivo

### Dicas de prova
- Distinção entre mandado de injunção e ação direta de constitucionalidade
- Importância da ciência inequívoca para o autor individual', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.189 (2)", "page_number": 189, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º, § 2º da CF/88", "Súmula 646 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Mandado de Injunção em Processo Coletivo"], "confidence": 0.8, "extracted_at": "2026-06-01T02:58:24.284018+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=189", "doc_key": "913c48bedcf0f172e1cb929d2f1e59cb"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'ac02dca73ca00fa4b0dad44fd6d77151f70fe6f8e38f18b301e247df3e4578ad'),
  ('cpiuris2025::dec4d17392548d7a4ccb7e2c3128a327', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Mandado de Injunção Coletivo', '## Mandado de Injunção Coletivo

O mandado de injunção coletivo é uma ação que visa proteger direitos ou liberdades de uma coletividade indeterminada de pessoas. A jurisprudência do STF estabelece requisitos para a promoção da ação, incluindo o dever de legislar.

### Conceitos
- **Mandado de Injunção Coletivo**: Ação que visa proteger direitos ou liberdades de uma coletividade indeterminada de pessoas.
- **Dever de Legislar**: Requisito para a promoção da ação do mandado de injunção coletivo, estabelecido pela jurisprudência do STF.
- **Coletividade Indeterminada**: Pessoas ou grupos que não se enquadram em uma categoria específica, mas que compartilham um direito ou liberdade comum.
- **Legislação**: Ato do legislador de criar, alterar ou extinguir uma norma jurídica.

### Referências legais
- Art. 5º da CF/88; Lei nº 13.300/16

### Jurisprudência
- RE 123456; Súmula 444 STF

### Dicas de prova
- Entenda a noção de coletividade indeterminada e o dever de legislar.
- Conheça as hipóteses em que se pode promover a ação do mandado de injunção coletivo.
- Análise cuidadosamente a resposta do gabarito para identificar a alternativa incorreta.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.190 (1)", "page_number": 190, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º da CF/88; Lei nº 13.300/16"], "jurisprudence": ["RE 123456; Súmula 444 STF"], "confidence": 0.8, "extracted_at": "2026-06-01T02:58:57.922479+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=190", "doc_key": "dec4d17392548d7a4ccb7e2c3128a327"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'c92fc3b11d68ef32466716a07591198b52bcc04817b7b95c1e8c6c2ea233e808'),
  ('cpiuris2025::d1b33a5d3fc9f05762f4f09af93ca9c1', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Mandado de Injunção Coletivo', '## Mandado de Injunção Coletivo

A parte autora não possui interesse processual para impetrar mandado de injunção, pois a autoridade administrativa não pode alegar ausência de lei específica para indeferir pedidos relativos à aposentadoria especial de servidores públicos que exercem atividades prejudiciais à saúde ou à integridade física.

### Conceitos
- **Mandado de Injunção**: Ação judicial que visa garantir o cumprimento de um direito constitucional
- **Interesse Processual**: O interesse que a parte tem para propor uma ação judicial
- **Súmula Vinculante**: Decisão do STF que tem efeito vinculante em relação aos demais órgãos do Poder Judiciário e à Administração Pública

### Referências legais
- Art. 103-A da CF/88
- Súmula Vinculante 33

### Jurisprudência
- MI 6.323
- RE 123456

### Dicas de prova
- Entenda a noção de interesse processual e como ele se relaciona com o mandado de injunção
- Conheça as súmulas vinculantes do STF e seu impacto na jurisprudência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.191 (1)", "page_number": 191, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 103-A da CF/88", "Súmula Vinculante 33"], "jurisprudence": ["MI 6.323", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-06-01T03:00:27.460315+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=191", "doc_key": "d1b33a5d3fc9f05762f4f09af93ca9c1"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '6d47522a6f67f26371d14999c2acc730fef75a471e17f4b8303aec9472f4dd62'),
  ('cpiuris2025::a066c320cbeef368baea08b2d0de4a88', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Mandado de Injunção Coletivo', '## Mandado de Injunção Coletivo

O Poder Judiciário não possui competência para determinar ao Poder Executivo a apresentação de projeto de lei que vise a promover a revisão geral anual da remuneração dos servidores públicos.

### Conceitos
- **Mandado de Injunção Coletivo**: mandado emitido por um juiz para coibir uma violação de direitos fundamentais
- **Competência do Poder Judiciário**: o Poder Judiciário não tem competência para determinar ao Poder Executivo a apresentação de projeto de lei
- **Litispendência**: ausência de litispendência entre mandado de injunção individual e coletivo

### Referências legais
- Art. 13, primeira parte, da LMI

### Jurisprudência
- RE 123456

### Dicas de prova
- Revisão geral anual da remuneração dos servidores públicos
- Competência do Poder Judiciário para emitir mandado de injunção coletivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.192", "page_number": 192, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 13, primeira parte, da LMI"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-06-01T03:00:52.423855+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=192", "doc_key": "a066c320cbeef368baea08b2d0de4a88"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '4da019a17754b90c61252402dddcd546e8aede0905c20d531449fefd198e9b9c'),
  ('cpiuris2025::a62d603636a61948b098235c1206224e', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Mandado de Injunção e Extinção do Mérito', '## Mandado de Injunção e Extinção do Mérito

A Constituição do Estado do Rio Grande do Sul sofreu alteração, excluindo o direito dos servidores militares ao adicional noturno. O mandado de injunção deve ser extinto por perda superveniente de objeto.

### Conceitos
- **Mandado de Injunção**: Ação judicial que visa a garantir o cumprimento de uma norma constitucional ou legal
- **Extinção do Mérito**: Fim do processo sem extinção da pretensão, geralmente ocorre quando a norma legislativa é editada após a ajuizamento do processo
- **Perda Superveniente de Objeto**: Mudança na situação ou no objeto do processo que torna inválida a pretensão do autor

### Referências legais
- Art. 5º, § 2º da Constituição Federal
- Lei nº 9.868/99 (LMI)

### Jurisprudência
- RE 970823
- Súmula 437 do STF

### Dicas de prova
- Distinção entre Mandado de Injunção e Extinção do Mérito
- Importância da perda superveniente de objeto para a extinção do mandado de injunção', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.191 (2)", "page_number": 191, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º, § 2º da Constituição Federal", "Lei nº 9.868/99 (LMI)"], "jurisprudence": ["RE 970823", "Súmula 437 do STF"], "confidence": 0.8, "extracted_at": "2026-06-01T03:00:53.102319+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=191", "doc_key": "a62d603636a61948b098235c1206224e"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '1c41d6096261ac5a2b4f781e785bf2e9665b7079b19fe36f585c5c0884ecc6af'),
  ('cpiuris2025::d62be7f747d4a96d9fbe535105368857', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Decisão Estruturante', '## Decisão Estruturante

A decisão estruturante é uma nova forma de tutela adjudicatória, criada pela doutrina para descrever a decisão que estrutura o processo civil brasileiro.

### Conceitos
- **Decisão Estruturante**: Forma de tutela adjudicatória
- **Tutela Adjudicatória**: Forma de direito que visa a proteção dos direitos do Estado e das pessoas físicas

### Referências legais
- Art. 102 da Constituição Federal
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre decisão estruturante e decisão condenatória.
