  ('cpiuris2025::4f9535c696fbe6fa78225fac1a927abb', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Problema/Litígio Estrutural', '## Problema/Litígio Estrutural

O problema estrutural é um estado de coisas que não é considerado ideal e que necessita de reestruturação/reorganização das instituições envolvidas para sanar a violação do direito material.

### Conceitos
- **Problema Estrutural**: Estado de coisas que não é considerado ideal e que necessita de reestruturação/reorganização das instituições envolvidas.
- **Desconformidade Estruturada**: Situação de ilicitude contínua e permanente ou situação de desconformidade não propriamente ilícita

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- Brown II
- RE 123456

### Dicas de prova
- Entenda a distinção entre problema estrutural e desconformidade.
- Conheça as características de um estado de coisas que necessita de reestruturação/reorganização.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.195 (1)", "page_number": 195, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["Brown II", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-06-01T03:02:45.290451+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=195", "doc_key": "4f9535c696fbe6fa78225fac1a927abb"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '84ffab92e331fffab48ed3dbc0d61792b4ee0d9a22dd5d52000b2b49c57d5a91'),
  ('cpiuris2025::116b336b3a193867880b07d4b40b5212', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Litígio Estrutural', '## Litígio Estrutural

O litígio estrutural é um tipo de processo que busca sanar problemas estruturais, resultantes da violação massiva de direitos fundamentais. Ele envolve a reestruturação de determinada organização social ou política para remover o estado de desconformidade e solucionar o problema.

### Conceitos
- **Litígio Estrutural**: Processo que busca sanar problemas estruturais resultantes da violação massiva de direitos fundamentais.
- **Problemas Estruturais**: Situações que exigem a reestruturação de uma organização social ou política para remover o estado de desconformidade e solucionar o problema.
- **Direitos Fundamentais**: Direitos assegurados constitucionalmente que são violados em larga escala.

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456
- Brown vs. Board of Education of Topeka

### Dicas de prova
- Entenda a importância dos direitos fundamentais e como eles podem ser violados em larga escala.
- Conheça o caso Brown vs. Board of Education of Topeka e sua influência na concepção de processo estrutural.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.194 (1)", "page_number": 194, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456", "Brown vs. Board of Education of Topeka"], "confidence": 0.8, "extracted_at": "2026-06-01T03:03:03.478194+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=194", "doc_key": "116b336b3a193867880b07d4b40b5212"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'e4ebf8d4da12f7961a8e65731fbb7bbbc0bf73935d08783ee7d7c259783c17ef'),
  ('cpiuris2025::5b377e38b2fc310397e588d9113f9cd9', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Obrigação em Processo Coletivo', '## Obrigação em Processo Coletivo

