  ('cpiuris2025::cbc5a038ccda2de3309355da142c2e12', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Processo estrutural', '## Processo estrutural

O processo estrutural é um tipo de litígio que visa corrigir problemas estruturais por meio da reestruturação das instituições envolvidas.

### Conceitos
- **Processo estrutural**: litígio que visa corrigir problemas estruturais
- **Litígio estrutural**: disputa que causa ou fomenta violações na estrutura de uma instituição
- **Reestruturação**: mudança nas instituições envolvidas para corrigir problemas estruturais

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre processo estrutural e litígio estrutural.
