  ('cpiuris2025::fc248ea2768bf00a14ecf74b23384096', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Litígio Estrutural', '## Litígio Estrutural

O litígio estrutural envolve problemas de difícil solução que afetam múltiplos interesses sociais, exigindo intervenção judicial para implementar direitos e valores.

### Conceitos
- **Litígio Estrutural**: Problema de difícil solução que afeta múltiplos interesses sociais
- **Processo Estrutural**: Instrumento para solucionar problemas estruturais, buscando alterar o estado de desconformidade e alcançar o estado ideal
- **Policêntrico**: Relacionado a uma multiplicidade de interesses e diversos setores da comunidade

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
