  ('cpiuris2025::a430321b511e819b3a8c38d316a2f0d1', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Decisão Estrutural', '## Decisão Estrutural

A decisão estrutural é aquela que constata o estado de desconformidade e define o modo pelo qual se reestabelecerá o estado ideal, com conteúdo complexo que inclui norma jurídica aberta e estrutura deôntica de uma norma-princípio.

### Conceitos
- **Decisão Estrutural**: constata o estado de desconformidade e define o modo pelo qual se reestabelecerá o estado ideal
- **Norma Jurídica Aberta**: tem conteúdo aberto e indica um resultado a ser alcançado – uma meta, um objetivo
- **Estrutura deôntica de uma Norma-Princípio**: assume a estrutura deôntica de uma norma-princípio, indicando um resultado a ser alcançado

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Tema repetitivo ...

