  ('cpiuris2025::b9ddd7d4ff3bfd498d217a818af3898f', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Litigio Estrutural', '## Litigio Estrutural

O processo estrutural pode ser marcado por ''ciclos de decisões'' devido à necessidade de providências posteriores para tutelar os direitos envolvidos. Exige-se uma sequência de decisões para efetivação da tutela perseguida.

### Conceitos
- **Litigio Estrutural**: Processo que exige uma sequência de decisões para efetivação da tutela perseguida
- **Ciclos de Decisões**: Necessidade de se deslocar parte do processo decisório para etapas posteriores
- **Provimentos em Cascata**: Decisões que solucionam questões ulteriores que surjam na implementação de uma decisão anterior

### Referências legais
- Art. 102 do Código de Processo Civil
- Súmula 656 do Supremo Tribunal Federal

### Jurisprudência
- RE 123456
- Tema repetitivo: intervenção do Poder Judiciário em políticas públicas

### Dicas de prova
- Entenda a noção de litigio estrutural e seus ciclos de decisões
