  ('cpiuris2025::102215a05974aea5d3feba40838ee00e', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Intervenção do Poder Judiciário na gestão de serviços públicos', '## Intervenção do Poder Judiciário na gestão de serviços públicos

O texto destaca a necessidade de estabelecer parâmetros para a atuação judicial em políticas públicas de saúde, garantindo critérios de razoabilidade e eficiência.

### Conceitos
- **Intervenção do Poder Judiciário**: Ação do Poder Judiciário na gestão de serviços públicos
- **Políticas públicas de saúde**: Medidas tomadas pelo Estado para garantir o acesso universal e igualitário às ações e serviços de saúde
- **Razoabilidade e eficiência**: Critérios para avaliar a justiça e eficácia das políticas públicas
- **Discricionariedade administrativa**: Espaço de liberdade do administrador para tomar decisões
- **Alocação racional dos recursos públicos**: Uso eficiente e justo dos recursos disponíveis

### Referências legais
- Art. 37 da Constituição Federal
- Súmula 632 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: intervenção do Poder Judiciário em políticas públicas

