  ('cpiuris2025::f8a7d8c41720218fa875ec4e9dfe13cf', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Caracterização do Processo Estrutural', '## Caracterização do Processo Estrutural

O processo estrutural é caracterizado pela existência de um problema estrutural, busca pela transição do estado de desconformidade para o estado ideal a partir de uma reestruturação.

### Conceitos
- **Problema estrutural**: elemento fundamental para caracterizar um processo como estrutural
- **Reestruturação**: mudança socialmente relevante que visa melhorar a situação de um grupo ou indivíduo
- **Procedimento bifásico**: fase inicial para reconhecer e definir o problema estrutural, seguida de uma fase de reestruturação
- **Flexibilidade intrínseca**: possibilidade de adoção de formas atípicas de intervenção de terceiros e medidas executivas

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a importância do problema estrutural no processo estrutural
- Conheça as fases do procedimento bifásico e sua relevância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.199 (2)", "page_number": 199, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-06-01T03:09:51.309437+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=199", "doc_key": "f8a7d8c41720218fa875ec4e9dfe13cf"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '84b48a1377d2cf82f9a6a290134b256386f4e3b7ee4eb4e8750e85e1dbcaf370')
